window.CHEM_DATA = {"fields": [{"field": "theory", "fieldLabel": "理論", "lectures": [{"id": "th-01", "title": "物質と原子", "book": "理論編 第1講"}, {"id": "th-02", "title": "電子配置とイオン", "book": "理論編 第2講"}, {"id": "th-03", "title": "化学結合と原子量", "book": "理論編 第3講"}, {"id": "th-04", "title": "結晶構造", "book": "理論編 第4講"}, {"id": "th-05", "title": "共有結合結晶と分子", "book": "理論編 第5講"}, {"id": "th-06", "title": "濃度と量的関係", "book": "理論編 第6講"}, {"id": "th-07", "title": "酸と塩基", "book": "理論編 第7講"}, {"id": "th-08", "title": "塩の反応と滴定", "book": "理論編 第8講"}, {"id": "th-09", "title": "酸化還元", "book": "理論編 第9講"}, {"id": "th-10", "title": "電池", "book": "理論編 第10講"}, {"id": "th-11", "title": "電気分解と工業的製法", "book": "理論編 第11講"}, {"id": "th-12", "title": "気体", "book": "理論編 第12講"}, {"id": "th-13", "title": "状態変化と蒸気圧", "book": "理論編 第13講"}, {"id": "th-14", "title": "溶液とコロイド", "book": "理論編 第14講"}, {"id": "th-15", "title": "熱化学", "book": "理論編 第15講"}, {"id": "th-16", "title": "反応速度と化学平衡", "book": "理論編 第16講"}, {"id": "th-17", "title": "電離平衡と溶解度積", "book": "理論編 第17講"}], "cards": [{"id": "card-th-01", "lecture": "th-01", "name": "物質の分類と同素体", "kind": "概念", "points": [{"label": "純物質と混合物", "text": "1種の化学式で書けるのが純物質（単体・化合物）。塩酸や空気のように複数の物質が混ざったものが混合物。", "blind": true, "masks": ["純物質", "混合物"]}, {"label": "同素体（S・C・O・P）", "text": "同じ元素の単体で性質が異なるもの。S（斜方・単斜・ゴム状）、C（ダイヤ・黒鉛・フラーレン）、O（酸素・オゾン）、P（黄リン・赤リン）。", "blind": true, "masks": ["斜方・単斜・ゴム状", "ダイヤ・黒鉛・フラーレン", "酸素・オゾン", "黄リン・赤リン"]}, {"label": "分離法", "text": "沸点の差を利用する蒸留、溶解度の差を利用する再結晶、昇華性の有無を利用する昇華法などがある。", "blind": true, "masks": ["蒸留", "再結晶", "昇華法"]}, {"label": "原子の構造", "text": "原子番号＝陽子数＝電子数。質量数＝陽子数＋中性子数。中性子数が異なるものは同位体。 ", "blind": true, "masks": ["原子番号＝陽子数＝電子数", "質量数＝陽子数＋中性子数", "同位体"]}], "note": "まとめノート理論編 第1講"}, {"id": "card-th-02", "lecture": "th-02", "name": "電子配置と周期性", "kind": "概念", "points": [{"label": "電子殻の収容数", "text": "内側からK(2), L(8), M(18), N(32)個。最大収容数は2n^2だが、最外殻には8個までしか入らない。", "blind": true, "masks": ["K(2), L(8), M(18), N(32)", "2n^2", "8個"]}, {"label": "半径の大小", "text": "同じ電子配置のイオンでは原子番号が大きいほど小さい。周期表では左下ほど大きく、右上ほど小さい。", "blind": true, "masks": ["大きいほど小さい", "左下ほど大きく、右上ほど小さい"]}, {"label": "イオン化エネルギーと電子親和力", "text": "IEは右上ほど大きく（最大He）、電子を引き抜くエネルギー。EAは電子を受け取るときに放出するエネルギー（17族で大）。", "blind": true, "masks": ["最大He", "17族"]}], "note": "まとめノート理論編 第2講"}, {"id": "card-th-03", "lecture": "th-03", "name": "化学結合と物質量", "kind": "概念", "points": [{"label": "結合の種類", "text": "金属+非金属はイオン結合、金属同士は金属結合、非金属同士は共有結合。NH4Clは非金属のみだがイオン結合。 ", "blind": true, "masks": ["イオン結合", "金属結合", "共有結合"]}, {"label": "共有結合結晶（5つ）", "text": "ダイヤモンド、黒鉛、Si、SiO2、SiC。非常に硬く融点が高い。これら以外で共有結合するものは分子を作る。", "blind": true, "masks": ["ダイヤモンド、黒鉛、Si、SiO2、SiC"]}, {"label": "物質量 mol", "text": "1 mol = 6.02*10^23個 = 標準状態の気体22.4 L = 原子量・分子量・式量にgをつけた質量。", "blind": true, "masks": ["6.02*10^23個", "22.4 L"]}], "note": "まとめノート理論編 第3講"}, {"id": "card-th-04", "lecture": "th-04", "name": "体心立方格子", "kind": "概念", "points": [{"label": "構造", "text": "立方体の各頂点に粒子があり、立体の中心にも1個の粒子がある構造。", "blind": true, "masks": ["中心にも1個の粒子"]}, {"label": "粒子数と配位数", "text": "単位格子あたりの粒子数は2個（1/8×8 + 1）。配位数は8。", "blind": true, "masks": ["粒子数は2個", "配位数は8"]}, {"label": "原子半径rの関係", "text": "原子は立体対角線上で接触しており、4r = √3 a（aは格子定数）が成り立つ。", "blind": true, "masks": ["4r = √3 a"]}, {"label": "充填率", "text": "単位格子の体積のうち粒子が占める割合は約68%である。", "blind": true, "masks": ["約68%"]}], "note": "まとめノート理論編 第4講"}, {"id": "card-th-05", "lecture": "th-05", "name": "共有結合結晶", "kind": "概念", "points": [{"label": "定義", "text": "原子が共有結合で次々と網目状につながり、1つの巨大な分子のようになった結晶。", "blind": true, "masks": ["網目状"]}, {"label": "代表例", "text": "ダイヤモンド、黒鉛、ケイ素Si、二酸化ケイ素SiO2、炭化ケイ素SiC。", "blind": true, "masks": ["ダイヤモンド、黒鉛、ケイ素Si、二酸化ケイ素SiO2、炭化ケイ素SiC"]}, {"label": "ダイヤモンド型", "text": "1個の原子が正四面体の中心と頂点の関係で4個の原子と結合。単位格子の粒子数は8。", "blind": true, "masks": ["4個の原子", "粒子数は8"]}, {"label": "性質", "text": "融点が極めて高く非常に硬い。黒鉛を除き、電気伝導性はない。", "blind": true, "masks": ["黒鉛を除き", "電気伝導性はない"]}], "note": "まとめノート理論編 第5講"}, {"id": "card-th-06", "lecture": "th-06", "name": "濃度の種類と換算", "kind": "概念", "points": [{"label": "質量パーセント濃度とモル濃度", "text": "質量%は「溶質の質量/溶液の質量」、モル濃度は「溶質の物質量/溶液の体積」で表す。変換には密度を用いた溶液質量の算出が必須。", "blind": true, "masks": ["溶質の質量/溶液の質量", "溶質の物質量/溶液の体積"]}, {"label": "質量モル濃度", "text": "「溶質の物質量(mol)/溶媒の質量(kg)」で表す。分母が「溶液」ではなく「溶媒」である点に注意し、溶液の質量から溶質の質量を引いて求める。", "blind": true, "masks": ["溶質の物質量(mol)/溶媒の質量(kg)"]}, {"label": "希釈の原則", "text": "溶液を薄めても溶質の物質量（粒の数）は変化しない。c1V1 = c2V2（濃度×体積＝一定）の関係が成り立つ。", "blind": true, "masks": ["c1V1 = c2V2"]}, {"label": "化学反応式の係数比", "text": "反応式の係数比は物質量(mol)の比を表す。気体のみの反応であれば、同温・同圧での体積比とも一致する。", "blind": true, "masks": ["物質量(mol)の比", "体積比"]}], "note": "まとめノート理論編 第6講"}, {"id": "card-th-07", "lecture": "th-07", "name": "酸・塩基の定義とpH", "kind": "概念", "points": [{"label": "ブレンステッドの定義", "text": "H+を与える物質が酸、H+を受け取る物質が塩基。相手次第で役割が変わる両性物質（H2O, HCO3-など）も存在する。", "blind": true, "masks": ["H+を与える物質が酸", "H+を受け取る物質が塩基"]}, {"label": "pHの計算公式", "text": "[H+] = 濃度(mol/L) × 価数 × 電離度(α)。強酸・強塩基は α=1 とし、弱酸・弱塩基は与えられた α を用いる。", "blind": true, "masks": ["[H+] = 濃度(mol/L) × 価数 × 電離度(α)"]}, {"label": "水のイオン積とpOH", "text": "25℃において Kw = [H+][OH-] = 1.0×10^-14。塩基のpHを求める際は、まず[OH-]からpOHを出し、14から引くのが基本。", "blind": true, "masks": ["1.0×10^-14"]}, {"label": "中和の量的関係", "text": "酸の出したH+の総量 ＝ 塩基の受け取ったH+の総量。中和計算では弱酸であっても電離度 α は考慮せず、全量で計算する。", "blind": true, "masks": ["H+の総量", "全量で計算する"]}], "note": "まとめノート理論編 第7講"}, {"id": "card-th-08", "lecture": "th-08", "name": "塩の反応と中和滴定", "kind": "概念", "points": [{"label": "塩の反応の仕組み", "text": "弱酸や弱塩基由来のイオンは水中でH+やOH-を受け取って元の分子に戻りやすく、これが遊離反応や加水分解の正体である。", "blind": true, "masks": ["遊離反応や加水分解"]}, {"label": "器具の扱い", "text": "濃度がずれると困るホールピペットとビュレットは共洗いが必要だが、メスフラスコとコニカルビーカーはぬれたまま使ってよい。", "blind": true, "masks": ["ホールピペットとビュレット", "メスフラスコとコニカルビーカー"]}, {"label": "指示薬の選択", "text": "中和点での液性からpHジャンプの位置を判断し、変色域（MO: 3-4.5, PP: 8-10）がジャンプ内に重なるものを選ぶ。", "blind": true, "masks": ["MO: 3-4.5, PP: 8-10"]}, {"label": "特殊な滴定", "text": "気体は過剰な酸・塩基に吸収させる逆滴定を行い、炭酸ナトリウムはNaHCO3を経由する二段滴定で定量する。", "blind": true, "masks": ["逆滴定", "二段滴定"]}], "note": "まとめノート理論編 第8講"}, {"id": "card-th-09", "lecture": "th-09", "name": "酸化還元と酸化数", "kind": "概念", "points": [{"label": "定義", "text": "酸化還元は電子 e- の移動が起こる反応である。酸化は電子を失うこと、還元は電子を得ることを指す。", "blind": true, "masks": ["電子を失うこと", "電子を得ること"]}, {"label": "酸化数", "text": "電気陰性度の大きい方に電子を帰属させた際の電荷。単体は0、化合物中の総和は0、Hは+1、Oは-2を基準に算出する。", "blind": true, "masks": ["単体は0", "Hは+1", "Oは-2"]}, {"label": "酸化剤と還元剤", "text": "相手を酸化し自身は還元されるのが酸化剤、相手を還元し自身は酸化されるのが還元剤である。名称は相手への働きを示す。", "blind": true, "masks": ["相手を酸化し自身は還元されるのが酸化剤", "相手を還元し自身は酸化されるのが還元剤"]}, {"label": "反応の判断", "text": "単体が現れる反応は酸化還元の可能性が高い。最終的には原子の酸化数に変化があるかどうかで判断する。", "blind": true, "masks": ["酸化数に変化があるかどうか"]}], "note": "まとめノート理論編 第9講"}, {"id": "card-th-10", "lecture": "th-10", "name": "電池の原理と実用電池", "kind": "概念", "points": [{"label": "電池の仕組み", "text": "負極（イオン化傾向大）が電子を放出し、正極（イオン化傾向小）側で電子を受け取ることで電流を取り出す装置。", "blind": true, "masks": ["イオン化傾向大", "イオン化傾向小"]}, {"label": "分極", "text": "ボルタ電池等で正極にH2が付着し起電力が低下する現象。酸化剤である減極剤（H2O2など）の添加で一時的に防げる。", "blind": true, "masks": ["H2が付着", "減極剤"]}, {"label": "鉛蓄電池", "text": "負極Pb、正極PbO2、電解液に希硫酸を用いる二次電池。放電で両極ともPbSO4の沈殿となり、硫酸濃度は低下する。", "blind": true, "masks": ["負極Pb、正極PbO2", "希硫酸", "PbSO4"]}, {"label": "燃料電池", "text": "水素と酸素の反応エネルギーを電気として取り出す。負極でH2が酸化、正極でO2が還元され、全体で水が生成する。", "blind": true, "masks": ["H2が酸化", "O2が還元", "水が生成する"]}], "note": "まとめノート理論編 第10講"}, {"id": "card-th-11", "lecture": "th-11", "name": "電気分解の反応マニュアル", "kind": "概念", "points": [{"label": "陰極の反応判断", "text": "溶液中の陽イオンがZn以下の金属イオンなら金属が析出、H+ならH2が発生。いずれもいなければH2Oが反応しH2とOH-が生じる。", "blind": true, "masks": ["金属が析出", "H+ならH2が発生"]}, {"label": "陽極の反応判断", "text": "電極がPt・Au・C以外なら電極自身が溶け出す。電極が不活性なら、ハロゲン化物イオン、OH-、H2Oの順に反応を検討する。", "blind": true, "masks": ["電極自身が溶け出す", "ハロゲン化物イオン、OH-、H2Oの順"]}, {"label": "電気量の計算", "text": "Q(C) = I(A) × t(s) で求めた電気量をファラデー定数で割り、e-の物質量(mol)を基準に各極の物質の変化量を係数比で求める。", "blind": true, "masks": ["Q(C) = I(A) × t(s)", "ファラデー定数"]}, {"label": "イオン交換膜法", "text": "陽イオン交換膜で仕切り、陽極にNaCl、陰極に希NaOHを入れる。Na+のみを透過させ、陰極側で高純度のNaOH水溶液を得る製法。", "blind": true, "masks": ["Na+のみを透過させ", "高純度のNaOH水溶液"]}], "note": "まとめノート理論編 第11講"}, {"id": "card-th-12", "lecture": "th-12", "name": "気体の状態方程式と実在気体", "kind": "概念", "points": [{"label": "状態方程式", "text": "PV = nRT。温度Tは常に絶対温度(K = t + 273)を用いる。分子量Mを含む変形版 PV = (w/M)RT も頻出。", "blind": true, "masks": ["PV = nRT", "K = t + 273"]}, {"label": "分圧の法則", "text": "混合気体の全圧は各成分の分圧の和に等しく、分圧の比は物質量(mol)の比に等しい。また成分ごとの体積で考える分体積もある。", "blind": true, "masks": ["各成分の分圧の和", "物質量(mol)の比"]}, {"label": "理想気体と実在気体", "text": "実在気体は分子間力と分子自身の体積を持つ。これらが無視できる「高温・低圧」の条件で、実在気体は理想気体の挙動に近づく。", "blind": true, "masks": ["高温・低圧"]}, {"label": "平均分子量", "text": "混合気体では、各成分の分子量にモル分率を掛けたものの和を平均分子量とする。空気(N2:O2=4:1)の平均分子量は約28.8。", "blind": true, "masks": ["約28.8"]}], "note": "まとめノート理論編 第12講"}, {"id": "card-th-13", "lecture": "th-13", "name": "水の状態図", "kind": "概念", "points": [{"label": "三重点", "text": "融解曲線・蒸気圧曲線・昇華圧曲線の3本が交わる点。固体・液体・気体の3つが共存できる、ただ1つの温度・圧力。", "blind": true, "masks": ["固体・液体・気体の3つが共存できる"]}, {"label": "融解曲線の傾き", "text": "水だけが左上がり。氷の体積が液体の水より大きいため。加圧すると水の融点は下がり、一般の物質では上がる。", "blind": true, "masks": ["水だけが左上がり", "水の融点は下がり"]}, {"label": "蒸気圧は分圧", "text": "混合気体の中で蒸気の圧力は分圧として扱う。液体が共存する状態では、蒸気の分圧はその温度での蒸気圧に等しい。", "blind": true, "masks": ["蒸気圧に等しい"]}, {"label": "加熱曲線", "text": "融解・沸騰の最中は温度が一定。加えた熱が分子間力を切るために使われ、熱運動を激しくするためには使われないから。", "blind": true, "masks": ["温度が一定"]}], "note": "まとめノート理論編 第13講"}, {"id": "card-th-14", "lecture": "th-14", "name": "溶解度", "kind": "概念", "points": [{"label": "定義", "text": "一定温度で水100gに溶ける溶質の最大の質量(g)。単位はg/水100g。", "blind": true, "masks": ["水100g", "最大の質量(g)"]}, {"label": "飽和溶液の比", "text": "溶解度Sの飽和溶液では、溶質:水:溶液=S:100:100+S。量をどれだけ取ってもこの比は変わらない。", "blind": true, "masks": ["S:100:100+S"]}, {"label": "冷却による析出", "text": "水の量は変わらない。析出量は溶解度の差S(高温)-S(低温)で求まる。析出後の溶液は低温での飽和溶液。", "blind": true, "masks": ["溶解度の差S(高温)-S(低温)"]}, {"label": "水和物の析出", "text": "CuSO4・5H2Oのように結晶水を含む結晶が析出すると、溶液から水も出ていく。溶解度の差は使えず、析出後の飽和溶液の比で式を作る。", "blind": true, "masks": ["CuSO4・5H2O", "水も出ていく"]}], "note": "まとめノート理論編 第14講"}, {"id": "card-th-15", "lecture": "th-15", "name": "反応熱", "kind": "概念", "points": [{"label": "燃焼熱・生成熱", "text": "燃焼熱は物質1molが完全燃焼するときの発熱量。生成熱は単体から化合物1molが生じるときの熱量。", "blind": true, "masks": ["完全燃焼するときの発熱量", "単体から化合物1molが生じるときの熱量"]}, {"label": "熱化学方程式の符号", "text": "吸熱反応は式の中で-を付ける。例：H2(気)=2H(気)-436kJ(結合エネルギー436kJ/mol)。", "blind": true, "masks": ["H2(気)=2H(気)-436kJ"]}, {"label": "ヘスの法則", "text": "反応熱は反応経路によらず、はじめと終わりの状態だけで決まる。格子エネルギーなど直接測れない熱も、2つのルートを等しく置いて求める。", "blind": true, "masks": ["はじめと終わりの状態だけで決まる"]}, {"label": "格子エネルギー", "text": "NaClの格子エネルギーは本書の要点では771kJ/molに統一する。問題ごとに熱データが与えられている場合は、そのデータで計算した値が答えになる。", "blind": true, "masks": ["771kJ/mol"]}], "note": "まとめノート理論編 第15講"}, {"id": "card-th-16", "lecture": "th-16", "name": "化学平衡", "kind": "概念", "points": [{"label": "平衡定数K", "text": "生成物の濃度の積(係数を指数)÷反応物の濃度の積(係数を指数)。Kは温度だけで決まり、濃度・圧力・触媒では変わらない。", "blind": true, "masks": ["温度だけで決まり"]}, {"label": "ルシャトリエの原理", "text": "平衡状態にある系に変化を加えると、その変化を打ち消す向きに平衡が移動する。温度・圧力・濃度の変化で判断する。", "blind": true, "masks": ["打ち消す向きに"]}, {"label": "触媒", "text": "触媒は活性化エネルギーを下げて反応を速くするが、反応熱も平衡定数も変えない。平衡の位置は動かない。", "blind": true, "masks": ["反応熱も平衡定数も変えない"]}, {"label": "活性化エネルギー", "text": "反応物から活性化状態までの高さ。エネルギー図では出発側から山頂までの高さで読む。", "blind": true, "masks": ["活性化状態までの高さ"]}], "note": "まとめノート理論編 第16講"}, {"id": "card-th-17", "lecture": "th-17", "name": "電離平衡と溶解度積", "kind": "概念", "points": [{"label": "溶解度積Ksp", "text": "難溶性塩の溶解平衡の平衡定数。例：CaF2ではKsp=[Ca2+][F-]^2。イオン積がKspを超えると沈殿する。", "blind": true, "masks": ["Ksp=[Ca2+][F-]^2", "沈殿する"]}, {"label": "緩衝溶液", "text": "弱酸とその塩(または弱塩基とその塩)の混合溶液。少量の酸・塩基を加えてもpHがほぼ変わらない。例：ギ酸とギ酸ナトリウム。", "blind": true, "masks": ["弱酸とその塩(または弱塩基とその塩)", "ギ酸とギ酸ナトリウム"]}, {"label": "塩の加水分解", "text": "塩を構成するイオンが水と反応して液性を示す。NH4Cl水溶液は酸性(弱塩基の塩)。酸性か塩基性かは、塩を作る酸と塩基の強さで決まる。", "blind": true, "masks": ["NH4Cl水溶液は酸性(弱塩基の塩)"]}], "note": "まとめノート理論編 第17講"}], "questions": [{"id": "q-th-001", "lecture": "th-01", "unit": "物質の分類", "type": "choice", "q": "次の物質のうち、混合物に分類されるものの組み合わせとして正しいものはどれか。①石油 ②ドライアイス ③塩酸 ④オゾン", "choices": ["①、②", "③、④", "①、③", "②、③"], "answer": 2, "hint": "石油は炭化水素の混合物、塩酸は塩化水素の水溶液です。", "book": "理論編 第1講"}, {"id": "q-th-002", "lecture": "th-01", "unit": "分離法", "type": "choice", "q": "蒸留装置の操作として、不適切なものはどれか。", "choices": ["急激な沸騰を防ぐため、枝付きフラスコに沸騰石を入れる。", "冷却効率を上げるため、リービッヒ冷却器の冷却水は上口から下口へ流す。", "蒸気の温度を正しく測るため、温度計の球部を枝分かれの部分に合わせる。", "装置内の圧力が上昇して破損するのを防ぐため、受器の栓を密閉しない。"], "answer": 1, "hint": "冷却水は、より冷たい水が溜まるように下から上へ流します。", "book": "理論編 第1講"}, {"id": "q-th-003", "lecture": "th-01", "unit": "原子の構造", "type": "choice", "q": "放射性同位体の崩壊において、質量数が変化しないものはどれか。", "choices": ["アルファ崩壊", "中性子放出", "ベータ崩壊", "核分裂"], "answer": 2, "hint": "中性子が陽子と電子に変わる変化では、原子番号は増えますが質量数は変わりません。", "book": "理論編 第1講"}, {"id": "q-th-004", "lecture": "th-02", "unit": "イオンの半径", "type": "choice", "q": "次のイオンを半径が「大きい順」に並べたとき、正しいものはどれか。O2-、F-、Na+、Mg2+", "choices": ["F- > O2- > Mg2+ > Na+", "Mg2+ > Na+ > F- > O2-", "Na+ > Mg2+ > O2- > F-", "O2- > F- > Na+ > Mg2+"], "answer": 3, "hint": "電子配置が同じ場合、原子番号が大きいほど原子核が電子を強く引きつけます。", "book": "理論編 第2講"}, {"id": "q-th-005", "lecture": "th-02", "unit": "電子親和力", "type": "choice", "q": "電子親和力に関する記述として正しいものはどれか。", "choices": ["電子親和力が大きい原子ほど、陽イオンになりやすい。", "第17族元素の中では、塩素(Cl)の値が例外的にフッ素より大きい。", "第17族元素（ハロゲン）の中では、フッ素(F)の値が最大である。", "一般に、同じ周期では希ガスが最大の電子親和力を持つ。"], "answer": 1, "hint": "Fは原子半径が小さく電子間の反発が大きいため、Clが最大となります。", "book": "理論編 第2講"}, {"id": "q-th-006", "lecture": "th-02", "unit": "周期表の性質", "type": "choice", "q": "第一イオン化エネルギーの周期的な変化を示すグラフの特徴として正しいものはどれか。", "choices": ["第1族元素で最大値となり、第18族元素で最小値となる。", "遷移元素の区間では、原子番号とともに急激に増大する。", "同じ周期内では、右に行くほど核からの距離が遠くなるため減少する。", "第18族元素で最大値となり、第1族元素で最小値となる。"], "answer": 3, "hint": "最も電子を引き抜きにくい安定な配置を持つのはどの族でしょうか。", "book": "理論編 第2講"}, {"id": "q-th-007", "lecture": "th-03", "unit": "化学結合", "type": "choice", "q": "次の物質のうち、非金属元素のみで構成されているが、イオン結合によって結晶を作っているものはどれか。", "choices": ["NH4Cl", "SiO2", "SiC", "CO2"], "answer": 0, "hint": "アンモニウムイオンを含む物質は、非金属同士でもイオン結合を形成します。", "book": "理論編 第3講"}, {"id": "q-th-008", "lecture": "th-03", "unit": "なし", "type": "numeric", "q": "マグネシウムの同位体の相対質量と存在比は、24Mg=23.99(79.0%)、25Mg=24.99(10.0%)、26Mg=25.98(11.0%)である。マグネシウムの原子量を小数第2位まで求めよ。", "answer": 24.31, "tolerance": 0.01, "hint": "各相対質量にそれぞれの存在比（割合）をかけて合計します。", "book": "理論編 第3講"}, {"id": "q-th-009", "lecture": "th-03", "unit": "物質量", "type": "choice", "q": "標準状態で11.2 Lを占める窒素ガス N2 (原子量 N=14.0) の質量として、正しいものはどれか。", "choices": ["7.0 g", "56.0 g", "28.0 g", "14.0 g"], "answer": 3, "hint": "まず11.2 Lが何molにあたるかを計算し、それに分子量をかけます。", "book": "理論編 第3講"}, {"id": "q-th-010", "lecture": "th-04", "unit": "結晶構造", "type": "choice", "q": "体心立方格子の単位格子1個に含まれる粒子の数と、1個の粒子に接触している最近接粒子の数（配位数）の組み合わせとして正しいものはどれか。", "choices": ["4個、12", "2個、12", "2個、8", "4個、8"], "answer": 2, "hint": "頂点の1/8個分が8か所と、中心に丸ごと1個あります。", "book": "理論編 第4講"}, {"id": "q-th-011", "lecture": "th-04", "unit": "結晶構造", "type": "choice", "q": "面心立方格子（格子定数a）において、原子半径rとaの関係式として正しいものはどれか。原子は面の対角線上で接触しているものとする。", "choices": ["r = (√2/2)a", "r = (√2/4)a", "r = (√3/4)a", "r = a/2"], "answer": 1, "hint": "面の対角線の長さ√2 aの上に、半径4つ分（4r）が並びます。", "book": "理論編 第4講"}, {"id": "q-th-012", "lecture": "th-04", "unit": "結晶構造", "type": "choice", "q": "塩化ナトリウム型（NaCl型）のイオン結晶において、陽イオン半径をr+、陰イオン半径をr-、格子定数をaとする。イオンが立方体の一辺上で隙間なく接触しているとき、正しい関係式はどれか。", "choices": ["2(r+ + r-) = a", "2(r+ + r-) = √3 a", "r+ + r- = √2 a", "r+ + r- = a"], "answer": 0, "hint": "一辺の上に、陰イオンの半径、陽イオンの直径、陰イオンの半径が並びます。", "book": "理論編 第4講"}, {"id": "q-th-013", "lecture": "th-05", "unit": "共有結合結晶と分子", "type": "choice", "q": "アンモニアNH3の分子の形と、中心にある窒素原子のまわりの電子対（共有電子対と非共有電子対の合計）の数の組み合わせとして正しいものはどれか。", "choices": ["正四面体、4", "三角錐、4", "正三角形、3", "折れ線、4"], "answer": 1, "hint": "電子対は4方向に広がりますが、水素原子があるのはそのうち3方向です。", "book": "理論編 第5講"}, {"id": "q-th-014", "lecture": "th-05", "type": "numeric", "q": "ケイ素Si（原子量28）はダイヤモンド型の結晶構造をとり、単位格子の一辺の長さは 5.4×10^-8 cmである。単位格子の中にSi原子が8個含まれるとき、ケイ素の密度は何 g/cm3 か。小数第1位まで求めよ。アボガドロ定数を 6.0×10^23 /mol、5.4の3乗を157とする。", "answer": 2.4, "unit": "g/cm3", "tolerance": 0.1, "hint": "(原子量/NA × 粒子数) で単位格子の質量を出し、体積で割ります。", "book": "理論編 第5講"}, {"id": "q-th-015", "lecture": "th-05", "unit": "共有結合結晶と分子", "type": "choice", "q": "次の16族元素の水素化合物のうち、最も沸点が高い物質はどれか。", "choices": ["H2O", "H2Se", "H2S", "H2Te"], "answer": 0, "hint": "分子量は最小ですが、分子間に非常に強い水素結合がはたらきます。", "book": "理論編 第5講"}, {"id": "q-th-016", "lecture": "th-06", "unit": "mol/L", "type": "numeric", "q": "質量パーセント濃度 49%、密度 1.4 g/cm3 の硫酸 H2SO4 (式量 98) 水溶液がある。この水溶液のモル濃度は何 mol/L か。", "answer": 7.0, "tolerance": 0.1, "hint": "水溶液 1.0 L (1000 mL) の質量を密度から求め、その中の溶質の質量を計算しましょう。", "book": "理論編 第6講"}, {"id": "q-th-017", "lecture": "th-06", "unit": "濃度と量的関係", "type": "choice", "q": "質量パーセント濃度が 9.0% のブドウ糖 C6H12O6 (分子量 180) 水溶液の質量モル濃度 [mol/kg] として最も近い数値はどれか。", "choices": ["0.60", "0.55", "0.50", "0.45"], "answer": 1, "hint": "溶液 100 g と仮定したとき、溶媒（水）の質量は何 g になるか注意しましょう。", "book": "理論編 第6講"}, {"id": "q-th-018", "lecture": "th-06", "unit": "濃度と量的関係", "type": "choice", "q": "メタン CH4 とエタン C2H6 の混合気体 100 mL を完全燃焼させたところ、標準状態で二酸化炭素 160 mL が生じた。混合気体中のエタンの体積は何 mL か。ただし、反応前後の体積はすべて同温・同圧で測定したものとする。", "choices": ["70", "40", "50", "60"], "answer": 3, "hint": "それぞれの燃焼反応式を書き、係数比＝体積比の関係から連立方程式を立てます。", "book": "理論編 第6講"}, {"id": "q-th-019", "lecture": "th-07", "unit": "酸と塩基", "type": "choice", "q": "次の反応 (i), (ii) において、ブレンステッド・ローリーの定義で「酸」としてはたらいている物質の組み合わせとして正しいものはどれか。\n(i) HCO3-(a) + H2O <-> CO3^2- + H3O+\n(ii) NH4+(b) + OH-(c) -> NH3 + H2O", "choices": ["H2O と c", "a と c", "a と b", "H2O と b"], "answer": 2, "hint": "反応の前後を見て、相手に H+ を与えている物質を探しましょう。", "book": "理論編 第7講"}, {"id": "q-th-020", "lecture": "th-07", "unit": "酸と塩基", "type": "choice", "q": "25℃ における 0.010 mol/L の水酸化ナトリウム NaOH 水溶液の pH はいくらか。ただし、NaOH は完全に電離しているものとする。", "choices": ["13.0", "12.0", "10.0", "2.0"], "answer": 1, "hint": "まず水酸化物イオン濃度から pOH を求め、pH + pOH = 14 の関係を用います。", "book": "理論編 第7講"}, {"id": "q-th-021", "lecture": "th-07", "unit": "酸と塩基", "type": "choice", "q": "pH が 3.0 で電離度 0.010 の酢酸水溶液 100 mL がある。この酢酸をちょうど中和するのに必要な 0.10 mol/L 水酸化ナトリウム水溶液の体積は何 mL か。", "choices": ["10", "100", "1.0", "200"], "answer": 1, "hint": "中和の計算では、酸の全物質量を用います。まずは酢酸のモル濃度を pH と電離度から求めましょう。", "book": "理論編 第7講"}, {"id": "q-th-022", "lecture": "th-08", "unit": "中和滴定の器具", "type": "choice", "q": "中和滴定に使用する器具の扱いとして、水で洗ったあとに「使う溶液で共洗い」をしなければならない器具の組み合わせはどれか。", "choices": ["メスフラスコ、コニカルビーカー", "ホールピペット、メスフラスコ", "コニカルビーカー、ビュレット", "ビュレット、ホールピペット"], "answer": 3, "hint": "水が残っていることで、はかり取る溶液の濃度が薄まってしまうと困る器具を選びます。", "book": "理論編 第8講"}, {"id": "q-th-023", "lecture": "th-08", "unit": "mol/L", "type": "numeric", "q": "0.050 mol/L のシュウ酸水溶液 10.00 mL を、濃度不明の水酸化ナトリウム水溶液で滴定したところ、中和点までに 12.50 mL を要した。この水酸化ナトリウム水溶液のモル濃度は何 mol/L か。", "answer": 0.08, "tolerance": 0.001, "hint": "シュウ酸は2価の酸、水酸化ナトリウムは1価の塩基であることを考慮して中和の基本式を立てます。", "book": "理論編 第8講"}, {"id": "q-th-024", "lecture": "th-08", "unit": "指示薬の選択", "type": "choice", "q": "0.10 mol/L のアンモニア水を、0.10 mol/L の塩酸で滴定する場合、中和点での液性と、適する指示薬の組み合わせとして正しいものはどれか。", "choices": ["酸性、メチルオレンジ", "中性、フェノールフタレイン", "塩基性、フェノールフタレイン", "酸性、フェノールフタレイン"], "answer": 0, "hint": "中和点では塩化アンモニウムが存在します。アンモニウムイオンが水とどう反応するか（加水分解）を考えます。", "book": "理論編 第8講"}, {"id": "q-th-025", "lecture": "th-09", "unit": "酸化還元", "type": "choice", "q": "化合物 K2Cr2O7 における Cr 原子の酸化数として正しいものはどれか。", "choices": ["+6", "+7", "+3", "+4"], "answer": 0, "hint": "Kは+1、Oは-2として、全体の酸化数の総和が0になるよう計算します。", "book": "理論編 第9講"}, {"id": "q-th-026", "lecture": "th-09", "unit": "酸化還元", "type": "choice", "q": "酸化剤・還元剤の性質に関する記述として、本文の内容に基づき正しいものを選べ。", "choices": ["H2O2は常に酸化剤として働き、相手によって役割が変わることはない。", "KMnO4とH2O2が反応するとき、H2O2は酸化剤として働き水に変化する。", "SO2は通常は還元剤だが、H2Sが相手のときは酸化剤として働く。", "反応によって酸化剤自身の酸化数は増加し、還元剤自身の酸化数は減少する。"], "answer": 2, "hint": "H2O2やSO2は、より強い酸化剤や還元剤が相手になると役割が逆転することがあります。", "book": "理論編 第9講"}, {"id": "q-th-027", "lecture": "th-09", "unit": "mol/L", "type": "numeric", "q": "濃度不明のシュウ酸 H2C2O4 水溶液 20.0 mL を希硫酸で酸性にし、0.020 mol/L の過マンガン酸カリウム KMnO4 水溶液を滴下したところ、25.0 mL で終点に達した。このシュウ酸水溶液のモル濃度を求めよ。", "answer": 0.0625, "tolerance": 0.0001, "hint": "酸化剤の(物質量×価数) ＝ 還元剤の(物質量×価数) が成立します。シュウ酸は2価、過マンガン酸イオンは酸性で5価です。", "book": "理論編 第9講"}, {"id": "q-th-028", "lecture": "th-10", "unit": "電池", "type": "choice", "q": "ダニエル電池（Zn | ZnSO4 aq || CuSO4 aq | Cu）の仕組みに関する記述として正しいものを選べ。", "choices": ["負極側のZnSO4水溶液はあらかじめ濃く、正極側のCuSO4水溶液は薄くしておく。", "負極の亜鉛板では電子を受け取る反応が起こり、その質量は徐々に増加する。", "放電が進むと、正極側で余ったSO4 2-が素焼き板を通って負極側へ移動する。", "正極では水素が発生するため、分極を防ぐために減極剤を加える必要がある。"], "answer": 2, "hint": "素焼き板はイオンを通すことで、両溶液の電気的な中性を保つ役割を果たします。", "book": "理論編 第10講"}, {"id": "q-th-029", "lecture": "th-10", "unit": "電池", "type": "choice", "q": "鉛蓄電池の放電および充電に関する記述として、正しいものを選べ。", "choices": ["放電時に正極で生成したPbSO4は溶液中に溶け出し、電極から離れていく。", "放電すると負極のPbは減少するが、正極のPbO2は質量が変化しない。", "放電が進むにつれて、電解液である希硫酸の濃度は徐々に減少していく。", "充電するときは、外部電源の正極を電池の負極に、負極を正極に接続する。"], "answer": 2, "hint": "全体の反応式 Pb + PbO2 + 2H2SO4 -> 2PbSO4 + 2H2O から、硫酸と水の増減を考えます。", "book": "理論編 第10講"}, {"id": "q-th-030", "lecture": "th-10", "unit": "電池", "type": "choice", "q": "燃料電池に関する記述として、本文の内容に基づき正しいものを選べ。", "choices": ["全体の反応は H2 + 1/2 O2 -> H2O であり、水の電気分解の逆反応である。", "電解液にKOHを用いた塩基型では、H+イオンが電解液中を移動する。", "負極では酸素が供給され、電子を受け取って水に変化する反応が起こる。", "燃料電池は、鉛蓄電池と同じように充電して繰り返し使える二次電池である。"], "answer": 0, "hint": "燃料電池は燃料を供給し続ける限り発電する装置で、排泄物は水のみという特徴があります。", "book": "理論編 第10講"}, {"id": "q-th-031", "lecture": "th-11", "unit": "電気分解", "type": "choice", "q": "白金電極を用いて塩化ナトリウム水溶液を電気分解したとき、陰極で起こる反応を正しく表している式はどれか。", "choices": ["Pt -> Pt2+ + 2e-", "Na+ + e- -> Na", "2H2O + 2e- -> H2 + 2OH-", "2H+ + 2e- -> H2"], "answer": 2, "hint": "ナトリウムイオンは電子を受け取るのを拒否します。", "book": "理論編 第11講"}, {"id": "q-th-032", "lecture": "th-11", "unit": "電気分解", "type": "choice", "q": "銅電極を陽極、白金電極を陰極として、塩化ナトリウム水溶液を電気分解した。このとき陽極で起こる変化はどれか。", "choices": ["溶液中の水分子が反応し O2 が発生する", "電極の銅が Cu2+ となって溶け出す", "溶液中の塩化物イオンが反応し Cl2 が発生する", "溶液中の水酸化物イオンが反応し O2 が発生する"], "answer": 1, "hint": "陽極では、まず電極自体の材質をチェックします。", "book": "理論編 第11講"}, {"id": "q-th-033", "lecture": "th-11", "unit": "電気分解の計算", "type": "choice", "q": "白金電極を用いて硝酸銀水溶液を電気分解した。2.0 A の電流を 9650 秒間流したとき、陰極に析出する銀の質量は何 g か。Ag = 108、ファラデー定数は 96500 C/mol とする。", "choices": ["21.6 g", "5.4 g", "10.8 g", "43.2 g"], "answer": 0, "hint": "流れた電子の物質量(mol)を求め、銀イオンとの係数比を確認しましょう。", "book": "理論編 第11講"}, {"id": "q-th-034", "lecture": "th-12", "unit": "気体の性質", "type": "choice", "q": "自由に動くピストンのついた容器に気体が入っており、27度で体積は 1.0 L であった。圧力を一定に保ったまま、温度を 327度まで加熱したとき、体積は何 L になるか。", "choices": ["2.0 L", "1.1 L", "0.5 L", "12.1 L"], "answer": 0, "hint": "シャルルの法則では、温度は必ず絶対温度(K)を使います。", "book": "理論編 第12講"}, {"id": "q-th-035", "lecture": "th-12", "unit": "g/mol", "type": "numeric", "q": "標準状態（0度、1.013*10^5 Pa）において、密度が 1.25 g/L である気体の分子量を求めよ。標準状態における気体 1 mol の体積は 22.4 L とする。", "answer": 28.0, "tolerance": 0.1, "hint": "密度d(g/L)に1molの体積(L)を掛けると、1molあたりの質量になります。", "book": "理論編 第12講"}, {"id": "q-th-036", "lecture": "th-12", "unit": "実在気体", "type": "choice", "q": "実在気体が理想気体の挙動からずれる原因と、理想気体に近づく条件について正しく述べたものはどれか。", "choices": ["分子間力が原因であり、低温・低圧で理想気体に近づく。", "分子自身の体積が原因であり、高温・高圧で理想気体に近づく。", "分子間力と分子の体積が原因であり、高温・低圧で理想気体に近づく。", "熱運動が原因であり、低温・高圧で理想気体に近づく。"], "answer": 2, "hint": "熱運動が引力を振り切り、分子の隙間が十分に広くなる条件を考えます。", "book": "理論編 第12講"}, {"id": "q-th-037", "lecture": "th-13", "unit": "状態図", "type": "choice", "q": "水の状態図における「三重点」について、正しい説明はどれか。", "choices": ["固体・液体・気体の3つが共存できる、ただ1つの温度・圧力の点である。", "蒸気圧が大気圧に等しくなる温度・圧力の点である。", "液体と気体の区別がなくなる温度・圧力の点である。", "融点と沸点が一致する温度・圧力の点である。"], "answer": 0, "hint": "3本の曲線が交わる点です。", "book": "理論編 第13講"}, {"id": "q-th-038", "lecture": "th-13", "unit": "状態図", "type": "choice", "q": "水の融解曲線が左上がりになる理由として、正しいものはどれか。", "choices": ["水の融解熱が他の物質より大きいから。", "水の蒸気圧が他の物質より高いから。", "固体と液体の体積が等しいから。", "氷の体積が液体の水より大きいから。"], "answer": 3, "hint": "加圧すると体積の小さい方の状態が有利になります。", "book": "理論編 第13講"}, {"id": "q-th-039", "lecture": "th-13", "unit": "kJ", "type": "numeric", "q": "0℃の氷72gがある。水の融解熱は6.0kJ/molとする。氷をすべて0℃の水にするのに必要な熱量は何kJか。", "answer": 24, "tolerance": 0.5, "hint": "氷72gは水の分子量18で割ると4.0molです。", "book": "理論編 第13講"}, {"id": "q-th-040", "lecture": "th-14", "unit": "g", "type": "numeric", "q": "硝酸カリウムKNO3の20℃における溶解度は32(水100gに対して)である。20℃のKNO3飽和溶液264gに含まれるKNO3は何gか。", "answer": 64, "tolerance": 0.5, "hint": "飽和溶液では溶質:水:溶液=32:100:132の比です。", "book": "理論編 第14講"}, {"id": "q-th-041", "lecture": "th-14", "unit": "水和物の析出", "type": "choice", "q": "硫酸銅(II)五水和物CuSO4・5H2Oの結晶が析出するときの計算について、正しいものはどれか。", "choices": ["溶解度の差を使えば、水和物でも無水物と同じように析出量が求まる。", "結晶水の分は計算に入れなくてよい。", "析出後の溶液は未飽和になるので、溶解度の比は使えない。", "結晶水として水も溶液から出ていくので、溶解度の差だけでは析出量を求められない。"], "answer": 3, "hint": "析出する結晶の中に水が取り込まれることに注目します。", "book": "理論編 第14講"}, {"id": "q-th-042", "lecture": "th-14", "unit": "気体の溶解度", "type": "choice", "q": "気体の溶解度と温度の関係について、正しいものはどれか。", "choices": ["温度を変えても溶解度は変わらない。", "温度が高いほど溶けにくくなるが、理由は圧力が下がるからである。", "温度が低いほどよく溶ける。気体の溶解は発熱反応だからである。", "温度が高いほどよく溶ける。固体の溶解と同じ傾向である。"], "answer": 2, "hint": "温度を上げると、溶けていた気体分子が液面から飛び出しやすくなります。", "book": "理論編 第14講"}, {"id": "q-th-043", "lecture": "th-15", "unit": "熱化学方程式", "type": "choice", "q": "水素H2の結合エネルギーは436kJ/molである。熱化学方程式 H2(気)=2H(気)+Q におけるQとして正しいものはどれか。", "choices": ["-436kJ", "+872kJ", "+436kJ", "0kJ"], "answer": 0, "hint": "結合を切るのは吸熱反応です。式の中では符号に注意します。", "book": "理論編 第15講"}, {"id": "q-th-044", "lecture": "th-15", "unit": "kJ", "type": "numeric", "q": "プロパンC3H8(分子量44)8.8gを完全燃焼させたときに発生する熱量は何kJか。プロパンの燃焼熱は2220kJ/molとする。", "answer": 444, "tolerance": 1, "hint": "8.8gは0.20molです。熱量は反応熱×物質量で求めます。", "book": "理論編 第15講"}, {"id": "q-th-045", "lecture": "th-15", "unit": "格子エネルギー", "type": "choice", "q": "塩化ナトリウムNaClの格子エネルギーについて、本書の要点で統一している値はどれか。", "choices": ["787kJ/mol", "789kJ/mol", "770kJ/mol", "771kJ/mol"], "answer": 3, "hint": "格子エネルギーは使う熱データで値が少し変わります。本書の要点の値を覚えます。", "book": "理論編 第15講"}, {"id": "q-th-046", "lecture": "th-16", "unit": "kJ/mol", "type": "numeric", "q": "ある反応のエネルギー図では、反応物のエネルギーが120kJ、活性化状態が380kJ、生成物が50kJであった(いずれも1molあたり)。正反応の活性化エネルギーはいくらか。kJ/mol単位で答えよ。", "answer": 260, "tolerance": 1, "hint": "活性化エネルギーは出発側から山頂までの高さです。", "book": "理論編 第16講"}, {"id": "q-th-047", "lecture": "th-16", "unit": "触媒", "type": "choice", "q": "触媒の働きについて、正しいものはどれか。", "choices": ["反応熱を小さくして、反応を速くする。", "活性化エネルギーを下げて反応を速くするが、反応熱も平衡定数も変えない。", "反応物のエネルギーを下げて、反応を速くする。", "平衡定数を大きくして、生成物の量を増やす。"], "answer": 1, "hint": "触媒が下げるのは山頂(活性化状態)の高さだけです。", "book": "理論編 第16講"}, {"id": "q-th-048", "lecture": "th-16", "unit": "化学平衡", "type": "choice", "q": "四酸化二窒素と二酸化窒素の平衡 N2O4⇄2NO2 は吸熱反応である。平衡状態にあるこの反応を加熱すると、平衡はどう移動するか。", "choices": ["発熱方向である左(N2O4側)へ移動する。", "吸熱方向である右(NO2側)へ移動する。", "触媒を加えたときと同じで、平衡は移動しない。", "温度変化では平衡は移動しない。"], "answer": 1, "hint": "加えた熱を打ち消す向き、つまり熱を吸収する向きへ移動します。", "book": "理論編 第16講"}, {"id": "q-th-049", "lecture": "th-17", "unit": "緩衝溶液", "type": "choice", "q": "次の組み合わせのうち、緩衝溶液として働くものはどれか。", "choices": ["0.10mol/Lの水酸化ナトリウムと0.10mol/Lの塩化ナトリウムの混合溶液", "0.10mol/Lの塩酸と0.10mol/Lの水酸化ナトリウムの混合溶液", "0.10mol/Lの酢酸と0.10mol/Lの塩酸の混合溶液", "0.10mol/Lのギ酸と0.10mol/Lのギ酸ナトリウムの混合溶液"], "answer": 3, "hint": "弱酸とその塩の組み合わせです。", "book": "理論編 第17講"}, {"id": "q-th-050", "lecture": "th-17", "unit": "塩の加水分解", "type": "choice", "q": "0.20mol/Lの塩化アンモニウムNH4Cl水溶液の液性について、正しいものはどれか。", "choices": ["塩基性である。NH3が遊離するから。", "塩酸と同じ強さの酸性を示す。", "中性である。強酸と弱塩基の塩だから。", "酸性である。NH4+が加水分解してH+を生じるから。"], "answer": 3, "hint": "塩を作る酸と塩基の強さで、酸性か塩基性かが決まります。", "book": "理論編 第17講"}, {"id": "q-th-051", "lecture": "th-17", "unit": "×10^-4 mol/L", "type": "numeric", "q": "フッ化カルシウムCaF2の溶解度積はKsp=3.2×10^-11(mol/L)^3である。純水に対するCaF2の溶解度を、10^-4mol/L単位で答えよ。", "answer": 2.0, "tolerance": 0.1, "hint": "溶解度をxと置くと、Ksp=[Ca2+][F-]^2=x×(2x)^2=4x^3です。", "book": "理論編 第17講"}, {"id": "q-th-052", "lecture": "th-01", "unit": "成分元素と単体", "type": "choice", "q": "炭素の同素体に関する記述として、最も適当なものはどれか。", "choices": ["ダイヤモンドは、1個の炭素原子が4個の炭素原子と共有結合した、正四面体構造の結晶である。", "黒鉛（グラファイト）は、層状の構造を持ち、層の間は強い共有結合によって結ばれている。", "フラーレン（C60）は、多数の炭素原子が網目状に際限なく結合した巨大分子である。", "無定形炭素は、ダイヤモンドや黒鉛とは全く異なる特殊な原子配列を持つ結晶である。"], "answer": 0, "hint": "それぞれの同素体における原子の並び方や、結合の種類に着目しましょう。", "book": "理論編 第1講"}, {"id": "q-th-053", "lecture": "th-01", "unit": "成分元素の検出", "type": "choice", "q": "ある無色の水溶液について調べたところ、炎色反応は黄色を呈し、硝酸銀水溶液を加えると白色沈殿が生じた。この水溶液に含まれている物質として最も適当なものはどれか。", "choices": ["KCl", "NaCl", "Na2SO4", "BaCl2"], "answer": 1, "hint": "炎の色から陽イオンを、沈殿反応の結果から陰イオンを特定しましょう。", "book": "理論編 第1講"}, {"id": "q-th-054", "lecture": "th-01", "unit": "同位体と原子量", "type": "choice", "q": "塩素には、相対質量35.0の 35Cl と、相対質量37.0の 37Cl の2種類の同位体が存在する。塩素の原子量を35.5としたとき、35Cl の存在比（％）として正しいものはどれか。", "choices": ["25％", "50％", "75％", "80％"], "answer": 2, "hint": "原子量は、各同位体の相対質量にその存在比を掛けたものの和で求められます。", "book": "理論編 第1講"}, {"id": "q-th-055", "lecture": "th-02", "unit": "イオン化エネルギー", "type": "choice", "q": "第3周期の元素（Na〜Ar）の第1イオン化エネルギーに関する記述として正しいものはどれか。", "choices": ["同一周期では、原子番号が大きくなるほど第1イオン化エネルギーは一様に減少する。", "第1イオン化エネルギーが最も大きい元素はアルゴン（Ar）である。", "ナトリウム（Na）の第1イオン化エネルギーは、同周期の他の元素に比べて非常に大きい。", "第1イオン化エネルギーとは、気体状態の原子から電子を2個取り去るのに必要なエネルギーである。"], "answer": 1, "hint": "イオン化エネルギーは、電子を1個取り去るのに必要なエネルギーであり、貴ガスの状態に注目してください。", "book": "理論編 第2講"}, {"id": "q-th-056", "lecture": "th-02", "unit": "電子配置と周期表", "type": "choice", "q": "ある原子のM殻に6個の電子が入っているとき、この原子の周期表における位置として正しいものはどれか。なお、K殻とL殻は電子で満たされているものとする。", "choices": ["第3周期14族", "第3周期16族", "第4周期6族", "第4周期16族"], "answer": 1, "hint": "電子が入っている電子殻の数から「周期」を、最外殻電子の数から「族」を決定します。", "book": "理論編 第2講"}, {"id": "q-th-057", "lecture": "th-02", "unit": "等電子配置のイオン", "type": "choice", "q": "次のイオン O2-、F-、Na+、Mg2+ はすべてネオン（Ne）と同じ電子配置を持っている。これらのイオンの中で、イオン半径が最も大きいものはどれか。", "choices": ["O2-", "F-", "Na+", "Mg2+"], "answer": 0, "hint": "電子の数が同じ場合、中心にある原子核の正電荷（陽子数）が電子を引く強さに注目しましょう。", "book": "理論編 第2講"}, {"id": "q-th-058", "lecture": "th-03", "unit": "化学結合と原子量", "type": "choice", "q": "次の分子のうち、結合に極性は存在するが、分子の形状が対称であるために分子全体としては極性をもたない（無極性分子である）ものはどれか。", "choices": ["NH3", "CHCl3", "CO2", "H2O"], "answer": 2, "hint": "分子の形状による極性の打ち消し合いを考えます。", "book": "理論編 第3講"}, {"id": "q-th-059", "lecture": "th-03", "unit": "化学結合と原子量", "type": "numeric", "q": "硫酸銅(II)五水和物 CuSO4・5H2O の式量を求めよ。ただし原子量は Cu=64, S=32, O=16, H=1.0 とする。", "answer": 250, "tolerance": 1.25, "hint": "五水和物は、硫酸銅(II)の式量に水5分子分の分子量を加算して計算します。", "book": "理論編 第3講"}, {"id": "q-th-060", "lecture": "th-03", "unit": "化学結合と原子量", "type": "choice", "q": "次の物質の組み合わせのうち、分子間に水素結合がはたらくものの組み合わせとして最も適当なものはどれか。", "choices": ["CH4 と H2", "HF と NH3", "H2S と PH3", "HCl と HBr"], "answer": 1, "hint": "H原子が電気陰性度の非常に大きいF, O, N原子のいずれかと結合している分子を探します。", "book": "理論編 第3講"}, {"id": "q-th-061", "lecture": "th-04", "unit": "結晶構造", "type": "numeric", "q": "原子量 60 の金属結晶があり、面心立方格子の構造をとっている。単位格子の一辺の長さが 4.0 * 10^-8 cm であるとき、この金属の密度 [g/cm^3] を求めよ。ただし、4.0^3 = 64、アボガドロ定数は 6.0 * 10^23 /mol とする。", "answer": 6.25, "tolerance": 0.05, "hint": "単位格子に含まれる原子4個分の合計質量を、単位格子の体積で割って算出します。", "book": "理論編 第4講"}, {"id": "q-th-062", "lecture": "th-04", "unit": "結晶構造", "type": "choice", "q": "塩化セシウム CsCl 型のイオン結晶において、1個のセシウムイオン Cs+ に隣接して接している塩化物イオン Cl- の数（配位数）として正しいものはどれか。", "choices": ["4", "6", "8", "12"], "answer": 2, "hint": "CsCl型の構造は、立方体の中心に1つのイオンがあり、その頂点に逆符号のイオンが配置されます。", "book": "理論編 第4講"}, {"id": "q-th-063", "lecture": "th-04", "unit": "結晶構造", "type": "choice", "q": "ある金属 M の陽イオン M2+ と、非金属 X の陰イオン X3- からなるイオン結晶がある。この結晶の組成式として正しいものはどれか。", "choices": ["MX", "M3X2", "M2X3", "M2X"], "answer": 1, "hint": "陽イオンの正電荷の合計と、陰イオンの負電荷の合計が打ち消し合って 0 になる個数比を考えます。", "book": "理論編 第4講"}, {"id": "q-th-064", "lecture": "th-05", "unit": "共有結合結晶と分子", "type": "choice", "q": "ダイヤモンドと黒鉛（グラファイト）の性質に関する記述として、最も適当なものを1つ選べ。", "choices": ["ダイヤモンドは、1個の炭素原子に対して4個の炭素原子が正三角形の頂点方向に共有結合している。", "黒鉛は層状構造を持ち、層の内部では1個の炭素原子に3個の炭素原子が結合し、余った電子が移動できるため電気を通す。", "ダイヤモンドと黒鉛は互いに同位体であり、どちらも完全に燃焼させると二酸化炭素が発生する。", "黒鉛は共有結合のみで構成されているが、ダイヤモンドは共有結合とファンデルワールス力の両方で結合している。"], "answer": 1, "hint": "各炭素原子から出ている結合手の数と、自由な電子の有無に注目しましょう。", "book": "理論編 第5講"}, {"id": "q-th-065", "lecture": "th-05", "unit": "共有結合結晶と分子", "type": "choice", "q": "二酸化ケイ素(SiO2)の構造と性質に関する記述として、正しいものを1つ選べ。", "choices": ["SiO2の結晶中では、1個のケイ素原子に対して2個の酸素原子が二重結合で結合した分子が独立して存在している。", "二酸化ケイ素は水分子と水素結合を形成しやすいため、水によく溶けて弱酸性を示す。", "二酸化ケイ素の結晶は、1個のケイ素原子を4個の酸素原子が正四面体形に取り囲んだ構造が繰り返された共有結合結晶である。", "二酸化ケイ素は分子結晶であるため、ダイヤモンドなどの共有結合結晶に比べて融点が著しく低い。"], "answer": 2, "hint": "二酸化ケイ素は個別の分子として存在するのか、巨大な網目構造なのかを考えましょう。", "book": "理論編 第5講"}, {"id": "q-th-066", "lecture": "th-05", "unit": "共有結合結晶と分子", "type": "choice", "q": "次の分子のうち、沸点が最も高い物質を1つ選べ。", "choices": ["HF", "HCl", "HBr", "HI"], "answer": 0, "hint": "フッ素、塩素、臭素、ヨウ素の水素化合物のうち、特殊な分子間力が働くものはどれか考えましょう。", "book": "理論編 第5講"}, {"id": "q-th-067", "lecture": "th-06", "unit": "濃度と量的関係", "type": "numeric", "q": "36.5%の濃塩酸（塩化水素HClの水溶液）がある。この濃塩酸の密度が1.20 g/cm3であるとき、この水溶液のモル濃度は何mol/Lか。有効数字3桁で答えよ。（原子量：H=1.0、Cl=35.5）", "answer": 12.0, "tolerance": 0.1, "hint": "溶液1Lの質量を密度から求め、その中に含まれる溶質の質量をパーセント濃度を使って計算しましょう。", "book": "理論編 第6講"}, {"id": "q-th-068", "lecture": "th-06", "unit": "濃度と量的関係", "type": "choice", "q": "硝酸カリウムKNO3の溶解度は、60度で110g/水100g、20度で32g/水100gである。60度の硝酸カリウム飽和水溶液210gを20度まで冷却したとき、析出する結晶は何gか。", "choices": ["32g", "78g", "110g", "178g"], "answer": 1, "hint": "60度の飽和水溶液210gの中に、水と溶質がそれぞれ何g含まれているかを計算しましょう。", "book": "理論編 第6講"}, {"id": "q-th-069", "lecture": "th-06", "unit": "濃度と量的関係", "type": "choice", "q": "アルミニウム5.4gに十分な量の希塩酸を加えて反応させたとき、発生する水素の体積は標準状態で何Lか。反応式は 2Al + 6HCl -> 2AlCl3 + 3H2 とする。（原子量：Al=27）", "choices": ["2.24L", "4.48L", "6.72L", "13.44L"], "answer": 2, "hint": "反応式の係数比から、反応するアルミニウムと発生する水素の物質量（mol）の比を確認しましょう。", "book": "理論編 第6講"}, {"id": "q-th-070", "lecture": "th-07", "unit": "酸と塩基", "type": "choice", "q": "次の化学反応式において、下線部の物質がブレンステッド・ローリーの定義における「酸」として働いているものはどれか。 (1) NH3 + H2O <-> NH4+ + OH-、(2) CH3COOH + H2O <-> CH3COO- + H3O+、(3) HCl + H2O -> H3O+ + Cl-。ただし、下線部は順に (1)のH2O、(2)のH2O、(3)のCl- とする。", "choices": ["(1)のH2O", "(2)のH2O", "(3)のCl-", "この中には存在しない"], "answer": 0, "hint": "ブレンステッド・ローリーの定義では、相手にH+（陽子）を与える物質を酸と呼びます。", "book": "理論編 第7講"}, {"id": "q-th-071", "lecture": "th-07", "unit": "酸と塩基", "type": "numeric", "q": "0.10 mol/Lの塩酸1.0 mLに水を加えて100 mLとした。この希釈後の水溶液のpHはいくらか。数値で答えよ。ただし、25度における塩酸の電離度は1.0とする。", "answer": 3, "tolerance": 0.1, "hint": "希釈によって[H+]が何分の一になるかを計算し、pHの定義式に当てはめましょう。", "book": "理論編 第7講"}, {"id": "q-th-072", "lecture": "th-07", "unit": "酸と塩基", "type": "choice", "q": "次の(A)〜(D)の酸の水溶液を、それぞれ0.10 mol/Lの水酸化ナトリウム水溶液で完全に中和するとき、最も多くの滴下量を必要とするものはどれか。\n(A) 30 mLの0.10 mol/L HCl水溶液\n(B) 25 mLの0.10 mol/L H2SO4水溶液\n(C) 15 mLの0.20 mol/L CH3COOH水溶液\n(D) 40 mLの0.050 mol/L HNO3水溶液", "choices": ["(A)", "(B)", "(C)", "(D)"], "answer": 1, "hint": "中和に必要な塩基の量は、酸の「価数 × モル濃度 × 体積」で決まるH+の総物質量に比例します。", "book": "理論編 第7講"}, {"id": "q-th-073", "lecture": "th-08", "unit": "塩の反応と滴定", "type": "choice", "q": "次の塩のうち、その水溶液が塩基性を示すものの組み合わせとして正しいものはどれか。 (a) NH4Cl, (b) Na2CO3, (c) KNO3, (d) CH3COONa", "choices": ["(a)と(b)", "(b)と(c)", "(b)と(d)", "(a)と(d)"], "answer": 2, "hint": "強塩基と弱酸からなる塩が加水分解すると、水溶液は塩基性になります。", "book": "理論編 第8講"}, {"id": "q-th-074", "lecture": "th-08", "unit": "塩の反応と滴定", "type": "numeric", "q": "濃度未知の炭酸ナトリウム Na2CO3 水溶液20.0 mLを、0.100 mol/Lの塩酸で滴定した。フェノールフタレインを指示薬として用いたところ、溶液の赤色が消える第1中和点までに12.0 mLの塩酸を要した。この炭酸ナトリウム水溶液のモル濃度（mol/L）を求めよ。", "answer": 0.06, "tolerance": 0.001, "hint": "フェノールフタレインが変色する第1中和点では、炭酸ナトリウムがすべて炭酸水素ナトリウムに変化しています。", "book": "理論編 第8講"}, {"id": "q-th-075", "lecture": "th-08", "unit": "塩の反応と滴定", "type": "choice", "q": "0.10 mol/Lの酢酸水溶液10 mLを、0.10 mol/Lの水酸化ナトリウム水溶液で滴定した。この滴定に関する記述として最も適切なものはどれか。", "choices": ["中和点のpHは7であり、指示薬としてメチルオレンジが適している。", "中和点のpHは7より大きく、指示薬としてフェノールフタレインが適している。", "中和点のpHは7より小さく、指示薬としてメチルオレンジが適している。", "中和点のpHは7より大きく、指示薬としてメチルオレンジが適している。"], "answer": 1, "hint": "弱酸を強塩基で滴定すると、生成する塩の加水分解により、中和点は塩基性側にずれます。", "book": "理論編 第8講"}, {"id": "q-th-076", "lecture": "th-09", "unit": "酸化還元", "type": "choice", "q": "二クロム酸カリウム K2Cr2O7 におけるクロム原子(Cr)の酸化数として正しいものはどれか。", "choices": ["+6", "+7", "+3", "+4"], "answer": 0, "hint": "化合物全体の酸化数の総和は0になり、カリウムイオンは+1、酸素原子は-2として計算します。", "book": "理論編 第9講"}, {"id": "q-th-077", "lecture": "th-09", "unit": "酸化還元", "type": "choice", "q": "次の化学反応のうち、二酸化硫黄 SO2 が「酸化剤」としてはたらいているものはどれか。", "choices": ["SO2 + 2H2S -> 3S + 2H2O", "2SO2 + O2 -> 2SO3", "SO2 + Cl2 + 2H2O -> H2SO4 + 2HCl", "SO2 + H2O2 -> H2SO4"], "answer": 0, "hint": "酸化剤としてはたらくとき、その物質に含まれる原子の酸化数は減少します。", "book": "理論編 第9講"}, {"id": "q-th-078", "lecture": "th-09", "unit": "酸化還元", "type": "numeric", "q": "0.050 mol/L のシュウ酸 H2C2O4 水溶液 20.0 mL を完全に酸化するのに必要な 0.020 mol/L の過マンガン酸カリウム KMnO4 水溶液は何 mL か。ただし、反応は硫酸酸性条件下で行われるものとする。", "answer": 20.0, "tolerance": 0.1, "hint": "酸化剤が受け取る電子の物質量と、還元剤が放出する電子の物質量が等しくなることを利用します。", "book": "理論編 第9講"}, {"id": "q-th-079", "lecture": "th-10", "unit": "電池", "type": "choice", "q": "ダニエル電池（Zn | ZnSO4 aq || CuSO4 aq | Cu）において、塩橋（ソルトブリッジ）の役割に関する記述として正しいものはどれか。", "choices": ["正極側で減少する正電荷を補うため、塩橋内の陽イオンが正極側の水溶液へ移動する。", "負極から放出された電子(e-)が、塩橋の中を直接通って正極へ移動する。", "溶液中の硫酸イオン(SO4 2-)が、塩橋を通って負極側から正極側へ移動する。", "塩橋は、正極と負極の金属板を直接接触させて回路を閉じる役割を持つ。"], "answer": 0, "hint": "電池が作動すると、溶液中のイオンバランスが崩れるため、それを解消する方向にイオンが動きます。", "book": "理論編 第10講"}, {"id": "q-th-080", "lecture": "th-10", "unit": "電池", "type": "choice", "q": "鉛蓄電池を放電させたときの変化について、正しい記述はどれか。", "choices": ["負極・正極ともに、電極の質量が増加する。", "負極・正極ともに、電極の質量が減少する。", "負極の質量は増加し、正極の質量は減少する。", "電解液である希硫酸の密度が上昇する。"], "answer": 0, "hint": "放電時、負極のPbおよび正極のPbO2は、ともに共通のある物質に変化します。", "book": "理論編 第10講"}, {"id": "q-th-081", "lecture": "th-10", "unit": "電池", "type": "choice", "q": "リン酸型燃料電池（電解液が酸性）の正極における反応を正しく表した式はどれか。", "choices": ["O2 + 4H+ + 4e- -> 2H2O", "H2 -> 2H+ + 2e-", "O2 + 2H2O + 4e- -> 4OH-", "2H2O -> O2 + 4H+ + 4e-"], "answer": 0, "hint": "燃料電池の正極では、供給された酸素が電子を受け取って還元されます。酸性条件であることに注意してください。", "book": "理論編 第10講"}, {"id": "q-th-082", "lecture": "th-11", "unit": "電気分解", "type": "choice", "q": "アルミニウムの工業的製法（ホール・エルー法）において、酸化アルミニウム（アルミナ）に氷晶石（Na3AlF6）を加えて融解塩電解を行う主な目的として、最も適切なものはどれか。", "choices": ["酸化アルミニウムの融点を下げ、液状にしやすくするため。", "陽極で発生する酸素ガスを、二酸化炭素として取り除くため。", "陰極でアルミニウムイオンが還元される反応速度を速めるため。", "溶融液の密度を大きくし、生成したアルミニウムを浮上させるため。"], "answer": 0, "hint": "酸化アルミニウム単体の融点は約2000度と非常に高いことに注目しましょう。", "book": "理論編 第11講"}, {"id": "q-th-083", "lecture": "th-11", "unit": "電気分解", "type": "choice", "q": "陽イオン交換膜法を用いた塩化ナトリウム水溶液の電気分解について、陰極側の変化として正しい記述はどれか。", "choices": ["水分子が電子を受け取り、水素が発生して溶液の塩基性が強くなる。", "塩化物イオンが電子を放出し、塩素が発生して溶液の酸性が強くなる。", "ナトリウムイオンが電子を受け取り、金属ナトリウムが析出する。", "水酸化物イオンが電子を放出し、酸素が発生してpHは変化しない。"], "answer": 0, "hint": "陰極では、水溶液中のイオンまたは水分子のどちらが電子を受け取りやすいかを考えます。", "book": "理論編 第11講"}, {"id": "q-th-084", "lecture": "th-11", "unit": "電気分解", "type": "numeric", "q": "硝酸銀水溶液の電気分解を、白金電極を用いて行った。2.00 Aの一定電流を16分5秒（965秒）間流したとき、陰極に析出する銀（原子量 Ag=108）は何gか。ファラデー定数 F=96500 C/molとする。", "answer": 2.16, "tolerance": 0.02, "hint": "Q=Itで電気量を求め、ファラデー定数を使って電子の物質量を計算しましょう。", "book": "理論編 第11講"}, {"id": "q-th-085", "lecture": "th-12", "unit": "気体の分圧", "type": "choice", "q": "一定温度において、10 Lの密閉容器に0.40 molのヘリウムと0.10 molのアルゴンが入っている。この混合気体の全圧が 1.25 * 10^5 Pa であるとき、アルゴンの分圧は何Paか。", "choices": ["0.25 * 10^5", "0.50 * 10^5", "1.00 * 10^5", "1.25 * 10^5"], "answer": 0, "hint": "ドルトンの分圧の法則（分圧 = 全圧 * モル分率）を利用しましょう。", "book": "理論編 第12講"}, {"id": "q-th-086", "lecture": "th-12", "unit": "気体の密度", "type": "choice", "q": "窒素（分子量28）と酸素（分子量32）が体積比 4：1 で混合された気体がある。標準状態（0度、1.013 * 10^5 Pa）におけるこの混合気体の密度（g/L）として最も近い値はどれか。", "choices": ["1.16", "1.25", "1.29", "1.43"], "answer": 2, "hint": "まず混合気体の平均分子量を求め、標準状態での1molの体積（22.4 L）で割りましょう。", "book": "理論編 第12講"}, {"id": "q-th-087", "lecture": "th-12", "unit": "状態方程式", "type": "numeric", "q": "容積 8.31 L の真空容器に 0.50 mol の理想気体を入れ、温度を 27 度に保った。このときの容器内の圧力は何 Pa か。気体定数 R = 8.31 * 10^3 Pa・L/(K・mol) とする。", "answer": 150000, "tolerance": 1000, "hint": "状態方程式 PV=nRT に値を代入します。温度は必ず絶対温度（K）に変換してください。", "book": "理論編 第12講"}, {"id": "q-th-088", "lecture": "th-13", "unit": "状態変化と蒸気圧", "type": "choice", "q": "外圧が 6.0*10^4 Pa の場所で液体を加熱したとき、沸騰が起こる条件として最も適切な説明を選びなさい。", "choices": ["液体の蒸気圧が 6.0*10^4 Pa に達したとき", "液体の蒸気圧が 1.013*10^5 Pa に達したとき", "液体の温度が 100度 に達したとき", "液体の蒸気圧が外圧よりも小さくなったとき"], "answer": 0, "hint": "沸騰とは、液体の内部から気化が起こる現象です。", "book": "理論編 第13講"}, {"id": "q-th-089", "lecture": "th-13", "unit": "状態変化と蒸気圧", "type": "choice", "q": "純物質の固体を一定の割合で加熱したときの加熱曲線について、融解している間、加熱を続けているにもかかわらず温度が一定に保たれる理由として正しいものを選びなさい。", "choices": ["加えられた熱がすべて物質の状態変化（分子間の結合を切るなど）に使われるため", "融解によって比熱容量が無限大になるため", "固体と液体が共存すると蒸気圧が 0 になるため", "周囲に熱が逃げる速度と加熱の速度が完全に一致するため"], "answer": 0, "hint": "状態変化に伴い吸収される熱（潜熱）の行方を考えましょう。", "book": "理論編 第13講"}, {"id": "q-th-090", "lecture": "th-13", "unit": "状態変化と蒸気圧", "type": "numeric", "q": "容積 8.31 L の密閉容器を 27度（300 K）に保ち、内部を真空にした後、0.050 mol の物質Xを導入した。27度における物質Xの飽和蒸気圧が 1.2*10^4 Pa であるとき、容器内の最終的な圧力は何 Pa になるか。気体定数 R = 8.31*10^3 Pa・L/(mol・K) とする。", "answer": 12000, "tolerance": 60.0, "hint": "仮にすべてが気体とした場合の圧力を求め、飽和蒸気圧と比較しましょう。", "book": "理論編 第13講"}, {"id": "q-th-091", "lecture": "th-14", "unit": "溶液とコロイド", "type": "choice", "q": "水酸化鉄(III)のコロイド溶液（正に帯電した疎水コロイド）に関する記述として正しいものを選びなさい。", "choices": ["少量の電解質を加えると、コロイド粒子が凝集して沈殿する（凝析）。", "親水コロイドであるため、多量の電解質を加えない限り沈殿しない（塩析）。", "直流電圧をかけると、コロイド粒子は陽極側に移動する。", "デンプン溶液を加えると、保護コロイドとしての作用により凝集しやすくなる。"], "answer": 0, "hint": "疎水コロイドと電解質の関係を思い出しましょう。", "book": "理論編 第14講"}, {"id": "q-th-092", "lecture": "th-14", "unit": "溶液とコロイド", "type": "choice", "q": "中央を半透膜で仕切ったU字管の一方に純水を、もう一方に同じ高さまで 0.1 mol/L のスクロース（ショ糖）水溶液を入れた。十分な時間放置したときの変化として正しいものを選びなさい。", "choices": ["純水側の水分子が溶液側に移動し、溶液側の液面が高くなる。", "溶液側のスクロース分子が純水側に移動し、両液面の高さは等しくなる。", "純水側の液面が高くなる。", "半透膜を水分子が通過できないため、液面の高さは変化しない。"], "answer": 0, "hint": "浸透圧の原理により、水分子はどちらの方向に移動しやすいかを考えます。", "book": "理論編 第14講"}, {"id": "q-th-093", "lecture": "th-14", "unit": "溶液とコロイド", "type": "numeric", "q": "ある非電解質の有機化合物 1.28 g をベンゼン 100 g に溶かしたところ、凝固点が純粋なベンゼンより 0.256 K 低下した。この化合物の分子量を求めなさい。ベンゼンのモル凝固点降下を Kf = 5.12 K・kg/mol とする。", "answer": 256, "tolerance": 1.28, "hint": "凝固点降下度の式 delta T = Kf * m に各数値を代入しましょう。", "book": "理論編 第14講"}, {"id": "q-th-094", "lecture": "th-15", "unit": "反応熱の種類", "type": "choice", "q": "熱化学方程式において、反応熱の符号が吸熱（負の反応熱、または Q < 0）となる現象として最も適切なものはどれか。", "choices": ["強酸と強塩基の水溶液を混合したときの中和熱", "プロパンが酸素と反応して二酸化炭素と水が生じるときの燃焼熱", "水酸化ナトリウムの固体が多量の水に溶けるときの溶解熱", "液体の水が沸騰して水蒸気になるときの蒸発熱"], "answer": 3, "hint": "周囲からエネルギーを奪って状態が変化するものを探しましょう。", "book": "理論編 第15講"}, {"id": "q-th-095", "lecture": "th-15", "unit": "ヘスの法則", "type": "choice", "q": "黒鉛 C の燃焼熱を Q1 kJ/mol、一酸化炭素 CO の燃焼熱を Q2 kJ/mol とするとき、一酸化炭素の生成熱 Q3 kJ/mol を求める式として正しいものはどれか。", "choices": ["Q3 = Q1 + Q2", "Q3 = Q1 - Q2", "Q3 = Q2 - Q1", "Q3 = (Q1 + Q2) / 2"], "answer": 1, "hint": "「(炭素の燃焼熱) = (一酸化炭素の生成熱) + (一酸化炭素の燃焼熱)」の関係を考えます。", "book": "理論編 第15講"}, {"id": "q-th-096", "lecture": "th-15", "unit": "結合エネルギー", "type": "numeric", "q": "水 H2O(気)の生成熱は 241 kJ/mol である。H-H の結合エネルギーを 432 kJ/mol、O=O の結合エネルギーを 494 kJ/mol とするとき、O-H の結合エネルギーは何 kJ/mol か。整数値で答えよ。", "answer": 460, "tolerance": 0.5, "hint": "水分子1つには O-H 結合が2つ含まれることに注意して、エネルギーの収支を計算しましょう。", "book": "理論編 第15講"}, {"id": "q-th-097", "lecture": "th-16", "unit": "ルシャトリエの原理", "type": "choice", "q": "アンモニア生成の可逆反応 N2(気) + 3H2(気) = 2NH3(気) + 92 kJ が平衡状態にあるとき、アンモニアの収率（平衡時の割合）を高くするための条件として正しいものはどれか。", "choices": ["温度を上げて、全圧を低くする", "温度を下げて、全圧を高くする", "触媒を加えて、体積を大きくする", "体積を一定に保ち、希ガス（アルゴン）を加える"], "answer": 1, "hint": "発熱反応であることと、反応前後での分子数の変化（4分子から2分子）に注目しましょう。", "book": "理論編 第16講"}, {"id": "q-th-098", "lecture": "th-16", "unit": "反応速度", "type": "choice", "q": "2.0 mol/L の塩酸 100 mL に 1.0 g の亜鉛を入れ、水素を発生させた。この反応の開始直後の反応速度を「小さくする」操作として最も適切なものはどれか。", "choices": ["1.0 mol/L の塩酸 200 mL に変更する", "3.0 mol/L の塩酸 100 mL に変更する", "亜鉛を細かく砕いて粉末状にする", "反応容器を温めて溶液の温度を上げる"], "answer": 0, "hint": "反応速度は、反応物の濃度、温度、表面積に依存します。", "book": "理論編 第16講"}, {"id": "q-th-099", "lecture": "th-16", "unit": "平衡定数", "type": "numeric", "q": "容積 2.0 L の密閉容器に水素 H2 4.0 mol とヨウ素 I2 4.0 mol を入れ、一定温度に保った。反応 H2(気) + I2(気) <-> 2HI(気) が平衡に達したとき、ヨウ化水素 HI が 6.0 mol 生成していた。この温度における平衡定数 Kc の値を求めよ。", "answer": 36, "tolerance": 0.1, "hint": "平衡時の各物質のモル濃度（mol/L）を求めてから、平衡定数の式に代入しましょう。", "book": "理論編 第16講"}, {"id": "q-th-100", "lecture": "th-17", "unit": "電離平衡と溶解度積", "type": "choice", "q": "一定温度で、濃度 C [mol/L] の弱酸（電離定数 Ka）の電離度を a とすると、a ≪ 1 のとき a = √(Ka/C) と近似できる。この弱酸の溶液を純水で希釈して全量を元の4倍にしたとき、希釈後の電離度 a と水素イオン濃度 [H+] は、希釈前と比べてそれぞれ何倍になるか。正しい組み合わせを選べ。", "choices": ["a は2倍、[H+] は1/2倍", "a は4倍、[H+] は1/4倍", "a は1/2倍、[H+] は2倍", "a は2倍、[H+] は1/4倍"], "answer": 0, "hint": "濃度が 1/4倍になったとき、近似式 a = √(Ka/C) と [H+] = Ca がどのように変化するかを計算します。", "book": "理論編 第17講"}, {"id": "q-th-101", "lecture": "th-17", "unit": "電離平衡と溶解度積", "type": "choice", "q": "塩化銀 AgCl の 25度における溶解度積 Ksp を 1.0 * 10^-10 (mol/L)^2 とする。あらかじめ塩化ナトリウムを溶かして塩化物イオン濃度 [Cl-] を 1.0 * 10^-2 mol/L に調整した水溶液 1.0 L がある。25度において、この水溶液に溶けることができる銀イオン Ag+ の最大濃度 [mol/L] はいくらか。", "choices": ["1.0 * 10^-8", "1.0 * 10^-5", "1.0 * 10^-12", "1.0 * 10^-2"], "answer": 0, "hint": "共通イオン効果が働くため、[Ag+][Cl-] = Ksp の関係式に既知の [Cl-] を代入して [Ag+] を求めます。", "book": "理論編 第17講"}, {"id": "q-th-102", "lecture": "th-17", "unit": "電離平衡と溶解度積", "type": "numeric", "q": "水酸化マグネシウム Mg(OH)2 の 25度における溶解度積 Ksp は 4.0 * 10^-12 (mol/L)^3 である。25度における水酸化マグネシウムの飽和水溶液中のマグネシウムイオン Mg2+ の濃度 [mol/L] を求めよ。", "answer": 0.0001, "tolerance": 1e-06, "hint": "Mg(OH)2 が 1 mol 溶けると OH- は 2 mol 生じるため、[OH-] = 2[Mg2+] となることに注意して Ksp の式を立てます。", "book": "理論編 第17講"}]}, {"field": "inorganic", "fieldLabel": "無機", "lectures": [{"id": "inorg-01", "title": "第1講 沈殿と系統分析", "book": "無機編 第1講"}, {"id": "inorg-02", "title": "第2講 金属の反応と反応式の組み立て", "book": "無機編 第2講"}, {"id": "inorg-03", "title": "第3講 気体", "book": "無機編 第3講"}, {"id": "inorg-04", "title": "第4講 工業的製法と酸", "book": "無機編 第4講"}, {"id": "inorg-05", "title": "第5講 ハロゲン", "book": "無機編 第5講"}, {"id": "inorg-06", "title": "第6講 アルカリ金属・2族とカルシウム化合物", "book": "無機編 第6講"}, {"id": "inorg-07", "title": "第7講 鉄・遷移元素とケイ素", "book": "無機編 第7講"}], "cards": [{"id": "card-inorg-01", "lecture": "inorg-01", "name": "Ag+", "kind": "イオン", "points": [{"label": "色・沈殿", "text": "Cl-と反応してAgCl（白色沈殿）、少量の塩基でAg2O（褐色沈殿）を生じる。", "blind": true, "masks": ["AgCl（白色沈殿）", "Ag2O（褐色沈殿）"]}, {"label": "性質・反応", "text": "過剰のアンモニア水に[Ag(NH3)2]+となって溶ける。AgClは光で黒変する。", "blind": true, "masks": ["[Ag(NH3)2]+", "黒変する"]}, {"label": "検出", "text": "希塩酸で生じた白色沈殿が、熱水には溶けずアンモニア水に溶ければAg+である。", "blind": true, "masks": ["熱水には溶けずアンモニア水に溶ければ"]}], "note": "まとめノート無機編 第1講"}, {"id": "card-inorg-02", "lecture": "inorg-01", "name": "Pb2+", "kind": "イオン", "points": [{"label": "色・沈殿", "text": "Cl-とPbCl2（白）、SO42-とPbSO4（白）、I-とPbI2（黄）の沈殿を生じる。", "blind": true, "masks": ["PbCl2（白）", "PbSO4（白）", "PbI2（黄）"]}, {"label": "性質・反応", "text": "PbCl2の沈殿は、熱水を加えると溶解度が大きくなり溶ける性質がある。", "blind": true, "masks": ["熱水を加えると溶解度が大きくなり溶ける"]}, {"label": "検出", "text": "希塩酸で生じた白色沈殿が、熱水を加えると溶ければPb2+である。", "blind": true, "masks": ["熱水を加えると溶ければ"]}], "note": "まとめノート無機編 第1講"}, {"id": "card-inorg-03", "lecture": "inorg-01", "name": "Zn2+", "kind": "イオン", "points": [{"label": "色・沈殿", "text": "塩基性条件でH2Sと反応し、ZnS（白色沈殿）を生じる。硫化物で白は珍しい。", "blind": true, "masks": ["ZnS（白色沈殿）"]}, {"label": "性質・反応", "text": "両性元素のため、過剰のNaOHで[Zn(OH)4]2-、過剰のNH3で[Zn(NH3)4]2+となり溶ける。", "blind": true, "masks": ["[Zn(OH)4]2-", "[Zn(NH3)4]2+"]}, {"label": "検出", "text": "酸性ではH2Sで沈殿せず、アンモニア水で塩基性にすると白色沈殿を生じることで確認する。", "blind": true, "masks": ["塩基性にすると白色沈殿を生じる"]}], "note": "まとめノート無機編 第1講"}, {"id": "card-inorg-04", "lecture": "inorg-01", "name": "Al3+", "kind": "イオン", "points": [{"label": "色・沈殿", "text": "アンモニア水や少量のNaOHでAl(OH)3（白色沈殿）を生じる。", "blind": true, "masks": ["Al(OH)3（白色沈殿）"]}, {"label": "性質・反応", "text": "両性元素のため過剰のNaOHには[Al(OH)4]-となり溶けるが、過剰のNH3には溶けない。", "blind": true, "masks": ["[Al(OH)4]-", "過剰のNH3には溶けない"]}, {"label": "検出", "text": "アンモニア水で生じた白色沈殿が、過剰のNaOHを加えたときだけ溶ければAl3+である。", "blind": true, "masks": ["過剰のNaOHを加えたときだけ溶ければ"]}], "note": "まとめノート無機編 第1講"}, {"id": "card-inorg-05", "lecture": "inorg-02", "name": "Al（金属）", "kind": "物質", "points": [{"label": "性質・反応", "text": "高温水蒸気と反応してH2を出す。濃硝酸には不動態（酸化物の被膜）を作り溶けない。", "blind": true, "masks": ["H2を出す", "不動態（酸化物の被膜）"]}, {"label": "性質・反応", "text": "両性金属のため、酸だけでなく強塩基（NaOHaq）とも反応してH2を発生して溶ける。", "blind": true, "masks": ["強塩基（NaOHaq）"]}, {"label": "酸化物", "text": "酸化物Al2O3は両性酸化物で、酸にも強塩基にも錯イオンを作って溶ける。", "blind": true, "masks": ["両性酸化物"]}], "note": "まとめノート無機編 第2講"}, {"id": "card-inorg-06", "lecture": "inorg-02", "name": "Cu（金属）", "kind": "物質", "points": [{"label": "性質・反応", "text": "イオン化傾向がHより小さいため、希塩酸とは反応しないが、酸化力のある酸には溶ける。", "blind": true, "masks": ["希塩酸とは反応しない", "酸化力のある酸"]}, {"label": "性質・反応", "text": "希硝酸でNO（無色）、濃硝酸でNO2（赤褐色）、熱濃硫酸でSO2を発生して溶ける。", "blind": true, "masks": ["NO（無色）", "NO2（赤褐色）", "SO2"]}, {"label": "色・沈殿", "text": "高温で酸化されてCuOになる。Cu2+は過剰のNH3で[Cu(NH3)4]2+（深青色）になる。", "blind": true, "masks": ["CuO", "[Cu(NH3)4]2+（深青色）"]}], "note": "まとめノート無機編 第2講"}, {"id": "card-inorg-07", "lecture": "inorg-03", "name": "NH3", "kind": "物質", "points": [{"label": "色・におい", "text": "無色で刺激臭がある。水に非常によく溶ける。", "blind": true, "masks": ["刺激臭", "非常によく溶ける"]}, {"label": "性質・反応", "text": "唯一の塩基性気体。上方置換で捕集する。", "blind": true, "masks": ["唯一の塩基性気体", "上方置換"]}, {"label": "製法", "text": "塩化アンモニウムに水酸化カルシウムを加えて加熱する（弱塩基の遊離）。", "blind": true, "masks": ["塩化アンモニウムに水酸化カルシウムを加えて加熱する"]}, {"label": "乾燥", "text": "塩基性のソーダ石灰を用いる。濃H2SO4やCaCl2は反応するため不可。", "blind": true, "masks": ["ソーダ石灰", "濃H2SO4やCaCl2"]}], "note": "まとめノート無機編 第3講"}, {"id": "card-inorg-08", "lecture": "inorg-03", "name": "Cl2", "kind": "物質", "points": [{"label": "色・におい", "text": "黄緑色で刺激臭がある有毒な気体。", "blind": true, "masks": ["黄緑色", "有毒"]}, {"label": "検出", "text": "強い酸化作用を持ち、ヨウ化カリウムデンプン紙を青変させる。", "blind": true, "masks": ["ヨウ化カリウムデンプン紙を青変させる"]}, {"label": "製法", "text": "MnO2に濃塩酸を加えて加熱、またはさらし粉に塩酸を加える。", "blind": true, "masks": ["MnO2に濃塩酸を加えて加熱", "さらし粉に塩酸を加える"]}, {"label": "精製", "text": "洗気瓶で水（HCl除去）、濃H2SO4（水蒸気除去）の順に通す。", "blind": true, "masks": ["水（HCl除去）、濃H2SO4（水蒸気除去）の順"]}], "note": "まとめノート無機編 第3講"}, {"id": "card-inorg-09", "lecture": "inorg-03", "name": "SO2", "kind": "物質", "points": [{"label": "色・におい", "text": "無色で刺激臭がある。", "blind": true, "masks": ["刺激臭"]}, {"label": "性質・反応", "text": "還元剤として働き、漂白作用（色素を還元）を持つ。水にやや溶け、水溶液は酸性。", "blind": true, "masks": ["還元剤", "漂白作用", "酸性"]}, {"label": "捕集", "text": "水に溶けやすく、空気（28.8）より重い（64）ため下方置換を用いる。", "blind": true, "masks": ["下方置換"]}], "note": "まとめノート無機編 第3講"}, {"id": "card-inorg-10", "lecture": "inorg-04", "name": "Na2CO3", "kind": "物質", "points": [{"label": "製法", "text": "アンモニアソーダ法（ソルベー法）で食塩と石灰石から作る。", "blind": true, "masks": ["アンモニアソーダ法（ソルベー法）", "食塩と石灰石"]}, {"label": "中間体", "text": "まずNaHCO3を沈殿させ、これを加熱してNa2CO3を得る。", "blind": true, "masks": ["NaHCO3", "Na2CO3"]}, {"label": "循環", "text": "アンモニアNH3と二酸化炭素CO2は、工程内で回収して再利用される。", "blind": true, "masks": ["アンモニアNH3と二酸化炭素CO2"]}], "note": "まとめノート無機編 第4講"}, {"id": "card-inorg-11", "lecture": "inorg-04", "name": "H2SO4", "kind": "物質", "points": [{"label": "製法", "text": "接触法。SやFeS2からSO2を作り、V2O5触媒でSO3にしてから濃H2SO4に吸収させる。", "blind": true, "masks": ["接触法", "V2O5触媒", "濃H2SO4に吸収させる"]}, {"label": "濃硫酸の性質", "text": "不揮発性、吸湿性、脱水性、熱濃硫酸での酸化力を持つ。", "blind": true, "masks": ["不揮発性、吸湿性、脱水性", "酸化力"]}, {"label": "希釈", "text": "多量の水に濃硫酸を少しずつ加える。逆は沸騰・飛散の危険がある。", "blind": true, "masks": ["多量の水に濃硫酸を少しずつ加える"]}], "note": "まとめノート無機編 第4講"}, {"id": "card-inorg-12", "lecture": "inorg-04", "name": "HNO3", "kind": "物質", "points": [{"label": "製法", "text": "オストワルト法。NH3をPt触媒でNOにし、さらに酸化してNO2を水に吸収させる。", "blind": true, "masks": ["オストワルト法", "Pt触媒"]}, {"label": "性質・反応", "text": "強酸で強い酸化力を持つ。濃硝酸はNO2、希硝酸はNOを発生させる。", "blind": true, "masks": ["濃硝酸はNO2、希硝酸はNOを発生させる"]}, {"label": "保存", "text": "光で分解してNO2を生じるため、褐色ビンに入れて保存する。", "blind": true, "masks": ["褐色ビン"]}], "note": "まとめノート無機編 第4講"}, {"id": "card-inorg-13", "lecture": "inorg-05", "name": "AgCl（塩化銀）", "kind": "物質", "points": [{"label": "色・沈殿", "text": "白色沈殿。AgFだけが水によく溶け、AgCl・AgBr・AgIは沈殿する。", "blind": true, "masks": ["AgFだけが水によく溶け"]}, {"label": "性質・反応", "text": "感光性があり、光によって分解して銀を析出する。", "blind": true, "masks": ["銀を析出する"]}, {"label": "検出", "text": "アンモニア水を加えると錯イオン [Ag(NH3)2]+ となって溶ける。", "blind": true, "masks": ["[Ag(NH3)2]+"]}], "note": "まとめノート無機編 第5講"}, {"id": "card-inorg-14", "lecture": "inorg-05", "name": "HF（フッ化水素）", "kind": "物質", "points": [{"label": "性質・反応", "text": "ハロゲン化水素の中で唯一の弱酸。分子間に水素結合を作るため沸点が異常に高い。", "blind": true, "masks": ["唯一の弱酸", "水素結合", "沸点が異常に高い"]}, {"label": "性質・反応", "text": "ガラスの主成分 SiO2 を溶かす。水溶液中では H2SiF6 を生じる。", "blind": true, "masks": ["SiO2", "H2SiF6"]}, {"label": "保存", "text": "ガラスを侵すため、ポリエチレン製の容器に保存する。", "blind": true, "masks": ["ポリエチレン製の容器"]}], "note": "まとめノート無機編 第5講"}, {"id": "card-inorg-15", "lecture": "inorg-06", "name": "NaOH（水酸化ナトリウム）", "kind": "物質", "points": [{"label": "性質・反応", "text": "代表的な強塩基。潮解性をもち、空気中の水分を吸収して溶ける。", "blind": true, "masks": ["潮解性"]}, {"label": "性質・反応", "text": "空気中の CO2 を吸収して Na2CO3 に変わるため、密閉して保存する。", "blind": true, "masks": ["Na2CO3"]}, {"label": "製法", "text": "塩化ナトリウム水溶液の電気分解（隔膜法）により、陰極側で得られる。", "blind": true, "masks": ["隔膜法", "陰極側"]}], "note": "まとめノート無機編 第6講"}, {"id": "card-inorg-16", "lecture": "inorg-06", "name": "Ca(OH)2（水酸化カルシウム）", "kind": "物質", "points": [{"label": "色・沈殿", "text": "飽和水溶液は石灰水とよばれる。強塩基だが、Ca・Sr・Baの水酸化物の中では溶解度が比較的小さい。", "blind": true, "masks": ["石灰水"]}, {"label": "検出", "text": "CO2 を通すと CaCO3 の白色沈殿を生じて白濁する。さらに通すと溶ける。", "blind": true, "masks": ["CaCO3 の白色沈殿", "さらに通すと溶ける"]}, {"label": "製法", "text": "CaOに水を加えると得られる（CaO + H2O → Ca(OH)2）。", "blind": true, "masks": ["CaOに水を加える"]}], "note": "まとめノート無機編 第6講"}, {"id": "card-inorg-17", "lecture": "inorg-07", "name": "Fe2+・Fe3+（鉄イオン）", "kind": "イオン", "points": [{"label": "色・沈殿", "text": "Fe2+ は淡緑色、Fe3+ は黄褐色の水溶液。Fe2+ は酸化されて Fe3+ になりやすい。", "blind": true, "masks": ["淡緑色", "黄褐色"]}, {"label": "検出", "text": "Fe3+ に KSCN を加えると、血赤色の溶液（錯イオン）になる。", "blind": true, "masks": ["KSCN", "血赤色"]}, {"label": "検出", "text": "Fe2+ に K3[Fe(CN)6] を、Fe3+ に K4[Fe(CN)6] を加えると、共に濃青色沈殿を生じる。", "blind": true, "masks": ["K3[Fe(CN)6]", "K4[Fe(CN)6]", "濃青色沈殿"]}], "note": "まとめノート無機編 第7講"}, {"id": "card-inorg-18", "lecture": "inorg-07", "name": "SiO2（二酸化ケイ素）", "kind": "物質", "points": [{"label": "色・沈殿", "text": "石英や水晶の主成分。Si と O が三次元に網目状につながった共有結合結晶。", "blind": true, "masks": ["石英や水晶", "共有結合結晶"]}, {"label": "性質・反応", "text": "酸性酸化物であり、濃NaOH水溶液と加熱すると、またNa2CO3と高温で溶融すると、Na2SiO3になる。", "blind": true, "masks": ["Na2SiO3"]}, {"label": "性質・反応", "text": "強酸には溶けないが、フッ化水素酸 HF には溶ける。", "blind": true, "masks": ["フッ化水素酸 HF"]}], "note": "まとめノート無機編 第7講"}], "questions": [{"id": "q-inorg-001", "lecture": "inorg-01", "unit": "沈殿と系統分析", "type": "choice", "q": "Ag+とPb2+を含む水溶液に希塩酸を加えたときに生じる沈殿について、熱水を加えたときの挙動として正しいものはどれか。", "choices": ["PbCl2のみが溶け、AgClは残る。", "AgClのみが溶け、PbCl2は残る。", "AgClとPbCl2の両方が溶ける。", "どちらの沈殿も溶けずに残る。"], "answer": 0, "hint": "PbCl2は温度が上がると溶解度が大きくなる性質があります。", "book": "無機編 第1講"}, {"id": "q-inorg-002", "lecture": "inorg-01", "unit": "沈殿と系統分析", "type": "choice", "q": "水溶液中にCu2+、Fe3+、Zn2+が混ざっている。液性を酸性にしてH2Sを吹き込んだとき、沈殿する物質の化学式はどれか。", "choices": ["FeS", "CuS", "すべての硫化物が沈殿する", "ZnS"], "answer": 1, "hint": "酸性条件で沈殿するのは、Kspが極端に小さいイオン化傾向がSn以下の金属の硫化物です。", "book": "無機編 第1講"}, {"id": "q-inorg-003", "lecture": "inorg-01", "unit": "沈殿と系統分析", "type": "choice", "q": "Fe(OH)3とAl(OH)3の混合沈殿に過剰の水酸化ナトリウム水溶液を加えたとき、起こる変化として正しいものはどれか。", "choices": ["どちらも水酸化物なので、強塩基には反応せず溶けない。", "両方の沈殿が溶けて、透明な溶液になる。", "Al(OH)3のみが[Al(OH)4]-となって溶け、Fe(OH)3は残る。", "Fe(OH)3のみが溶け、Al(OH)3は残る。"], "answer": 2, "hint": "Alは両性元素ですが、Feは両性元素ではありません。", "book": "無機編 第1講"}, {"id": "q-inorg-004", "lecture": "inorg-01", "unit": "沈殿と系統分析", "type": "choice", "q": "系統分析において、アンモニア水を加えてFe(OH)3を沈殿させる前に、煮沸して硝酸を加える後処理を行う理由として正しいものはどれか。", "choices": ["液性を酸性から塩基性に変えるため。", "溶液中のCl-を除去するため。", "Al3+をAl(OH)3として沈殿させないようにするため。", "H2Sで還元されたFe2+を、沈殿しやすいFe3+に酸化するため。"], "answer": 3, "hint": "Fe2+よりもFe3+の方が水酸化物として沈殿しやすい性質を利用します。", "book": "無機編 第1講"}, {"id": "q-inorg-005", "lecture": "inorg-01", "unit": "沈殿と系統分析", "type": "choice", "q": "テトラアンミン銅(II)イオンの化学式と立体構造の組み合わせとして正しいものはどれか。", "choices": ["[Cu(NH3)2]+ ・ 直線形", "[Cu(NH3)4]2+ ・ 正方形（平面正方形）形", "[Cu(NH3)4]2+ ・ 正四面体形", "[Cu(NH3)6]2+ ・ 正八面体形"], "answer": 1, "hint": "Cu2+の配位数は4ですが、Zn2+とは形が異なります。", "book": "無機編 第1講"}, {"id": "q-inorg-006", "lecture": "inorg-02", "unit": "金属の反応と反応式の組み立て", "type": "choice", "q": "次の金属のうち、高温の水蒸気とは反応するが、冷水や沸騰水（熱水）とは反応しないものはどれか。", "choices": ["Fe", "Na", "Cu", "Mg"], "answer": 0, "hint": "Mgは沸騰水まで、Feは高温水蒸気まで反応します。", "book": "無機編 第2講"}, {"id": "q-inorg-007", "lecture": "inorg-02", "unit": "金属の反応と反応式の組み立て", "type": "choice", "q": "銅19.2 gを十分な量の希硝酸と完全に反応させた。このとき発生する一酸化窒素NOの標準状態での体積は何Lか（Cu=64）。", "choices": ["6.72 L", "2.24 L", "13.4 L", "4.48 L"], "answer": 3, "hint": "反応式は 3Cu + 8HNO3 -> 3Cu(NO3)2 + 2NO + 4H2O です。Cu:NO = 3:2 の比を使います。", "book": "無機編 第2講"}, {"id": "q-inorg-008", "lecture": "inorg-02", "unit": "金属の反応と反応式の組み立て", "type": "choice", "q": "鉄FeやアルミニウムAlを濃硝酸に入れると、表面に緻密な酸化物の被膜ができて反応が止まる現象を何というか。", "choices": ["不動態", "共鳴", "遊離", "中和"], "answer": 0, "hint": "イオン化傾向が大きいにもかかわらず、濃い酸に溶けなくなる特殊な状態です。", "book": "無機編 第2講"}, {"id": "q-inorg-009", "lecture": "inorg-02", "unit": "金属の反応と反応式の組み立て", "type": "choice", "q": "アルミニウム5.4 gを十分な量の水酸化ナトリウム水溶液と反応させたとき、標準状態で発生する水素H2の体積は何Lか（Al=27）。", "choices": ["10.1 L", "4.48 L", "3.36 L", "6.72 L"], "answer": 3, "hint": "反応式は 2Al + 2NaOH + 6H2O -> 2Na[Al(OH)4] + 3H2 です。Al:H2 = 2:3 の比を使います。", "book": "無機編 第2講"}, {"id": "q-inorg-010", "lecture": "inorg-02", "unit": "金属の反応と反応式の組み立て", "type": "choice", "q": "揮発性の酸の遊離について、フッ化カルシウムCaF2に濃硫酸を加えて加熱した際、反応が2段階目まで進みCaSO4が生成する理由として正しいものはどれか。", "choices": ["CaF2が水に溶けにくい塩だから。", "生成するHFが弱酸であり、HSO4-が出す弱いH+でも受け取って結合するから。", "硫酸が揮発性の酸だから。", "フッ素Fの電気陰性度がNaよりも大きいから。"], "answer": 1, "hint": "相手の酸が弱酸（HF）か強酸（HClやHNO3）かによって、HSO4-がH+を渡せるかどうかが決まります。", "book": "無機編 第2講"}, {"id": "q-inorg-011", "lecture": "inorg-03", "unit": "第3講 気体", "type": "choice", "q": "気体の製法について、その「型」の分類として誤っているものはどれか。", "choices": ["HCOOHに濃H2SO4を加えて加熱しCOを得る反応は、酸化還元反応である。", "NH4NO2を加熱してN2を得る反応は、分解反応である。", "CaF2に濃H2SO4を加えて加熱しHFを得る反応は、揮発性の酸の遊離である。", "NH4ClにCa(OH)2を加えて加熱しNH3を得る反応は、弱塩基の遊離である。"], "answer": 0, "hint": "ギ酸からのCO生成は、濃硫酸の脱水作用によるものです。", "book": "無機編 第3講"}, {"id": "q-inorg-012", "lecture": "inorg-03", "unit": "第3講 気体", "type": "choice", "q": "MnO2と濃塩酸を加熱して塩素を発生させ、精製する実験について、正しい記述はどれか。", "choices": ["塩素は空気より軽いため、上方置換で捕集する。", "1本目の洗気瓶に濃硫酸、2本目に水を用いるのが正しい順序である。", "KMnO4を酸化剤に用いる方が、MnO2よりも反応の制御がしやすく安全である。", "1本目の洗気瓶に水を用いるのは、混入した塩化水素HClを除くためである。"], "answer": 3, "hint": "水でHClを除き、その後に濃硫酸で乾燥させる順序が鉄則です。", "book": "無機編 第3講"}, {"id": "q-inorg-013", "lecture": "inorg-03", "unit": "第3講 気体", "type": "choice", "q": "気体の捕集法について、水上置換を用いるのが最も適切なものはどれか。", "choices": ["二酸化窒素 NO2", "二酸化硫黄 SO2", "塩化水素 HCl", "一酸化窒素 NO"], "answer": 3, "hint": "水に溶けにくい気体を選びましょう。NO2は水と反応して硝酸などになります。", "book": "無機編 第3講"}, {"id": "q-inorg-014", "lecture": "inorg-03", "unit": "第3講 気体", "type": "choice", "q": "乾燥剤と気体の組み合わせのうち、化学反応が起こるため「使用できない」ものはどれか。", "choices": ["濃H2SO4 ＋ H2S", "CaCl2 ＋ HCl", "ソーダ石灰 ＋ NH3", "濃H2SO4 ＋ Cl2"], "answer": 0, "hint": "濃硫酸には酸化力があり、還元剤であるH2Sと反応してしまいます。", "book": "無機編 第3講"}, {"id": "q-inorg-015", "lecture": "inorg-03", "unit": "第3講 気体", "type": "choice", "q": "塩素酸カリウム KClO3（式量122.5）12.25g に触媒を加えて加熱し、完全に分解させた。発生する酸素の標準状態での体積として正しいものはどれか。", "choices": ["1.12 L", "2.24 L", "3.36 L", "4.48 L"], "answer": 2, "hint": "反応式 2KClO3 → 2KCl + 3O2 より、KClO3の1.5倍のモルの酸素が生じます。", "book": "無機編 第3講"}, {"id": "q-inorg-016", "lecture": "inorg-04", "unit": "第4講 工業的製法と酸", "type": "choice", "q": "アンモニアソーダ法の全体式 2NaCl + CaCO3 → Na2CO3 + CaCl2 に基づき、食塩 NaCl（式量58.5）58.5kg を反応させたとき、得られる炭酸ナトリウム Na2CO3（式量106）の質量は何 kg か。", "choices": ["106 kg", "212 kg", "26.5 kg", "53 kg"], "answer": 3, "hint": "NaCl 2mol から Na2CO3 1mol が得られる係数比に注目しましょう。", "book": "無機編 第4講"}, {"id": "q-inorg-017", "lecture": "inorg-04", "unit": "第4講 工業的製法と酸", "type": "choice", "q": "アルミニウムの製法（バイヤー法・ホール・エルー法）について、正しい記述はどれか。", "choices": ["不純物の酸化鉄(III) Fe2O3 は、強塩基に溶けるためろ過では除けない。", "氷晶石を加えるのは、酸化アルミニウムの融点を下げるためである。", "陽極の炭素電極は反応に関与しないため、摩耗することはない。", "アルミニウムはイオン化傾向が小さいため、水溶液の電気分解で得られる。"], "answer": 1, "hint": "氷晶石は融点を約2070度から950度まで下げてくれます。", "book": "無機編 第4講"}, {"id": "q-inorg-018", "lecture": "inorg-04", "unit": "第4講 工業的製法と酸", "type": "choice", "q": "オストワルト法（硝酸の工業的製法）の工程(3)「3NO2 + H2O → 2HNO3 + NO」で生じた一酸化窒素 NO は、その後どのように扱われるか。", "choices": ["工程(2)の NO の酸化工程に戻して再利用する。", "白金 Pt 触媒の表面を洗浄するために用いる。", "空気中に放出して廃棄する。", "アンモニア NH3 と反応させて還元し、N2 に戻す。"], "answer": 0, "hint": "工業的製法では「中間体は再利用する」のが原則です。", "book": "無機編 第4講"}, {"id": "q-inorg-019", "lecture": "inorg-04", "unit": "第4講 工業的製法と酸", "type": "choice", "q": "接触法において、黄鉄鉱 FeS2（式量120）60kg を原料としたとき、最終的に得られる硫酸 H2SO4（式量98）の理論上の最大質量は何 kg か。", "choices": ["49 kg", "98 kg", "120 kg", "196 kg"], "answer": 1, "hint": "FeS2 1mol には硫黄原子が 2mol 含まれているため、H2SO4 は 2mol 生じます。", "book": "無機編 第4講"}, {"id": "q-inorg-020", "lecture": "inorg-04", "unit": "第4講 工業的製法と酸", "type": "choice", "q": "濃硫酸の性質に関する記述として、誤っているものはどれか。", "choices": ["ショ糖に加えると、脱水作用により黒い炭素が残る。", "エタノールに加えて約170℃に加熱すると、エチレンが生成する。", "不揮発性であるため、揮発性の酸の塩（NaCl等）から酸を追い出せる。", "希硫酸に比べると電離度が大きく、より強い酸性を示す。"], "answer": 3, "hint": "濃硫酸は水が少ないため、ほとんど電離せずに分子のまま存在しています。", "book": "無機編 第4講"}, {"id": "q-inorg-021", "lecture": "inorg-05", "unit": "ハロゲン", "type": "choice", "q": "ハロゲン単体の酸化力の強さの順序として正しいものはどれか。", "choices": ["F2 > Cl2 > Br2 > I2", "I2 > Br2 > Cl2 > F2", "Cl2 > F2 > Br2 > I2", "F2 > Cl2 > I2 > Br2"], "answer": 0, "hint": "周期表で上にある元素ほど、他の物質から電子を奪う力が強くなります。", "book": "無機編 第5講"}, {"id": "q-inorg-022", "lecture": "inorg-05", "unit": "ハロゲン", "type": "choice", "q": "フッ化水素 HF の沸点が、他のハロゲン化水素に比べて異常に高い理由として適切なものはどれか。", "choices": ["分子間に水素結合がはたらくから。", "水溶液が弱酸であるから。", "分子内の共有結合が非常に強いから。", "分子量が最も小さいから。"], "answer": 0, "hint": "HF 分子どうしを強く結びつける特別な結合を考えます。", "book": "無機編 第5講"}, {"id": "q-inorg-023", "lecture": "inorg-05", "unit": "ハロゲン", "type": "choice", "q": "ヨウ化銀 AgI の沈殿の色はどれか。", "choices": ["黒紫色", "白色", "黄色", "淡黄色"], "answer": 2, "hint": "AgCl が白、AgBr が淡黄色、AgI はさらに濃い色になります。", "book": "無機編 第5講"}, {"id": "q-inorg-024", "lecture": "inorg-05", "unit": "ハロゲン", "type": "choice", "q": "フッ化水素酸を保存する容器として、最も適切なものはどれか。", "choices": ["鉄製の容器", "透明なガラス瓶", "ポリエチレン製の容器", "褐色のガラス瓶"], "answer": 2, "hint": "HF はガラスの主成分である SiO2 と反応して溶かしてしまいます。", "book": "無機編 第5講"}, {"id": "q-inorg-025", "lecture": "inorg-05", "unit": "ハロゲン", "type": "choice", "q": "二酸化ケイ素 SiO2 12g をフッ化水素酸に完全に溶かすとき、必要な HF は何 mol か。原子量は Si=28, O=16 とする。", "choices": ["0.40 mol", "0.20 mol", "1.2 mol", "0.80 mol"], "answer": 2, "hint": "反応式 SiO2 + 6HF -> H2SiF6 + 2H2O より、係数比は 1:6 です。", "book": "無機編 第5講"}, {"id": "q-inorg-026", "lecture": "inorg-06", "unit": "アルカリ金属・2族", "type": "choice", "q": "ナトリウムの単体を石油（灯油）中に保存する理由として正しいものはどれか。", "choices": ["光による分解を防ぐため。", "蒸発して失われるのを防ぐため。", "空気中の酸素や水と反応するのを防ぐため。", "空気中の窒素と反応するのを防ぐため。"], "answer": 2, "hint": "Na はイオン化傾向が非常に大きく、O2 や H2O とすぐに反応してしまいます。", "book": "無機編 第6講"}, {"id": "q-inorg-027", "lecture": "inorg-06", "unit": "アルカリ金属・2族", "type": "choice", "q": "炭酸ナトリウム十水和物の結晶を空気中に放置すると、水和水の一部を失って白色粉末になる。この現象を何というか。", "choices": ["昇華", "風解", "潮解と風解の両方", "潮解"], "answer": 1, "hint": "水分を吸うのが潮解、結晶から水が抜けていくのがこの現象です。", "book": "無機編 第6講"}, {"id": "q-inorg-028", "lecture": "inorg-06", "unit": "アルカリ金属・2族", "type": "choice", "q": "2族元素の Mg と Ca の性質について、正しい記述はどれか。", "choices": ["Mg は冷水と激しく反応する。", "Mg は冷水とは反応しないが、熱水とは反応する。", "Ca は熱水とは反応するが、冷水とは反応しない。", "Mg も Ca も冷水とは反応しない。"], "answer": 1, "hint": "イオン化傾向は Ca > Mg です。Ca は冷水でも反応できます。", "book": "無機編 第6講"}, {"id": "q-inorg-029", "lecture": "inorg-06", "unit": "アルカリ金属・2族", "type": "choice", "q": "0.010 mol/L の水酸化カルシウム水溶液（石灰水）1.0 L に CO2 を通し続けた。白濁が完全に消えるまでに必要な CO2 は標準状態で何 mL か。", "choices": ["224 mL", "448 mL", "112 mL", "672 mL"], "answer": 1, "hint": "沈殿が生じるまでに 1等量、溶け直すまでにさらにもう 1等量の CO2 が必要です。", "book": "無機編 第6講"}, {"id": "q-inorg-030", "lecture": "inorg-06", "unit": "アルカリ金属・2族", "type": "choice", "q": "硫酸バリウム BaSO4 が X線造影剤として利用される主な理由として誤っているものはどれか。", "choices": ["Ba2+ が人体に有益なイオンだから。", "Ba が X線を吸収しやすいから。", "水に極めて溶けにくいから。", "胃酸に溶けず、体内に吸収されないから。"], "answer": 0, "hint": "Ba2+ は本来有毒ですが、不溶性のため吸収されずに排出されます。", "book": "無機編 第6講"}, {"id": "q-inorg-031", "lecture": "inorg-07", "unit": "鉄・遷移元素", "type": "choice", "q": "高炉における鉄の製錬において、鉄鉱石の直接の還元剤として主に働く物質はどれか。", "choices": ["二酸化炭素 (CO2)", "コークス (C)", "一酸化炭素 (CO)", "石灰石 (CaCO3)"], "answer": 2, "hint": "C が燃えてできたガスが、鉄鉱石から酸素を奪う段階還元の主役です。", "book": "無機編 第7講"}, {"id": "q-inorg-032", "lecture": "inorg-07", "unit": "鉄・遷移元素", "type": "choice", "q": "鉄(III)イオン Fe3+ を含む水溶液にチオシアン酸カリウム KSCN 水溶液を加えたときの変化として正しいものはどれか。", "choices": ["白色沈殿が生じる。", "濃青色沈殿が生じる。", "変化しない。", "血赤色の溶液になる。"], "answer": 3, "hint": "SCN- と錯イオンを作る Fe3+ 特有の検出反応です。", "book": "無機編 第7講"}, {"id": "q-inorg-033", "lecture": "inorg-07", "unit": "鉄・遷移元素", "type": "choice", "q": "アルミニウム粉末と酸化鉄(III)の混合物に点火して鉄を得る「テルミット反応」が起こる理由として正しいものはどれか。", "choices": ["Fe のイオン化傾向が Al より大きく、酸化されやすいから。", "Fe2O3 が熱によって自然に分解するから。", "Al のイオン化傾向が Fe より大きく、酸素と結びつきやすいから。", "Al が Fe より密度が小さく、浮き上がりやすいから。"], "answer": 2, "hint": "強い還元力を持つ金属が、他の金属の酸化物から酸素を奪う反応です。", "book": "無機編 第7講"}, {"id": "q-inorg-034", "lecture": "inorg-07", "unit": "ケイ素", "type": "choice", "q": "二酸化ケイ素 SiO2 0.50 mol をコークスで還元して単体のケイ素 Si を得るとき、得られる Si は何 g か。原子量は Si=28 とする。", "choices": ["28 g", "14 g", "56 g", "7.0 g"], "answer": 1, "hint": "反応式 SiO2 + 2C -> Si + 2CO より、SiO2 と Si の物質量比は 1:1 です。", "book": "無機編 第7講"}, {"id": "q-inorg-035", "lecture": "inorg-07", "unit": "ケイ素", "type": "choice", "q": "ケイ酸ナトリウムの水溶液（水ガラス）に塩酸を加えると、ケイ酸の白色沈殿が生じる。この反応の形式はどれか。", "choices": ["酸化還元反応", "中和反応", "弱酸の遊離", "複分解による沈殿生成"], "answer": 2, "hint": "非常に弱い酸であるケイ酸の塩に、強酸である塩酸を加えたときの反応です。", "book": "無機編 第7講"}, {"id": "q-inorg-036", "lecture": "inorg-01", "unit": "沈殿と系統分析", "type": "choice", "q": "溶液中に Cu2+、Zn2+、Fe2+、Mn2+ の4種類のイオンが含まれている。酸性条件下で硫化水素 H2S を通じたとき、沈殿を生じるイオンとして正しいものはどれか。", "choices": ["Cu2+", "Zn2+", "Fe2+", "Mn2+"], "answer": 0, "hint": "イオン化傾向が小さく、酸性でも硫化物をつくる金属を選びましょう。", "book": "無機編 第1講"}, {"id": "q-inorg-037", "lecture": "inorg-01", "unit": "沈殿と系統分析", "type": "choice", "q": "Al3+ と Zn2+ を含む混合水溶液に、過剰のアンモニア水を加えたときの変化として正しい記述はどれか。", "choices": ["Al3+ と Zn2+ の両方が沈殿し、沈殿はそのまま残る。", "Al3+ は沈殿するが、Zn2+ は錯イオンを形成して溶解する。", "Zn2+ は沈殿するが、Al3+ は錯イオンを形成して溶解する。", "Al3+ と Zn2+ の両方が錯イオンを形成して溶解する。"], "answer": 1, "hint": "アンモニア水に対して、錯イオンを作って溶けるのはどの金属か思い出しましょう。", "book": "無機編 第1講"}, {"id": "q-inorg-038", "lecture": "inorg-01", "unit": "沈殿と系統分析", "type": "choice", "q": "金属の硫化物の沈殿のうち、その色が「白色」であるものはどれか。", "choices": ["CuS", "PbS", "ZnS", "FeS"], "answer": 2, "hint": "硫化物の多くは黒色ですが、例外的な色のものがあります。", "book": "無機編 第1講"}, {"id": "q-inorg-039", "lecture": "inorg-02", "unit": "金属の反応", "type": "choice", "q": "鉄、コバルト、ニッケル、アルミニウムなどの金属を冷濃硝酸に入れたとき、表面に緻密な酸化被膜が生じて反応が止まる現象を何というか。", "choices": ["アマルガム", "不動態", "トタン", "ブリキ"], "answer": 1, "hint": "金属の表面が酸化され、内部が保護される特殊な状態のことです。", "book": "無機編 第2講"}, {"id": "q-inorg-040", "lecture": "inorg-02", "unit": "金属の反応", "type": "choice", "q": "酸化鉄(III) Fe2O3 とアルミニウム Al の粉末を混合して点火し、多量の熱とともに鉄の単体を得る反応を何というか。", "choices": ["ハーバー・ボッシュ法", "オストワルト法", "テルミット反応", "溶融塩電解"], "answer": 2, "hint": "鉄道のレールの溶接などにも利用される、Al の強い還元力を利用した反応です。", "book": "無機編 第2講"}, {"id": "q-inorg-041", "lecture": "inorg-02", "unit": "金属の反応", "type": "choice", "q": "次の金属のうち、冷水と激しく反応して水素 H2 を発生するものはどれか。", "choices": ["Mg", "Na", "Fe", "Cu"], "answer": 1, "hint": "イオン化傾向が非常に大きく、常温の水とも反応できる金属を探しましょう。", "book": "無機編 第2講"}, {"id": "q-inorg-042", "lecture": "inorg-03", "unit": "気体の捕集法", "type": "choice", "q": "二酸化硫黄(SO2)を試験管に集める方法として、最も適当なものはどれか。性質（水溶性と空気との密度比較）を考慮して選べ。", "choices": ["水に溶けにくいため、水上置換で捕集する。", "水に溶けやすく空気より軽いため、上方置換で捕集する。", "水に溶けやすく空気より重いため、下方置換で捕集する。", "空気中の酸素と直ちに反応するため、水上置換で捕集する。"], "answer": 2, "hint": "二酸化硫黄の分子量(64)と空気の平均分子量(29)を比較し、水への溶解性を思い出しましょう。", "book": "無機編 第3講"}, {"id": "q-inorg-043", "lecture": "inorg-03", "unit": "気体の乾燥", "type": "choice", "q": "気体と乾燥剤の組み合わせのうち、乾燥剤が「塩基性」であるために、酸性の気体の乾燥には適さないものはどれか。", "choices": ["二酸化炭素(CO2)を乾燥させるためのソーダ石灰", "アンモニア(NH3)を乾燥させるための酸化カルシウム(CaO)", "酸素(O2)を乾燥させるための十酸化四リン(P4O10)", "窒素(N2)を乾燥させるための濃硫酸(H2SO4)"], "answer": 0, "hint": "気体と乾燥剤の間で中和反応が起こる組み合わせを探しましょう。", "book": "無機編 第3講"}, {"id": "q-inorg-044", "lecture": "inorg-03", "unit": "気体の確認反応", "type": "choice", "q": "亜鉛(Zn)に希硫酸(H2SO4)を加えたときに発生する気体の性質と確認方法として、最も適当なものはどれか。", "choices": ["特有の刺激臭があり、湿らせた赤色リトマス紙を青変させる。", "無臭の気体であり、火を近づけると音を立てて燃える。", "無色の気体であり、石灰水に通すと白濁する。", "助燃性があり、火のついた線香を入れると激しく燃え上がる。"], "answer": 1, "hint": "イオン化傾向が水素より大きい金属に酸を加えたときに発生する気体を考えましょう。", "book": "無機編 第3講"}, {"id": "q-inorg-045", "lecture": "inorg-04", "unit": "アンモニアの合成", "type": "choice", "q": "ハーバー・ボッシュ法において、窒素(N2)と水素(H2)からアンモニア(NH3)を合成する際に用いられる触媒と反応条件の組み合わせとして正しいものはどれか。", "choices": ["四酸化三鉄(Fe3O4)を主成分とする触媒を用い、高圧にする。", "酸化バナジウム(V) (V2O5)を用い、常圧で反応させる。", "白金(Pt)を触媒として用い、低温・低圧にする。", "十酸化四リン(P4O10)を触媒として用い、高温にする。"], "answer": 0, "hint": "ルシャトリエの原理において、分子数が減少する方向に平衡を移動させる条件を考えましょう。", "book": "無機編 第4講"}, {"id": "q-inorg-046", "lecture": "inorg-04", "unit": "硫酸の性質", "type": "choice", "q": "濃硫酸(H2SO4)の性質に関する記述として正しいものはどれか。", "choices": ["強い脱水作用を持ち、ショ糖(C12H22O11)から水素と酸素を水の比率で奪い、黒い炭に変える。", "強い還元剤として働き、銅(Cu)と反応して水素(H2)を発生させる。", "揮発性の酸であり、塩化ナトリウム(NaCl)と反応させると速やかに塩化水素(HCl)が遊離する。", "希釈する際は、安全のため濃硫酸の中に水を少しずつ注ぎ入れる。"], "answer": 0, "hint": "濃硫酸特有の、化合物中から水分子の成分を引き抜く作用を思い出しましょう。", "book": "無機編 第4講"}, {"id": "q-inorg-047", "lecture": "inorg-04", "unit": "オストワルト法", "type": "choice", "q": "オストワルト法による硝酸(HNO3)の製造において、第一段階で得られた一酸化窒素(NO)を二酸化窒素(NO2)に変えるための操作として最も適当なものはどれか。", "choices": ["空気中の酸素と反応させる。", "白金触媒を用いて800度以上に加熱する。", "温水に溶かして不均化反応を起こさせる。", "濃硫酸を加えて酸化させる。"], "answer": 0, "hint": "一酸化窒素が空気中に触れたときの色の変化や反応性を思い出しましょう。", "book": "無機編 第4講"}, {"id": "q-inorg-048", "lecture": "inorg-05", "unit": "ハロゲン", "type": "choice", "q": "ヨウ化カリウム水溶液に塩素ガスを吹き込んだ際の変化に関する記述として、最も適当なものはどれか。", "choices": ["塩素の酸化力がヨウ素より強いため、ヨウ素が遊離して溶液が褐色になった。", "塩素の還元力がヨウ素より強いため、ヨウ化カリウムが還元されて無色のままだった。", "ヨウ素の酸化力が塩素より強いため、反応は進行せず色の変化は見られなかった。", "ヨウ化カリウムと塩素が中和反応を起こし、白色沈殿が生成した。"], "answer": 0, "hint": "ハロゲン単体の酸化力の強さと、周期表での位置関係を思い出しましょう。", "book": "無機編 第5講"}, {"id": "q-inorg-049", "lecture": "inorg-05", "unit": "ハロゲン", "type": "choice", "q": "フッ化水素およびフッ化水素酸の性質に関する記述として、最も適当なものはどれか。", "choices": ["二酸化ケイ素と反応して可溶性のヘキサフルオロケイ酸を生成するため、ガラスを腐食する。", "他のハロゲン化水素と同様に、水溶液中では塩酸よりも強い強酸として振る舞う。", "沸点は他のハロゲン化水素よりも低く、常温では気体として存在する。", "銀イオンと反応すると、塩化銀と同様に水に不溶な白色沈殿を生じる。"], "answer": 0, "hint": "フッ化水素は分子間に働く水素結合の影響や、ケイ素に対する特殊な反応性に注意が必要です。", "book": "無機編 第5講"}, {"id": "q-inorg-050", "lecture": "inorg-05", "unit": "ハロゲン", "type": "choice", "q": "さらし粉およびその関連物質に関する記述として正しいものはどれか。", "choices": ["さらし粉は、消石灰（水酸化カルシウム）に塩素を吸収させることで製造される。", "さらし粉の主成分は塩化ナトリウムと次亜塩素酸ナトリウムの混合物である。", "さらし粉に希塩酸を加えると、激しく酸素が発生して周囲の物質を酸化する。", "高度さらし粉は、さらし粉から塩化カルシウムを取り除いたもので、化学式はCaCl2である。"], "answer": 0, "hint": "さらし粉の原料となるカルシウム化合物と、酸を加えたときに発生する気体を考えましょう。", "book": "無機編 第5講"}, {"id": "q-inorg-051", "lecture": "inorg-06", "unit": "アルカリ金属・2族", "type": "choice", "q": "アンモニアソーダ法（ソルベー法）において、炭酸水素ナトリウム（NaHCO3）が沈殿として得られる理由として最も適当なものはどれか。", "choices": ["生成する4つの塩のうち、炭酸水素ナトリウムが冷水に対して最も溶解度が小さいため。", "反応系に過剰の塩化ナトリウムを加えることで、共通イオン効果により沈殿が促進されるため。", "アンモニアを吹き込むことで溶液が酸性になり、炭酸水素ナトリウムの溶解度が急低下するため。", "反応温度を100度以上に保つことで、炭酸水素ナトリウムが水に溶けなくなるため。"], "answer": 0, "hint": "この製法では、複数のイオンが混在する中で特定の物質だけを効率よく取り出す工夫がなされています。", "book": "無機編 第6講"}, {"id": "q-inorg-052", "lecture": "inorg-06", "unit": "アルカリ金属・2族", "type": "choice", "q": "炭酸ナトリウム（Na2CO3）と炭酸水素ナトリウム（NaHCO3）の性質の比較として正しいものはどれか。", "choices": ["同じモル濃度の水溶液を比較すると、炭酸ナトリウム水溶液の方が強い塩基性を示す。", "炭酸ナトリウムの固体は加熱すると容易に分解して二酸化炭素を発生させるが、炭酸水素ナトリウムは熱に安定である。", "炭酸水素ナトリウムの方が炭酸ナトリウムよりも水に対する溶解度が大きく、潮解性を持つ。", "フェノールフタレイン溶液を加えると、炭酸水素ナトリウム水溶液のみが濃い赤色に呈色する。"], "answer": 0, "hint": "炭酸イオンと炭酸水素イオンの加水分解の程度の違いや、熱分解のしやすさを思い出してください。", "book": "無機編 第6講"}, {"id": "q-inorg-053", "lecture": "inorg-06", "unit": "アルカリ金属・2族", "type": "choice", "q": "カルシウムの化合物に関する記述として、最も適当なものはどれか。", "choices": ["セッコウ（CaSO4・2H2O）を加熱すると、一部の結晶水を失って焼きセッコウ（CaSO4・0.5H2O）になる。", "生石灰（CaO）に水を加えると、激しく吸熱しながら消石灰（Ca(OH)2）に変化する。", "石灰石（CaCO3）に希硫酸を加えると、二酸化炭素を発生し続けながら完全に溶解する。", "塩化カルシウム（CaCl2）は中性の乾燥剤であり、アンモニアガスの乾燥に最適である。"], "answer": 0, "hint": "硫酸カルシウムの結晶水の変化や、生石灰と水の反応熱、塩化カルシウムの化学的性質を整理しましょう。", "book": "無機編 第6講"}, {"id": "q-inorg-054", "lecture": "inorg-07", "unit": "鉄の製錬", "type": "choice", "q": "溶鉱炉（高炉）を用いた鉄の製錬において、副原料として加えられる石灰石（CaCO3）の役割として最も適当なものはどれか。", "choices": ["鉄鉱石に含まれる二酸化ケイ素（SiO2）などの不純物を、スラグ（CaSiO3）として分離・除去する。", "一酸化炭素（CO）を発生させるための炭素源となり、鉄鉱石の還元反応を直接促進する。", "鉄鉱石の融点を大幅に下げる助剤として働き、低温での溶融を可能にする。", "生成した銑鉄の中に含まれる炭素分を燃焼させ、鋼（こう）へと精錬する役割を担う。"], "answer": 0, "hint": "石灰石が熱分解して生じる酸化カルシウム（CaO）が、酸性酸化物である不純物とどのように反応するかを考えましょう。", "book": "無機編 第7講"}, {"id": "q-inorg-055", "lecture": "inorg-07", "unit": "鉄イオンの検出", "type": "choice", "q": "鉄(II)イオン（Fe2+）と鉄(III)イオン（Fe3+）の性質および検出に関する記述として、正しいものはどれか。", "choices": ["Fe2+を含む水溶液にヘキサシアニド鉄(III)酸カリウム水溶液を加えると、濃青色の沈殿が生じる。", "Fe3+を含む水溶液にチオシアン酸カリウム水溶液を加えると、淡緑色の沈殿が生じる。", "Fe2+を含む水溶液にアンモニア水を過剰に加えると、一度生じた沈殿が溶けて無色の溶液になる。", "Fe3+を含む水溶液にヘキサシアニド鉄(III)酸カリウム水溶液を加えると、濃青色の沈殿が生じる。"], "answer": 0, "hint": "試薬の名称に含まれる鉄の酸化数（IIかIIIか）と、反応させるイオンの酸化数の組み合わせに注目しましょう。", "book": "無機編 第7講"}, {"id": "q-inorg-056", "lecture": "inorg-07", "unit": "クロム酸イオンの平衡", "type": "choice", "q": "クロムのオキソ酸イオンを含む水溶液の平衡（2CrO4^2- + 2H+ <=> Cr2O7^2- + H2O）に関する記述として、最も適当なものはどれか。", "choices": ["黄色のクロム酸カリウム水溶液に希硫酸を加えると、溶液の色は赤橙色に変化する。", "赤橙色の二クロム酸カリウム水溶液に水酸化ナトリウム水溶液を加えると、二クロム酸イオンの濃度が増加する。", "酸性条件下では、二クロム酸イオンよりもクロム酸イオンの方が安定して存在する。", "クロム酸イオン（CrO4^2-）中のクロムの酸化数は+6であり、二クロム酸イオン（Cr2O7^2-）中のクロムの酸化数は+7である。"], "answer": 0, "hint": "ルシャトリエの原理に基づいて、水素イオン（H+）を加えたときに平衡がどちらに移動するかを考えましょう。", "book": "無機編 第7講"}]}, {"field": "organic", "fieldLabel": "有機", "lectures": [{"id": "org-01", "title": "構造決定", "book": "有機編 第1講"}, {"id": "org-02", "title": "炭素骨格の書き方と立体構造", "book": "有機編 第2講"}, {"id": "org-03", "title": "構造異性体", "book": "有機編 第3講"}, {"id": "org-04", "title": "立体異性体", "book": "有機編 第4講"}, {"id": "org-05", "title": "飽和炭化水素（アルカンとシクロアルカン）", "book": "有機編 第5講"}, {"id": "org-06", "title": "不飽和炭化水素（アルケンとアルキン）", "book": "有機編 第6講"}, {"id": "org-07", "title": "アルコールとエーテル", "book": "有機編 第7講"}, {"id": "org-08", "title": "アルデヒドとケトン", "book": "有機編 第8講"}, {"id": "org-09", "title": "カルボン酸とエステル", "book": "有機編 第9講"}, {"id": "org-10", "title": "芳香族炭化水素（ベンゼンの反応）", "book": "有機編 第10講"}, {"id": "org-11", "title": "フェノール類", "book": "有機編 第11講"}, {"id": "org-12", "title": "芳香族アミン", "book": "有機編 第12講"}, {"id": "org-13", "title": "糖類（単糖類と二糖類）", "book": "有機編 第13講"}, {"id": "org-14", "title": "多糖類", "book": "有機編 第14講"}, {"id": "org-15", "title": "アミノ酸", "book": "有機編 第15講"}, {"id": "org-16", "title": "ペプチドとタンパク質", "book": "有機編 第16講"}, {"id": "org-17", "title": "油脂とせっけん", "book": "有機編 第17講"}, {"id": "org-18", "title": "合成高分子", "book": "有機編 第18講"}, {"id": "org-19", "title": "イオン交換樹脂", "book": "有機編 第19講"}, {"id": "org-20", "title": "ナイロンとゴム", "book": "有機編 第20講"}], "cards": [{"id": "card-org-01", "lecture": "org-01", "name": "構造決定の5ステップ", "kind": "概念", "points": [{"label": "手順1,2", "text": "元素分析で組成式を求め、分子量から分子式(組成式)nを決定する", "blind": true, "masks": ["元素分析で組成式を求め", "分子式(組成式)n"]}, {"label": "手順3", "text": "不飽和度Duを (2x+2-y)/2 で計算し、二重結合や環の総数を見積もる", "blind": true, "masks": ["不飽和度Du", "(2x+2-y)/2"]}, {"label": "手順4,5", "text": "骨格を先に決めて異性体を列挙し、検出反応の結果から構造を絞り込む", "blind": true, "masks": ["骨格を先に決めて", "検出反応の結果から構造を絞り込む"]}], "note": "まとめノート有機編 第1講"}, {"id": "card-org-02", "lecture": "org-02", "name": "炭素の立体構造", "kind": "概念", "points": [{"label": "正四面体形", "text": "炭素が4個の原子と単結合している場合。結合角は約109.5度", "blind": true, "masks": ["約109.5度"]}, {"label": "平面三角形", "text": "炭素が二重結合1個を含む3個の原子と結合している場合。エチレンなど", "blind": true, "masks": ["エチレン"]}, {"label": "直線形", "text": "炭素が三重結合1個を含む2個の原子と結合している場合。アセチレンなど", "blind": true, "masks": ["アセチレン"]}, {"label": "結合の長さ", "text": "単結合 > ベンゼンの結合 > 二重結合 > 三重結合 の順に短い", "blind": true, "masks": ["単結合 > ベンゼンの結合 > 二重結合 > 三重結合"]}], "note": "まとめノート有機編 第2講"}, {"id": "card-org-03", "lecture": "org-03", "name": "構造異性体", "kind": "概念", "points": [{"label": "定義", "text": "分子式が同じで、原子のつながり方（並び方）そのものが異なる物質どうしのこと。", "blind": true, "masks": ["つながり方（並び方）そのものが異なる"]}, {"label": "数え上げ", "text": "長い主鎖から順に短くしていき、外れた炭素を枝として各位置に付ける。末端への枝付けは主鎖が伸びるだけで新しい異性体にならない。", "blind": true, "masks": ["新しい異性体にならない"]}, {"label": "重複の確認", "text": "同じ骨格か迷った場合は正式な名称を付けてみる。主鎖を選び直し、位置番号が最小になるように命名して一致すれば同一物質である。", "blind": true, "masks": ["位置番号が最小になるように命名して一致すれば同一物質である"]}, {"label": "原子価の確認", "text": "炭素の手は必ず4本である。書き上げた構造について、中心の炭素から手が5本出るような存在しない構造になっていないか確認する。", "blind": true, "masks": ["必ず4本"]}], "note": "まとめノート有機編 第3講"}, {"id": "card-org-04", "lecture": "org-04", "name": "立体異性体", "kind": "概念", "points": [{"label": "幾何異性体", "text": "二重結合が回転できないために生じる。二重結合の両端の各炭素に、それぞれ異なる2つの基が付いている場合に存在する（シス・トランス異性体）。", "blind": true, "masks": ["それぞれ異なる2つの基が付いている場合"]}, {"label": "光学異性体", "text": "4つの異なる基が結合した不斉炭素原子をもつ分子で生じる。鏡像どうしが重ならない関係にあり、旋光性以外の物理的・化学的性質はほぼ同じである。", "blind": true, "masks": ["4つの異なる基が結合した不斉炭素原子"]}, {"label": "マレイン酸とフマル酸", "text": "シス型のマレイン酸は分子内水素結合を作るため融点が低く、加熱で無水物を生じやすい。トランス型のフマル酸は分子間水素結合を作るため融点が高い。", "blind": true, "masks": ["分子内水素結合", "分子間水素結合"]}], "note": "まとめノート有機編 第4講"}, {"id": "card-org-05", "lecture": "org-05", "name": "アルカン", "kind": "物質", "points": [{"label": "性質", "text": "無極性分子で水に不溶。密度は水より小さく、水に浮くものが多い。", "blind": true, "masks": ["水に不溶", "水より小さく"]}, {"label": "状態", "text": "炭素数1〜4は常温で気体、C5〜C17程度は液体、それ以上は固体である。", "blind": true, "masks": ["炭素数1〜4は常温で気体、C5〜C17程度は液体、それ以上は固体である"]}, {"label": "反応", "text": "化学的に安定で常温では反応しにくいが、光（紫外線）を当てるとハロゲンと置換反応を起こす。", "blind": true, "masks": ["光（紫外線）", "置換反応"]}, {"label": "構造", "text": "鎖式飽和炭化水素であり、一般式 CnH2n+2 で表される。", "blind": true, "masks": ["CnH2n+2"]}], "note": "まとめノート有機編 第5講"}, {"id": "card-org-06", "lecture": "org-06", "name": "アセチレン", "kind": "物質", "points": [{"label": "製法", "text": "炭化カルシウム CaC2 に水を作用させて発生させる。水上置換で捕集する。", "blind": true, "masks": ["炭化カルシウム CaC2", "水上置換"]}, {"label": "水の付加", "text": "硫酸水銀(II)を触媒として水を付加させると、不安定なビニルアルコールを経てアセトアルデヒドになる。", "blind": true, "masks": ["硫酸水銀(II)を触媒として", "アセトアルデヒド"]}, {"label": "重合", "text": "鉄触媒を用いて高温で加熱すると、3分子が重合してベンゼン C6H6 になる。", "blind": true, "masks": ["ベンゼン C6H6"]}, {"label": "検出", "text": "アンモニア性硝酸銀水溶液を加えると、銀アセチリドの白色沈殿を生じる。", "blind": true, "masks": ["アンモニア性硝酸銀水溶液", "銀アセチリドの白色沈殿"]}], "note": "まとめノート有機編 第6講"}, {"id": "card-org-07", "lecture": "org-07", "name": "エタノール", "kind": "物質", "points": [{"label": "性質", "text": "ヒドロキシ基 -OH をもつため分子間で水素結合し、沸点(78度)は異性体のジメチルエーテル(-23度)より高い。", "blind": true, "masks": ["水素結合し", "78度"]}, {"label": "検出・反応", "text": "金属ナトリウムを加えると、水素 H2 を発生してナトリウムエトキシド C2H5ONa になる。", "blind": true, "masks": ["水素 H2 を発生して", "ナトリウムエトキシド C2H5ONa"]}, {"label": "脱水反応", "text": "濃硫酸を用い、130-140度で分子間脱水(ジエチルエーテル)、160-170度で分子内脱水(エチレン)が起こる。", "blind": true, "masks": ["130-140度で分子間脱水(ジエチルエーテル)、160-170度で分子内脱水(エチレン)"]}, {"label": "酸化", "text": "第1級アルコールであり、酸化されるとアセトアルデヒドを経て、最終的に酢酸(カルボン酸)になる。", "blind": true, "masks": ["アセトアルデヒドを経て、最終的に酢酸(カルボン酸)になる"]}], "note": "まとめノート有機編 第7講"}, {"id": "card-org-08", "lecture": "org-08", "name": "アセトアルデヒド", "kind": "物質", "points": [{"label": "製法", "text": "アセチレン HC≡CH への水の付加により生じる不安定なビニルアルコール CH2=CH-OH が異性化して生成する。", "blind": true, "masks": ["ビニルアルコール CH2=CH-OH"]}, {"label": "検出・反応", "text": "還元性をもち、銀鏡反応(銀の析出)やフェーリング反応(Cu2O の赤色沈殿)に陽性を示す。", "blind": true, "masks": ["銀鏡反応(銀の析出)", "フェーリング反応(Cu2O の赤色沈殿)"]}, {"label": "ヨードホルム反応", "text": "CH3-CO-H の構造をもつため、ヨウ素と水酸化ナトリウムを加えて温めると CHI3 の黄色沈殿を生じる。", "blind": true, "masks": ["CHI3 の黄色沈殿"]}], "note": "まとめノート有機編 第8講"}, {"id": "card-org-09", "lecture": "org-09", "name": "ギ酸", "kind": "物質", "points": [{"label": "検出", "text": "カルボン酸であるため、NaHCO3 水溶液に加えると CO2 を発生して溶ける。", "blind": true, "masks": ["CO2 を発生して溶ける"]}, {"label": "還元性", "text": "分子内にアルデヒド基とみなせる構造をもち、銀鏡反応やフェーリング液の還元を示す。", "blind": true, "masks": ["アルデヒド基とみなせる構造"]}, {"label": "構造異性体", "text": "分子式 C2H4O2 において、エステルであるギ酸メチル HCOOCH3 は、酢酸 CH3COOH と構造異性体の関係にある。", "blind": true, "masks": ["ギ酸メチル HCOOCH3"]}], "note": "まとめノート有機編 第9講"}, {"id": "card-org-10", "lecture": "org-10", "name": "ベンゼン", "kind": "物質", "points": [{"label": "構造", "text": "π電子が非局在化した正六角形構造。すべての炭素ー炭素結合は、単結合と二重結合の中間の長さで等しい。", "blind": true, "masks": ["非局在化", "中間の長さで等しい"]}, {"label": "置換反応", "text": "鉄触媒で塩素を反応させるとクロロベンゼン、混酸でニトロベンゼン、濃硫酸でベンゼンスルホン酸が生じる。", "blind": true, "masks": ["クロロベンゼン", "ニトロベンゼン", "ベンゼンスルホン酸"]}, {"label": "付加反応", "text": "Ni触媒・高温高圧で水素が付加してシクロヘキサン、光照射で塩素が付加してヘキサクロロシクロヘキサンになる。", "blind": true, "masks": ["シクロヘキサン", "ヘキサクロロシクロヘキサン"]}], "note": "まとめノート有機編 第10講"}, {"id": "card-org-11", "lecture": "org-11", "name": "フェノール", "kind": "物質", "points": [{"label": "性質", "text": "弱い酸性を示し、NaOH水溶液には溶けるが、炭酸より弱い酸のためNaHCO3水溶液には溶けない。", "blind": true, "masks": ["NaHCO3水溶液には溶けない"]}, {"label": "検出・反応", "text": "FeCl3水溶液で紫色に呈色し、臭素水と反応すると2,4,6-トリブロモフェノールの白色沈殿を生じる。", "blind": true, "masks": ["紫色に呈色", "2,4,6-トリブロモフェノールの白色沈殿"]}, {"label": "製法", "text": "ベンゼンとプロペンからクメンをつくり、酸化・分解してフェノールとアセトンを得るクメン法が工業的製法の主流である。", "blind": true, "masks": ["クメン法"]}], "note": "まとめノート有機編 第11講"}, {"id": "card-org-12", "lecture": "org-12", "name": "アニリン", "kind": "物質", "points": [{"label": "性質", "text": "弱塩基性を示す油状の液体。塩酸にはアニリン塩酸塩になって溶けるが、塩基性はアンモニアよりも弱い。", "blind": true, "masks": ["アンモニアよりも弱い"]}, {"label": "検出・反応", "text": "さらし粉水溶液で赤紫色に呈色し、二クロム酸カリウム水溶液で酸化すると黒色のアニリンブラックが生じる。", "blind": true, "masks": ["赤紫色に呈色", "アニリンブラック"]}, {"label": "合成・変換", "text": "無水酢酸によりアセチル化されてアセトアニリドになる。また、氷冷下でジアゾ化すると塩化ベンゼンジアゾニウムになる。", "blind": true, "masks": ["アセトアニリド", "塩化ベンゼンジアゾニウム"]}], "note": "まとめノート有機編 第12講"}, {"id": "card-org-13", "lecture": "org-13", "name": "グルコース", "kind": "物質", "points": [{"label": "性質", "text": "水溶液中では鎖状、α型（環状）、β型（環状）が平衡状態にある。α型は1位の-OHが下向き、β型は上向きである。", "blind": true, "masks": ["α型は1位の-OHが下向き、β型は上向きである"]}, {"label": "検出・反応", "text": "ヘミアセタール構造をもち、開環してアルデヒド基を生じるため還元性を示す。フェーリング液を加熱すると赤色のCu2Oが沈殿する。", "blind": true, "masks": ["ヘミアセタール構造", "Cu2O"]}, {"label": "構造", "text": "分子式はC6H12O6（分子量180）で、フルクトースやガラクトースと構造異性体である。環状構造は六員環をとる。", "blind": true, "masks": ["C6H12O6（分子量180）", "六員環"]}], "note": "まとめノート有機編 第13講"}, {"id": "card-org-14", "lecture": "org-14", "name": "デンプン", "kind": "物質", "points": [{"label": "成分", "text": "α-1,4結合のみでらせん状のアミロースと、α-1,6結合の枝分かれをもつアミロペクチンからなる。", "blind": true, "masks": ["アミロース", "アミロペクチン"]}, {"label": "検出・反応", "text": "ヨウ素デンプン反応で青紫色を示す。加熱によりヨウ素がらせんから出て色が消えるが、冷やすと再び呈色する。", "blind": true, "masks": ["青紫色"]}, {"label": "性質", "text": "多数の単糖が結合した多糖であり、還元性は事実上示さない。希硫酸で完全に加水分解するとグルコースになる。", "blind": true, "masks": ["還元性は事実上示さない", "グルコース"]}], "note": "まとめノート有機編 第14講"}, {"id": "card-org-15", "lecture": "org-15", "name": "α-アミノ酸", "kind": "物質", "points": [{"label": "構造", "text": "1つの分子内にアミノ基-NH2とカルボキシ基-COOHが同じ炭素(α炭素)に結合している。", "blind": true, "masks": ["同じ炭素(α炭素)に結合している"]}, {"label": "光学異性体", "text": "側鎖RがHであるグリシンを除き、α炭素は不斉炭素原子であり、天然では主にL型が存在する。", "blind": true, "masks": ["グリシンを除き", "L型"]}, {"label": "物理的性質", "text": "双性イオンとして存在し、イオン結晶のように融点が高く、水に溶けやすく有機溶媒に溶けにくい。", "blind": true, "masks": ["双性イオンとして存在し"]}], "note": "まとめノート有機編 第15講"}, {"id": "card-org-16", "lecture": "org-16", "name": "ペプチド結合", "kind": "概念", "points": [{"label": "特徴", "text": "-COOHと-NH2の間で水H2Oが1分子取れてできる-CO-NH-の結合。", "blind": true, "masks": ["-CO-NH-"]}, {"label": "分子量計算", "text": "ペプチドの分子量は(アミノ酸の分子量の和)-(18 × ペプチド結合の数)で求められる。", "blind": true, "masks": ["(アミノ酸の分子量の和)-(18 × ペプチド結合の数)"]}, {"label": "検出・反応", "text": "ペプチド結合を2つ以上もつトリペプチド以上は、ビウレット反応で赤紫色を呈する。", "blind": true, "masks": ["トリペプチド以上", "ビウレット反応で赤紫色を呈する"]}], "note": "まとめノート有機編 第16講"}, {"id": "card-org-17", "lecture": "org-17", "name": "油脂", "kind": "物質", "points": [{"label": "構造", "text": "3価アルコールのグリセリン1分子と、高級脂肪酸3分子がエステル結合したトリエステル。", "blind": true, "masks": ["グリセリン1分子", "高級脂肪酸3分子", "トリエステル"]}, {"label": "不斉炭素", "text": "グリセリン部分の中央の炭素に結合する脂肪酸のうち、上端(R1)と下端(R3)が異なる場合にのみ不斉炭素原子となる。", "blind": true, "masks": ["上端(R1)と下端(R3)が異なる場合にのみ"]}, {"label": "反応", "text": "水酸化ナトリウム水溶液と加熱すると、グリセリンと高級脂肪酸のナトリウム塩（せっけん）が得られる（けん化）。", "blind": true, "masks": ["高級脂肪酸のナトリウム塩（せっけん）"]}], "note": "まとめノート有機編 第17講"}, {"id": "card-org-18", "lecture": "org-18", "name": "ポリエチレンテレフタラート", "kind": "物質", "points": [{"label": "製法", "text": "テレフタル酸とエチレングリコールが脱水縮合（縮合重合）して生成するポリエステル。", "blind": true, "masks": ["テレフタル酸", "エチレングリコール"]}, {"label": "性質", "text": "繰り返し単位の式量は192。1本の直鎖状分子(重合度n)が生成する際、(2n-1)分子の水が取れる。", "blind": true, "masks": ["192", "(2n-1)分子の水"]}, {"label": "用途", "text": "飲料用のペットボトルや、衣類用のポリエステル繊維の材料として広く利用される。", "blind": true, "masks": ["ペットボトル", "ポリエステル繊維"]}], "note": "まとめノート有機編 第18講"}, {"id": "card-org-19", "lecture": "org-19", "name": "陽イオン交換樹脂", "kind": "物質", "points": [{"label": "製法", "text": "スチレンとp-ジビニルベンゼンを共重合させ、濃硫酸でスルホン化して-SO3Hを導入する。", "blind": true, "masks": ["p-ジビニルベンゼン", "-SO3H"]}, {"label": "構造", "text": "ビニル基を2つ持つp-ジビニルベンゼンにより、鎖間が橋かけされた三次元の網目状構造を持つ。", "blind": true, "masks": ["三次元の網目状構造"]}, {"label": "交換の原理", "text": "樹脂側のH+と水溶液中の陽イオンが電荷の総量が等しくなるように入れ替わる。2価のCa2+は2つのH+と交換する。", "blind": true, "masks": ["電荷の総量が等しくなるように", "2つのH+と交換する"]}, {"label": "再生", "text": "使用後の樹脂に塩酸などの強酸を流すと、逆向きの交換が起こりR-SO3Hの形に戻る。", "blind": true, "masks": ["塩酸などの強酸"]}], "note": "まとめノート有機編 第19講"}, {"id": "card-org-20", "lecture": "org-20", "name": "ナイロン6,6", "kind": "物質", "points": [{"label": "製法", "text": "アジピン酸とヘキサメチレンジアミンを縮合重合(脱水縮合)させて合成する。", "blind": true, "masks": ["アジピン酸", "ヘキサメチレンジアミン"]}, {"label": "構造", "text": "アミド結合-CO-NH-を繰り返し単位に持ち、鎖間で水素結合ができるため強度が大きい。", "blind": true, "masks": ["アミド結合-CO-NH-", "水素結合"]}, {"label": "性質", "text": "繰り返し単位の式量は226。名前の「6,6」は原料となるアジピン酸とヘキサメチレンジアミンの炭素数がともに6であることに由来する。", "blind": true, "masks": ["226", "ともに6"]}], "note": "まとめノート有機編 第20講"}], "questions": [{"id": "q-org-001", "lecture": "org-01", "unit": "元素分析（燃焼法）の装置と計算", "type": "choice", "q": "元素分析装置において、燃焼管の後に続く吸収管の順序と、各管で吸収される物質の組み合わせとして正しいものはどれか。", "choices": ["先にソーダ石灰管でCO2を吸収し、次に塩化カルシウム管でH2Oを吸収する", "先にソーダ石灰管でH2Oを吸収し、次に塩化カルシウム管でCO2を吸収する", "先に塩化カルシウム管でH2Oを吸収し、次にソーダ石灰管でCO2を吸収する", "先に塩化カルシウム管でCO2を吸収し、次にソーダ石灰管でH2Oを吸収する"], "answer": 2, "hint": "ソーダ石灰はCO2だけでなくH2Oも吸収してしまう性質があります。", "book": "有機編 第1講"}, {"id": "q-org-002", "lecture": "org-01", "unit": "不飽和度 Du ― 部品の数を数える", "type": "choice", "q": "分子式 C4H8O2 で表される化合物の不飽和度(Du)として正しい数値はどれか。", "choices": ["2", "0", "3", "1"], "answer": 3, "hint": "不飽和度の計算式 (2x + 2 - y) / 2 に当てはめます。酸素の数は無視します。", "book": "有機編 第1講"}, {"id": "q-org-003", "lecture": "org-01", "unit": "検出反応の早見表と酸性の序列", "type": "choice", "q": "ある有機化合物に炭酸水素ナトリウム(NaHCO3)水溶液を加えたところ、二酸化炭素が発生した。この化合物がもつ官能基はどれか。", "choices": ["アルコール性ヒドロキシ基", "エステル結合", "フェノール性ヒドロキシ基", "カルボキシ基"], "answer": 3, "hint": "炭酸よりも強い酸である官能基を探します。", "book": "有機編 第1講"}, {"id": "q-org-004", "lecture": "org-02", "unit": "炭素の結合の数と立体構造（正四面体・平面三角形・直線）", "type": "choice", "q": "ホルムアルデヒド HCHO の炭素原子のまわりにおける、結合している原子の数と立体構造の組み合わせとして正しいものはどれか。", "choices": ["3個の原子と結合し、平面三角形", "4個の原子と結合し、正四面体形", "3個の原子と結合し、正四面体形", "2個の原子と結合し、直線形"], "answer": 0, "hint": "二重結合で結ばれた酸素も「相手1個」として数えます。", "book": "有機編 第2講"}, {"id": "q-org-005", "lecture": "org-02", "unit": "ベンゼン環と「同一平面上」の判定", "type": "choice", "q": "トルエン(ベンゼン環にメチル基-CH3が1つついた化合物)の原子の配置について、正しい記述はどれか。", "choices": ["すべての炭素原子は同一平面上にあるが、すべての水素原子が同一平面上にあるわけではない", "すべての水素原子は同一平面上にあるが、すべての炭素原子が同一平面上にあるわけではない", "炭素原子も水素原子も、ベンゼン環以外の部分は同一平面上にはない", "すべての炭素原子とすべての水素原子が、常に同一平面上にある"], "answer": 0, "hint": "メチル基の炭素は環に直結していますが、その先の水素は正四面体方向に広がります。", "book": "有機編 第2講"}, {"id": "q-org-006", "lecture": "org-02", "unit": "炭素骨格の見分け方（同じ骨格かどうか）", "type": "choice", "q": "炭素数5の鎖状炭化水素 C5H12 について、考えられる異なる炭素骨格は全部で何種類か。", "choices": ["5種類", "4種類", "3種類", "2種類"], "answer": 2, "hint": "主鎖が5、4、3の場合をそれぞれ検討し、重複がないか確認します。", "book": "有機編 第2講"}, {"id": "q-org-007", "lecture": "org-03", "unit": "炭化水素の構造異性体 ― アルカンと CnH2n 型", "type": "choice", "q": "分子式 C5H12 で表されるアルカンの構造異性体は、全部で何種類存在するか。", "choices": ["3種類", "5種類", "4種類", "2種類"], "answer": 0, "hint": "主鎖の炭素数を5、4、3と変えながら枝の付け方を数えます。", "book": "有機編 第3講"}, {"id": "q-org-008", "lecture": "org-03", "unit": "酸素を含む化合物の構造異性体 ― アルコールとエーテル", "type": "choice", "q": "分子式 C4H10O で表される構造異性体のうち、エーテルに分類されるものは全部で何種類あるか。", "choices": ["7種類", "4種類", "2種類", "3種類"], "answer": 3, "hint": "酸素の両側への炭素の配分が「1個と3個（2通り）」か「2個と2個（1通り）」かを考えます。", "book": "有機編 第3講"}, {"id": "q-org-009", "lecture": "org-03", "unit": "構造異性体とは何か ― 数え上げの原則", "type": "choice", "q": "構造異性体の重複を確認する際の説明として、本文の内容に照らして正しいものはどれか。", "choices": ["主鎖5個の2位に枝がある構造と4位に枝がある構造は、反対から数え直せば同じものである。", "2-メチルペンタンと4-メチルペンタンは、異なる構造異性体である。", "ペンタンの末端の炭素にメチル基を1個付けると、2-メチルブタンと同じ構造になる。", "主鎖3個のプロパンの中央の炭素にメチル基を2個付けると、主鎖が4個に伸びる。"], "answer": 0, "hint": "名前を付けるときは、枝の位置番号が小さくなる向きに数えるのがルールです。", "book": "有機編 第3講"}, {"id": "q-org-010", "lecture": "org-04", "unit": "幾何異性体 ― 生じる条件とシス・トランス", "type": "choice", "q": "次の化合物のうち、幾何異性体（シス・トランス異性体）が存在するものはどれか。", "choices": ["ブタ-1-エン", "ペンタ-2-エン", "2-メチルプロペン", "2-メチルブタ-2-エン"], "answer": 1, "hint": "二重結合の両端の炭素に、それぞれ異なる2つの基が付いているかを確認します。", "book": "有機編 第4講"}, {"id": "q-org-011", "lecture": "org-04", "unit": "光学異性体と不斉炭素原子", "type": "choice", "q": "次の化合物のうち、不斉炭素原子をもち、光学異性体が存在するものはどれか。", "choices": ["プロパン-2-オール", "プロパン-1,2,3-トリオール", "ブタン-2-オール", "ペンタン-3-オール"], "answer": 2, "hint": "炭素に結合している4つの基がすべて異なっている炭素原子を探します。", "book": "有機編 第4講"}, {"id": "q-org-012", "lecture": "org-04", "unit": "極性と物性 ― マレイン酸とフマル酸", "type": "choice", "q": "マレイン酸とフマル酸の性質の比較について、正しい記述はどれか。", "choices": ["マレイン酸は分子内で水素結合を作るため、フマル酸よりも水に溶けにくい。", "フマル酸は分子間での水素結合のネットワークを作るため、マレイン酸よりも融点が高い。", "マレイン酸はトランス型で、フマル酸よりも融点が高い。", "フマル酸は加熱すると容易に脱水し、環状の無水物を生じる。"], "answer": 1, "hint": "フマル酸はトランス型で、分子間で水素結合を作るため結晶が強固になります。", "book": "有機編 第4講"}, {"id": "q-org-013", "lecture": "org-05", "unit": "アルカンの構造と命名法", "type": "choice", "q": "構造式 CH3-C(CH3)2-CH2-CH3 で表されるアルカンの名称として正しいものはどれか。", "choices": ["2-エチル-2-メチルプロパン", "3,3-ジメチルブタン", "2,2-ジメチルプロパン", "2,2-ジメチルブタン"], "answer": 3, "hint": "最も長い炭素鎖（主鎖）を基準とし、側鎖の位置番号が小さくなる向きから数えます。", "book": "有機編 第5講"}, {"id": "q-org-014", "lecture": "org-05", "unit": "アルカンの性質と反応 ― 置換反応・熱分解・燃焼", "type": "choice", "q": "メタン 0.50 mol の水素原子のうち2つを塩素で置換してジクロロメタン CH2Cl2 を得るとき、消費される塩素 Cl2 は何 mol か。", "choices": ["2.0 mol", "1.5 mol", "0.50 mol", "1.0 mol"], "answer": 3, "hint": "水素1つを置換するごとに、塩素分子を1つ消費して塩化水素が1つ生じます。", "book": "有機編 第5講"}, {"id": "q-org-015", "lecture": "org-05", "unit": "シクロアルカン", "type": "choice", "q": "分子式 C4H8 で表される炭化水素のうち、環状構造をもち、側鎖としてメチル基を1つもつ化合物の名称はどれか。", "choices": ["1-ブテン", "メチルシクロブタン", "メチルシクロプロパン", "シクロブタン"], "answer": 2, "hint": "全体の炭素数が4になるように、環の炭素数と側鎖の炭素数を合計します。", "book": "有機編 第5講"}, {"id": "q-org-016", "lecture": "org-06", "unit": "アルケンの構造と付加反応・マルコフニコフ則", "type": "choice", "q": "プロペン CH2=CH-CH3 に酸触媒下で水を付加させたとき、マルコフニコフ則に従って得られる主生成物の名称はどれか。", "choices": ["プロパナール", "2-プロパノール", "1-プロパノール", "プロパノン"], "answer": 1, "hint": "Hは水素を多くもつ二重結合炭素に、OHは水素の少ない方の炭素に付きます。", "book": "有機編 第6講"}, {"id": "q-org-017", "lecture": "org-06", "unit": "付加反応を使った構造決定", "type": "choice", "q": "ある直鎖アルケンをオゾン分解したところ、アセトアルデヒド CH3CHO だけが得られた。元のアルケンの名称はどれか。", "choices": ["2-メチル-2-ブテン", "1-ブテン", "2-ブテン", "2-ペンテン"], "answer": 2, "hint": "生成物のカルボニル炭素（C=O）どうしを二重結合でつなぎ直すと元の構造がわかります。", "book": "有機編 第6講"}, {"id": "q-org-018", "lecture": "org-06", "unit": "ジエンとアルキン ― アセチレンの製法と反応", "type": "choice", "q": "炭化カルシウム CaC2 12.8 g（モル質量 64 g/mol）に十分な量の水を加えたとき、発生するアセチレンは標準状態で何 L か。", "choices": ["2.24 L", "5.60 L", "8.96 L", "4.48 L"], "answer": 3, "hint": "反応式の係数比から、CaC2 1 mol あたり 1 mol のアセチレンが発生することを利用します。", "book": "有機編 第6講"}, {"id": "q-org-019", "lecture": "org-07", "unit": "① 金属ナトリウムとの反応：−OH の検出", "type": "choice", "q": "エタノール 1.15 g に十分な量の金属ナトリウムを加えて完全に反応させた。発生する水素は標準状態で何 mL か。ただし原子量は H=1.0、C=12、O=16 とし、エタノールのモル質量は 46 g/mol とする。", "choices": ["560 mL", "280 mL", "140 mL", "1120 mL"], "answer": 1, "hint": "反応式 2C2H5OH + 2Na -> 2C2H5ONa + H2 より、エタノールと発生する水素の物質量比は 2 : 1 です。", "book": "有機編 第7講"}, {"id": "q-org-020", "lecture": "org-07", "unit": "② 脱水反応：温度で生成物が変わる（濃硫酸）", "type": "choice", "q": "エタノールに濃硫酸を加え、130〜140℃ で加熱した際に生じる有機化合物の名称として正しいものはどれか。", "choices": ["アセトアルデヒド", "ジメチルエーテル", "エチレン", "ジエチルエーテル"], "answer": 3, "hint": "低温（130〜140℃）では、2分子のエタノールから水1分子が取れる分子間脱水が起こります。", "book": "有機編 第7講"}, {"id": "q-org-021", "lecture": "org-07", "unit": "③ 酸化：第1級・第2級・第3級で行き先が違う", "type": "choice", "q": "1-プロパノールを二クロム酸カリウムなどの酸化剤で十分に酸化したときに得られる最終的な有機化合物はどれか。", "choices": ["プロパナール", "プロパン酸", "アセトン", "プロペン"], "answer": 1, "hint": "1-プロパノールは第1級アルコールなので、アルデヒドを経てカルボン酸まで酸化が進みます。", "book": "有機編 第7講"}, {"id": "q-org-022", "lecture": "org-08", "unit": "エノールとケト型への異性化：アセトアルデヒドの製法", "type": "choice", "q": "アセチレン 2.6 g に水を付加させて、すべてアセトアルデヒドに変化させたとき、得られるアセトアルデヒドは何 g か。ただし原子量は H=1.0、C=12、O=16 とする。", "choices": ["2.6 g", "3.2 g", "4.4 g", "8.8 g"], "answer": 2, "hint": "アセチレン(分子量26)1molからアセトアルデヒド(分子量44)1molが生成します。", "book": "有機編 第8講"}, {"id": "q-org-023", "lecture": "org-08", "unit": "② フェーリング反応", "type": "choice", "q": "アセトアルデヒド 0.44 g に十分な量のフェーリング液を加えて加熱したとき、生じる酸化銅(I) Cu2O は何 g か。ただし原子量は H=1.0、C=12、O=16、Cu=64、アセトアルデヒドのモル質量は 44 g/mol とする。", "choices": ["0.64 g", "0.72 g", "1.44 g", "2.88 g"], "answer": 2, "hint": "反応式より、アセトアルデヒド 1 mol に対して酸化銅(I) Cu2O(式量144) が 1 mol 生成します。", "book": "有機編 第8講"}, {"id": "q-org-024", "lecture": "org-08", "unit": "ヨードホルム反応：CH3-CO- の構造を検出する", "type": "choice", "q": "次の化合物のうち、ヨードホルム反応において陰性（黄色沈殿を生じない）を示すものはどれか。", "choices": ["2-プロパノール", "1-プロパノール", "アセトアルデヒド", "エタノール"], "answer": 1, "hint": "CH3-CH(OH)-R または CH3-CO-R の部分構造をもたないものを選びます。", "book": "有機編 第8講"}, {"id": "q-org-025", "lecture": "org-09", "unit": "酸性の強さと炭酸水素ナトリウムとの反応（カルボン酸の検出）", "type": "choice", "q": "次の化合物のうち、炭酸水素ナトリウム水溶液を加えたときに二酸化炭素を発生させるものの組み合わせとして正しいものはどれか。(1)ベンゼンスルホン酸 (2)酢酸 (3)フェノール (4)炭酸", "choices": ["(1)と(2)", "(2)のみ", "(2)と(3)", "(1)と(2)と(4)"], "answer": 0, "hint": "炭酸水素ナトリウムからCO2を発生させるには、炭酸よりも強い酸である必要があります。", "book": "有機編 第9講"}, {"id": "q-org-026", "lecture": "org-09", "unit": "酸無水物の生成：2つのカルボキシ基から水が取れる場合", "type": "choice", "q": "次のカルボン酸のうち、加熱するだけで分子内脱水が起こり、酸無水物を生じるものはどれか。", "choices": ["マレイン酸", "フマル酸", "安息香酸", "テレフタル酸"], "answer": 0, "hint": "2つのカルボキシ基が同じ側にあり、距離が近い必要があります。", "book": "有機編 第9講"}, {"id": "q-org-027", "lecture": "org-09", "unit": "けん化：塩基による加水分解は不可逆に進む", "type": "choice", "q": "酢酸エチル 22.0 g を十分な量の水酸化ナトリウム水溶液を用いて完全にけん化した。このとき得られる酢酸ナトリウムの質量は何 g か。原子量は H=1.0, C=12, O=16, Na=23 とする。", "choices": ["15.0 g", "41.0 g", "20.5 g", "22.0 g"], "answer": 2, "hint": "酢酸エチル(式量88)と酢酸ナトリウム(式量82)は1:1の物質量比で反応・生成します。", "book": "有機編 第9講"}, {"id": "q-org-028", "lecture": "org-10", "unit": "正六角形であることが構造の証拠", "type": "choice", "q": "ベンゼンの構造に関する記述として誤っているものはどれか。", "choices": ["pi電子が特定の炭素間にとどまらず環全体で共有されている。", "結合は単結合と二重結合が交互に並んで固定されている。", "二置換体の構造異性体はオルト・メタ・パラの3種類である。", "すべての炭素ー炭素結合の長さは等しい。"], "answer": 1, "hint": "もし結合が固定されていれば、二置換体は4種類存在するはずです。", "book": "有機編 第10講"}, {"id": "q-org-029", "lecture": "org-10", "unit": "ベンゼンの置換反応と付加反応（ニトロ化・スルホン化・ハロゲン化・アルキル化）", "type": "choice", "q": "ベンゼンと塩素を反応させたとき、条件と生成物の組み合わせとして正しいものはどれか。", "choices": ["光（紫外線）を照射すると、クロロベンゼンが生成する。", "光（紫外線）を照射すると、置換反応が起こりヘキサクロロシクロヘキサンが生成する。", "鉄を触媒として加熱すると、ヘキサクロロシクロヘキサンが生成する。", "鉄を触媒として反応させると、置換反応が起こりクロロベンゼンが生成する。"], "answer": 3, "hint": "触媒を使うと置換反応、光を当てると付加反応が優先します。", "book": "有機編 第10講"}, {"id": "q-org-030", "lecture": "org-10", "unit": "アルキルベンゼンの酸化と二置換体（側鎖の酸化・オルト／メタ／パラ）", "type": "choice", "q": "アルキルベンゼンの側鎖の酸化に関する記述として正しいものはどれか。", "choices": ["トルエンを酸化すると安息香酸が得られる。", "側鎖の炭素に水素原子がなくても、過マンガン酸カリウムで容易に酸化される。", "p-キシレンを酸化すると、分子内脱水しやすいフタル酸が得られる。", "エチルベンゼンを酸化すると、炭素数を保ったままフェニル酢酸が得られる。"], "answer": 0, "hint": "側鎖の長さに関わらず、環に直結した炭素がカルボキシ基になります。", "book": "有機編 第10講"}, {"id": "q-org-031", "lecture": "org-11", "unit": "酸性の強さの順序", "type": "choice", "q": "安息香酸とフェノールの混合エーテル溶液から、安息香酸のみを水層に分離して取り出したい。加えるべき試薬として最も適切なものはどれか。", "choices": ["塩化鉄(III)水溶液", "塩酸", "炭酸水素ナトリウム水溶液", "水酸化ナトリウム水溶液"], "answer": 2, "hint": "炭酸よりも強く、フェノールよりも弱い酸との反応を利用します。", "book": "有機編 第11講"}, {"id": "q-org-032", "lecture": "org-11", "unit": "サリチル酸からつくられる医薬品", "type": "choice", "q": "サリチル酸 6.90 g に十分な量の無水酢酸を反応させ、すべてアセチルサリチル酸に変換した。得られるアセチルサリチル酸は何 g か。原子量は H=1.0、C=12、O=16 とし、サリチル酸の式量は 138、アセチルサリチル酸の式量は 180 とする。", "choices": ["9.00 g", "13.8 g", "4.50 g", "6.90 g"], "answer": 0, "hint": "サリチル酸 1 mol からアセチルサリチル酸 1 mol が生成します。", "book": "有機編 第11講"}, {"id": "q-org-033", "lecture": "org-11", "unit": "④ クメン法（工業的製法）", "type": "choice", "q": "クメン法によるフェノールの工業的製法について、正しい説明はどれか。", "choices": ["クメンを酸化して得られる中間体はクメンヒドロペルオキシドである。", "反応の副生成物として得られるアセトンは、利用価値がないため廃棄される。", "クメンを希硫酸で分解すると、フェノールとメタノールが生成する。", "ベンゼンにエテンを付加させてクメンをつくる。"], "answer": 0, "hint": "中間体は過酸化物（ペルオキシド）です。", "book": "有機編 第11講"}, {"id": "q-org-034", "lecture": "org-12", "unit": "ジアゾ化", "type": "choice", "q": "アニリンを氷冷下でジアゾ化して得られた塩化ベンゼンジアゾニウムの水溶液を、5 ℃ 以上の室温に放置した。このとき観察される変化として正しいものはどれか。", "choices": ["橙色の沈殿が生じ、p-フェニルアゾフェノールが生成する。", "赤紫色の呈色が起こり、アセトアニリドが生成する。", "気体の窒素が発生し、フェノールが生成する。", "気体の水素が発生し、アニリンが遊離する。"], "answer": 2, "hint": "ジアゾニウム塩は高温では水と反応して分解します。", "book": "有機編 第12講"}, {"id": "q-org-035", "lecture": "org-12", "unit": "ベンゼンからアニリンへの合成経路", "type": "choice", "q": "ベンゼンからアニリンを合成する多段階反応において、ニトロベンゼンを還元してアニリン塩酸塩を得るために用いられる試薬はどれか。", "choices": ["濃硝酸と濃硫酸", "水酸化ナトリウム水溶液", "亜硝酸ナトリウムと塩酸", "スズと塩酸"], "answer": 3, "hint": "ニトロ基を還元してアミノ基にするための金属と酸の組み合わせです。", "book": "有機編 第12講"}, {"id": "q-org-036", "lecture": "org-12", "unit": "分離の手順（アニリン・安息香酸・フェノール・ニトロベンゼンの混合物）", "type": "choice", "q": "アニリン、安息香酸、フェノール、ニトロベンゼンの混合エーテル溶液がある。これにまず塩酸を加えて振り混ぜたとき、水層へ移動する物質はどれか。", "choices": ["安息香酸ナトリウム", "ナトリウムフェノキシド", "アニリン塩酸塩", "ニトロベンゼン"], "answer": 2, "hint": "酸と反応して塩になり、水に溶ける性質をもつのは塩基性物質です。", "book": "有機編 第12講"}, {"id": "q-org-037", "lecture": "org-13", "unit": "単糖類（グルコースの環状構造と還元性、フルクトース・ガラクトース）", "type": "choice", "q": "グルコースやフルクトースの性質に関する記述として正しいものはどれか。", "choices": ["グルコースは五員環構造を、フルクトースは六員環構造を主にとる。", "グルコースはヘミアセタール構造をもつため、水溶液中で開環してアルデヒド基を生じ還元性を示す。", "α-グルコースとβ-グルコースは、ハース投影式において4位の炭素につく-OHの向きで区別される。", "フルクトースは鎖状構造でケトン基をもつため、塩基性条件においても還元性を示さない。"], "answer": 1, "hint": "還元性の有無は、開環してアルデヒド基が生じるかどうかで決まります。", "book": "有機編 第13講"}, {"id": "q-org-038", "lecture": "org-13", "unit": "単糖類（グルコースの環状構造と還元性、フルクトース・ガラクトース）", "type": "choice", "q": "グルコース 3.60 g を水に溶かし、十分な量のフェーリング液を加えて加熱した。生じる酸化銅(I) Cu2O の質量は何 g か。ただし、グルコース 1 mol から Cu2O 1 mol が生じるものとし、原子量は H=1.0、C=12、O=16、Cu=63.5 とする。", "choices": ["3.60 g", "1.43 g", "4.29 g", "2.86 g"], "answer": 3, "hint": "グルコースの分子量は180、Cu2Oの式量は143です。物質量の比を考えましょう。", "book": "有機編 第13講"}, {"id": "q-org-039", "lecture": "org-13", "unit": "二糖類（グリコシド結合と還元性・加水分解の生成物）", "type": "choice", "q": "二糖類に関する記述として正しいものはどれか。", "choices": ["セロビオースを希硫酸で加水分解すると、グルコースとフルクトースが1分子ずつ生じる。", "スクロースとトレハロースは、いずれも構成単位のヘミアセタール構造が結合に使われているため、還元性を示さない。", "マルトースはα-グルコース2分子がβ-1,4結合したものであり、還元性を示す。", "ラクトースは、1つのヘミアセタール構造がグリコシド結合に使われているため、還元性を示さない。"], "answer": 1, "hint": "還元性の有無は、開環できるヘミアセタール構造が残っているかどうかで決まります。", "book": "有機編 第13講"}, {"id": "q-org-040", "lecture": "org-14", "unit": "デンプンとグリコーゲン（構造・ヨウ素デンプン反応・加水分解）", "type": "choice", "q": "デンプン 32.4 g を希硫酸で完全に加水分解した。得られるグルコースの質量と、反応で消費された水の質量の組み合わせとして正しいものはどれか。ただし、原子量は H=1.0、C=12、O=16 とし、デンプンの繰り返し単位を C6H10O5 とする。", "choices": ["グルコース：34.2 g、水：3.60 g", "グルコース：36.0 g、水：3.60 g", "グルコース：36.0 g、水：1.80 g", "グルコース：32.4 g、水：1.80 g"], "answer": 1, "hint": "デンプンの繰り返し単位の式量は162、グルコースの分子量は180です。単位1つにつき水1分子が反応します。", "book": "有機編 第14講"}, {"id": "q-org-041", "lecture": "org-14", "unit": "セルロースとその誘導体（直鎖構造・再生繊維・半合成繊維）", "type": "choice", "q": "多糖類の構造とヨウ素デンプン反応に関する記述として正しいものはどれか。", "choices": ["セルロースにヨウ素溶液を加えると、直鎖構造の内部にヨウ素分子が取り込まれ青色を呈する。", "グリコーゲンはアミロペクチンよりも枝分かれが少なく、ヨウ素デンプン反応で青色を呈する。", "アミロースはα-1,4結合により枝分かれの多い構造をとり、ヨウ素デンプン反応で赤紫色を呈する。", "セルロースはβ-1,4結合により直鎖状の構造をとり、鎖どうしが水素結合で強く結びついているため熱水に溶けない。"], "answer": 3, "hint": "結合の種類（αかβか）によって、らせん構造か直鎖構造かが決まります。", "book": "有機編 第14講"}, {"id": "q-org-042", "lecture": "org-14", "unit": "セルロースとその誘導体（直鎖構造・再生繊維・半合成繊維）", "type": "choice", "q": "セルロースの誘導体に関する記述として正しいものはどれか。", "choices": ["アセチルセルロースは、セルロースを二硫化炭素と水酸化ナトリウムで処理して得られる再生繊維である。", "ニトロセルロースは、セルロースのヒドロキシ基が硝酸エステル化されたもので、ニトロ化合物ではない。", "トリアセチルセルロースは、グルコース単位あたり2つのヒドロキシ基をアセチル化したものである。", "銅アンモニアレーヨン（キュプラ）は、セルロースのアセチル化によって得られる半合成繊維である。"], "answer": 1, "hint": "官能基を化学的に変えたものが半合成繊維、溶かして再生したものが再生繊維です。", "book": "有機編 第14講"}, {"id": "q-org-043", "lecture": "org-15", "unit": "α-アミノ酸の構造と双性イオン", "type": "choice", "q": "次のアミノ酸のうち、α炭素が不斉炭素原子ではないため、光学異性体をもたないものはどれか。", "choices": ["アラニン", "グリシン", "セリン", "システイン"], "answer": 1, "hint": "側鎖Rが水素原子-Hであるものを探してください。", "book": "有機編 第15講"}, {"id": "q-org-044", "lecture": "org-15", "unit": "pH による形の変化：陽イオン形・双性イオン・陰イオン形", "type": "choice", "q": "等電点が6.0であるアラニンを、pH 2.0の強酸性溶液に溶かして直流電圧をかけたとき、アラニンはどのように移動するか。", "choices": ["陽極(＋極)へ移動する", "原点付近にとどまり移動しない", "沈殿を生じてろ紙上を移動しない", "陰極(−極)へ移動する"], "answer": 3, "hint": "pHが等電点より小さいとき、アミノ酸はH+を受け取って何イオンになりますか？", "book": "有機編 第15講"}, {"id": "q-org-045", "lecture": "org-15", "unit": "酸性・塩基性アミノ酸の等電点：平均する2つの pKa の選び方", "type": "choice", "q": "ある塩基性アミノ酸(リシン)の3つの電離定数がpKa1=2.18, pKa2=8.95, pKa3=10.53であるとき、このアミノ酸の等電点として正しい値はどれか。", "choices": ["9.74", "5.57", "6.36", "10.53"], "answer": 0, "hint": "塩基性アミノ酸では、大きい方の2つのpKaの平均をとります。", "book": "有機編 第15講"}, {"id": "q-org-046", "lecture": "org-16", "unit": "ペプチドの分子量：脱水した水の分だけ差し引く", "type": "choice", "q": "アラニン(分子量89)とセリン(分子量105)が1分子ずつ脱水縮合してできたジペプチドの分子量はいくらか。", "choices": ["185", "194", "158", "176"], "answer": 3, "hint": "アミノ酸の分子量の和から、取れた水1分子分の質量を引きます。", "book": "有機編 第16講"}, {"id": "q-org-047", "lecture": "org-16", "unit": "三次構造：側鎖どうしの相互作用による全体の形", "type": "choice", "q": "タンパク質の三次構造を固定する側鎖間の相互作用のうち、2つのシステイン残基の-SHどうしが酸化されてできる共有結合を何というか。", "choices": ["ジスルフィド結合", "イオン結合", "ペプチド結合", "水素結合"], "answer": 0, "hint": "-S-S-という結合の名称です。", "book": "有機編 第16講"}, {"id": "q-org-048", "lecture": "org-16", "unit": "ビウレット反応：ペプチド結合が2つ以上あることの検出", "type": "choice", "q": "あるペプチドについて調べたところ、ビウレット反応は陰性であったが、キサントプロテイン反応は陽性(黄色)であった。このペプチドとして適切なものはどれか。", "choices": ["Gly-Ala", "Gly-Gly-Gly", "Phe-Gly", "Ala-Gly-Phe"], "answer": 2, "hint": "ビウレット反応が陰性なのはジペプチド、キサントプロテイン反応が陽性なのはベンゼン環を含むものです。", "book": "有機編 第16講"}, {"id": "q-org-049", "lecture": "org-17", "unit": "高級脂肪酸と油脂の構造", "type": "choice", "q": "炭素数18の高級脂肪酸のうち、分子内に炭素原子間の二重結合(C=C)を2つもち、式量が280である物質の名称はどれか。", "choices": ["リノール酸", "パルミチン酸", "リノレン酸", "オレイン酸"], "answer": 0, "hint": "ステアリン酸(C=Cが0)からC=Cが1つ増えるごとに、Hは2つ減り、式量は2ずつ減ります。", "book": "有機編 第17講"}, {"id": "q-org-050", "lecture": "org-17", "unit": "けん化価とヨウ素価", "type": "choice", "q": "ある油脂のけん化価を測定したところ、190であった。この油脂の分子量(式量)に最も近い値はどれか。ただし、KOHの式量は56とする。", "choices": ["884", "840", "890", "920"], "answer": 0, "hint": "けん化価 = 168000 / 分子量(M) の関係式を利用して計算します。", "book": "有機編 第17講"}, {"id": "q-org-051", "lecture": "org-17", "unit": "せっけんの欠点", "type": "choice", "q": "せっけん（高級脂肪酸ナトリウム）の性質に関する記述として正しいものはどれか。", "choices": ["Ca2+やMg2+を多く含む硬水中で使用しても、沈殿を生じず洗浄力を保つ。", "加水分解して塩基性を示すため、絹や羊毛などの動物性繊維を傷めてしまう。", "強酸と強塩基からなる塩なので、水溶液は中性を示す。", "合成洗剤と異なり、親水基としてスルホン酸由来の構造をもつ。"], "answer": 1, "hint": "せっけんは弱酸と強塩基の塩であるため、水溶液の液性に特徴があります。", "book": "有機編 第17講"}, {"id": "q-org-052", "lecture": "org-18", "unit": "単量体・重合体・重合度", "type": "choice", "q": "平均分子量が5.2x10^4のスチレン（単量体の式量104）の重合体がある。このポリスチレンの重合度nとして正しい数値はどれか。", "choices": ["2000", "200", "500", "1000"], "answer": 2, "hint": "付加重合では単量体の式量と繰り返し単位の式量は等しくなります。", "book": "有機編 第18講"}, {"id": "q-org-053", "lecture": "org-18", "unit": "界面重縮合：ナイロン6,6 の実験室的製法", "type": "choice", "q": "アジピン酸ジクロリドとヘキサメチレンジアミンを用いた界面重縮合でナイロン6,6を合成する際、水層に水酸化ナトリウムを加える理由として最も適切なものはどれか。", "choices": ["単量体であるアジピン酸ジクロリドを水層に溶けやすくする。", "副生する塩化水素を中和し、ジアミンが反応できなくなるのを防ぐ。", "アミド結合の生成を促進するための触媒として加える。", "生成したナイロン6,6の膜を溶かして、糸として引き出しやすくする。"], "answer": 1, "hint": "この反応では水の代わりに酸が副生しますが、ジアミンは塩基性であることに注目しましょう。", "book": "有機編 第18講"}, {"id": "q-org-054", "lecture": "org-18", "unit": "アセタール化の計算：–OH 1個あたり式量が6増える", "type": "choice", "q": "ポリビニルアルコール(PVA)88gをホルムアルデヒドで処理してアセタール化したところ、92.8gのビニロンが得られた。PVA中のヒドロキシ基(-OH)の何%がアセタール化されたか。", "choices": ["50%", "40%", "20%", "30%"], "answer": 1, "hint": "-OHが1molアセタール化されるごとに、式量は6増加します。PVA 88gは何molの繰り返し単位を含むでしょうか。", "book": "有機編 第18講"}, {"id": "q-org-055", "lecture": "org-19", "unit": "NaCl 水溶液を通すと HCl が同物質量だけ出てくる", "type": "choice", "q": "0.10 mol/L の塩化ナトリウム水溶液 200 mL を陽イオン交換樹脂に通し、流出液をすべて集めた。この液を中和するのに必要な 0.20 mol/L 水酸化ナトリウム水溶液の体積は何 mL か。", "choices": ["100 mL", "400 mL", "200 mL", "50 mL"], "answer": 0, "hint": "NaClから生じるHClの物質量は、元のNaClの物質量と等しくなります。", "book": "有機編 第19講"}, {"id": "q-org-056", "lecture": "org-19", "unit": "2価イオンが混ざるときの計算", "type": "choice", "q": "0.10 mol/L の塩化カルシウム CaCl2 水溶液 100 mL を陽イオン交換樹脂に通し、流出液をすべて集めた。この液を中和するのに必要な 0.10 mol/L 水酸化ナトリウム水溶液の体積は何 mL か。", "choices": ["400 mL", "100 mL", "200 mL", "50 mL"], "answer": 2, "hint": "2価の陽イオンであるCa2+は、1個で2個のH+を押し出します。", "book": "有機編 第19講"}, {"id": "q-org-057", "lecture": "org-19", "unit": "母体の作り方：なぜ p-ジビニルベンゼンを加えるのか", "type": "choice", "q": "イオン交換樹脂の母体を作る際、スチレンに p-ジビニルベンゼンを加えて共重合させる主な目的として正しいものはどれか。", "choices": ["樹脂を水に溶けやすくし、イオンとの反応速度を上げるため。", "直鎖状の高分子にして、カラムに隙間なく詰めやすくするため。", "樹脂に親水性のスルホ基を導入しやすくするため。", "鎖間を橋かけして網目状構造にし、不溶性の粒にするため。"], "answer": 3, "hint": "ビニル基を2つ持つ分子が、鎖どうしをどのようにつなぐか考えましょう。", "book": "有機編 第19講"}, {"id": "q-org-058", "lecture": "org-20", "unit": "ナイロン（ポリアミド：縮合重合と開環重合）", "type": "choice", "q": "ナイロン6,6とナイロン6について、分子量がともに 22600 である試料がある。ナイロン6,6の重合度を n1、ナイロン6の重合度を n2 としたとき、その値の組み合わせとして正しいものはどれか。原子量は H=1, C=12, N=14, O=16 とし、末端の影響は無視する。", "choices": ["n1 = 100, n2 = 100", "n1 = 200, n2 = 200", "n1 = 100, n2 = 200", "n1 = 200, n2 = 100"], "answer": 2, "hint": "ナイロン6,6の繰り返し単位の式量は226、ナイロン6は113です。", "book": "有機編 第20講"}, {"id": "q-org-059", "lecture": "org-20", "unit": "伸ばしたゴムに熱をかけると縮む理由", "type": "choice", "q": "おもりをつるして引き伸ばした天然ゴムに熱湯をかけると、ゴムが縮んでおもりが持ち上がった。この現象の理由として正しい説明はどれか。", "choices": ["熱によって単結合まわりの回転が活発になり、分子鎖が丸まった形を取りやすくなったため。", "熱によって鎖の硫黄による架橋反応がさらに進行し、網目構造が密になったため。", "熱によって二重結合の回転が活発になり、シス型からトランス型へと変化したため。", "熱によって空気中の酸素と反応し、ポリイソプレンの鎖が切断されて短くなったため。"], "answer": 0, "hint": "ゴムの弾性は、二重結合と単結合のどちらの回転の自由さに由来するかを考えます。", "book": "有機編 第20講"}, {"id": "q-org-060", "lecture": "org-20", "unit": "共重合ゴム：SBR と NBR", "type": "choice", "q": "1,3-ブタジエン(分子量54)とアクリロニトリル(分子量53)を物質量比 1 : 1 で共重合させた NBR がある。このゴムに含まれる窒素 N(原子量14)の質量パーセントは何 % か。小数第2位を四捨五入して答えよ。", "choices": ["8.7 %", "26.2 %", "14.0 %", "13.1 %"], "answer": 3, "hint": "1:1のセット(式量の合計は107)の中に、窒素原子がいくつ含まれるか計算します。", "book": "有機編 第20講"}, {"id": "q-org-061", "lecture": "org-01", "unit": "構造決定", "type": "choice", "q": "分子式 C5H10O で表される有機化合物のうち、フェーリング液を還元せず、かつヨードホルム反応にも陰性であった。この化合物の構造として最も適切なものはどれか。", "choices": ["ペンタナール", "2-ペンタノン", "3-ペンタノン", "2-メチルブタナール"], "answer": 2, "hint": "フェーリング液を還元しないのはケトンであり、ヨードホルム反応を示さないのはアセチル基を持たないものです。", "book": "有機編 第1講"}, {"id": "q-org-062", "lecture": "org-01", "unit": "構造決定", "type": "numeric", "q": "炭素、水素、酸素のみからなる脂肪族化合物 1.50 g を完全に燃焼させたところ、二酸化炭素 3.30 g と水 1.80 g が得られた。この化合物の組成式（CxHyOz）において、水素の数 y にあたる数値はいくつか。", "answer": 8, "tolerance": 0.1, "hint": "各生成物の質量から、燃焼前の化合物に含まれていた C, H, O の物質量（mol）の比を求めましょう。", "book": "有機編 第1講"}, {"id": "q-org-063", "lecture": "org-01", "unit": "構造決定", "type": "choice", "q": "分子式 C4H10O で表される化合物のうち、金属ナトリウムと反応して水素を発生し、さらに酸化してもケトン（カルボニル化合物の一種）を生じないものの分類として、正しいものはどれか。", "choices": ["第一級アルコールのみ", "第二級アルコールのみ", "第三級アルコールのみ", "第一級アルコールと第三級アルコールの両方"], "answer": 3, "hint": "金属ナトリウムと反応するのはアルコールです。酸化されてケトンになるのは第二級アルコールに限られます。", "book": "有機編 第1講"}, {"id": "q-org-064", "lecture": "org-01", "unit": "構造決定", "type": "choice", "q": "分子式 C5H12O で表されるアルコールの構造異性体のうち、分子内に不斉炭素原子を持つものは何種類あるか。", "choices": ["1種類", "2種類", "3種類", "4種類"], "answer": 2, "hint": "炭素鎖の形を書き出し、4つの異なる置換基が結合している炭素原子を探しましょう。2-ペンタノールなどが候補です。", "book": "有機編 第1講"}, {"id": "q-org-065", "lecture": "org-01", "unit": "構造決定", "type": "choice", "q": "化合物 A（C4H8O2）を加水分解したところ、カルボン酸 B とアルコール C が得られた。B は銀鏡反応を示し、C を酸化するとケトン D が得られた。このとき A の名称として正しいものはどれか。", "choices": ["ギ酸プロピル", "ギ酸イソプロピル", "酢酸エチル", "酢酸メチル"], "answer": 1, "hint": "銀鏡反応を示すカルボン酸はギ酸のみです。酸化してケトンになるアルコールは第二級アルコールです。", "book": "有機編 第1講"}, {"id": "q-org-066", "lecture": "org-02", "unit": "立体構造", "type": "choice", "q": "炭素原子間の結合と分子の形状に関する記述として、誤っているものはどれか。", "choices": ["エチレン分子を構成するすべての原子は、同一平面上に位置する。", "アセチレン分子を構成するすべての原子は、一直線上に位置する。", "シクロヘキサン分子を構成するすべての炭素原子は、同一平面上に位置する。", "プロパン分子の3つの炭素原子は、折れ線状に結合している。"], "answer": 2, "hint": "単結合のみで構成される環状構造において、結合角（約109.5度）を保つための形状を思い出しましょう。", "book": "有機編 第2講"}, {"id": "q-org-067", "lecture": "org-02", "unit": "立体構造", "type": "choice", "q": "パラキシレン（p-CH3-C6H4-CH3）の分子全体において、同一平面上に同時に存在させることができる原子の最大数はいくつか。ただし、単結合の回転を考慮するものとする。", "choices": ["10", "12", "14", "16"], "answer": 2, "hint": "ベンゼン環とその直結原子は同一平面です。メチル基の3つの水素のうち、平面に乗るのはいくつでしょうか。", "book": "有機編 第2講"}, {"id": "q-org-068", "lecture": "org-02", "unit": "立体構造", "type": "choice", "q": "次の分子のうち、二重結合や三重結合による結合の回転制限により、分子内のすべての原子が常に同一平面上に固定されているものはどれか。", "choices": ["1,2-ジクロロエタン", "1,1-ジクロロエチレン", "プロペン", "トルエン"], "answer": 1, "hint": "単結合（回転可能）を含まず、sp2混成軌道による平面構造のみで構成される分子を探します。", "book": "有機編 第2講"}, {"id": "q-org-069", "lecture": "org-02", "unit": "立体構造", "type": "choice", "q": "炭素原子の混成軌道と結合角に関する記述として、最も適切なものはどれか。", "choices": ["エチレンの炭素原子は sp 混成軌道を持ち、H-C-H の結合角は約 120 度である。", "アセチレンの炭素原子は sp2 混成軌道を持ち、C-C-H の結合角は 180 度である。", "ベンゼンの炭素原子は sp3 混成軌道を持ち、C-C-C の結合角は 120 度である。", "メタンの炭素原子は sp3 混成軌道を持ち、H-C-H の結合角は約 109.5 度である。"], "answer": 3, "hint": "二重結合は sp2、三重結合は sp 混成軌道に対応します。それぞれの理想的な結合角を確認しましょう。", "book": "有機編 第2講"}, {"id": "q-org-070", "lecture": "org-03", "unit": "構造異性体", "type": "choice", "q": "分子式 C3H6O2 で表される化合物のうち、エステルである構造異性体は何種類存在するか。", "choices": ["1種類", "2種類", "3種類", "4種類"], "answer": 1, "hint": "カルボン酸のHをアルキル基で置換した構造（R-COO-R'）を考えます。", "book": "有機編 第3講"}, {"id": "q-org-071", "lecture": "org-03", "unit": "構造異性体", "type": "choice", "q": "分子式 C4H8O で表され、分子内にカルボニル基（>C=O）を持つ構造異性体は全部で何種類か。", "choices": ["2種類", "3種類", "4種類", "5種類"], "answer": 1, "hint": "アルデヒド（R-CHO）とケトン（R-CO-R'）の両方を数え上げます。", "book": "有機編 第3講"}, {"id": "q-org-072", "lecture": "org-03", "unit": "構造異性体", "type": "choice", "q": "分子式 C7H8O で表される芳香族化合物の構造異性体は全部で何種類存在するか。", "choices": ["3種類", "4種類", "5種類", "6種類"], "answer": 2, "hint": "アルコール、エーテル、およびフェノール類の3つのパターンを考慮します。", "book": "有機編 第3講"}, {"id": "q-org-073", "lecture": "org-03", "unit": "構造異性体", "type": "choice", "q": "分子式 C4H8O2 で表されるカルボン酸とエステルの構造異性体に関する記述として正しいものはどれか。", "choices": ["カルボン酸が2種類、エステルが2種類存在する", "カルボン酸が2種類、エステルが4種類存在する", "カルボン酸が3種類、エステルが3種類存在する", "カルボン酸が3種類、エステルが4種類存在する"], "answer": 1, "hint": "カルボン酸は炭素鎖の分岐を、エステルは酸側とアルコール側の炭素の割り振りを考えます。", "book": "有機編 第3講"}, {"id": "q-org-074", "lecture": "org-04", "unit": "立体異性体", "type": "choice", "q": "次の化合物のうち、シス-トランス異性体（幾何異性体）が存在するものはどれか。", "choices": ["1,1-ジクロロエチレン", "2-メチル-2-ブテン", "1,2-ジクロロエチレン", "1-ブテン"], "answer": 2, "hint": "二重結合を形成する各炭素原子に、それぞれ異なる2つの原子または基が結合しているか確認します。", "book": "有機編 第4講"}, {"id": "q-org-075", "lecture": "org-04", "unit": "立体異性体", "type": "choice", "q": "分子式 C4H10O で表されるアルコールの構造異性体のうち、不斉炭素原子を持つものはどれか。", "choices": ["1-ブタノール", "2-ブタノール", "2-メチル-1-プロパノール", "2-メチル-2-プロパノール"], "answer": 1, "hint": "4つの異なる原子や置換基が結合している炭素原子を探します。", "book": "有機編 第4講"}, {"id": "q-org-076", "lecture": "org-04", "unit": "立体異性体", "type": "choice", "q": "一対の鏡像異性体（光学異性体）どうしで、一般に値が「異なる」性質はどれか。", "choices": ["融点および沸点", "水に対する溶解度", "他の不斉炭素を持つ化合物との反応速度", "密度"], "answer": 2, "hint": "鏡像異性体は物理的性質は同じですが、他の光学活性物質との相互作用において違いが生じます。", "book": "有機編 第4講"}, {"id": "q-org-077", "lecture": "org-04", "unit": "立体異性体", "type": "choice", "q": "2,3-ジヒドロキシブタン二酸（酒石酸）の1分子に含まれる不斉炭素原子の数はいくつか。", "choices": ["1個", "2個", "3個", "4個"], "answer": 1, "hint": "HOOC-CH(OH)-CH(OH)-COOH の構造を書き、各炭素の結合先を確認します。", "book": "有機編 第4講"}, {"id": "q-org-078", "lecture": "org-05", "unit": "飽和炭化水素", "type": "choice", "q": "2-メチルブタンの1つの水素原子を塩素原子で置換して得られる構造異性体（一塩素化物）は、全部で何種類存在するか。", "choices": ["2種類", "3種類", "4種類", "5種類"], "answer": 2, "hint": "分子の対称性を考慮して、異なる位置にある炭素原子の種類を数えてみましょう。", "book": "有機編 第5講"}, {"id": "q-org-079", "lecture": "org-05", "unit": "飽和炭化水素", "type": "choice", "q": "あるアルカン1 molを完全に燃焼させたところ、生成した水H2Oの物質量が、二酸化炭素CO2の物質量の1.25倍であった。このアルカンの名称として正しいものはどれか。", "choices": ["プロパン", "ブタン", "ペンタン", "ヘキサン"], "answer": 1, "hint": "アルカンの一般式 CnH2n+2 の燃焼反応式を書き、生成物の係数比 (n+1)/n = 1.25 を解いてみましょう。", "book": "有機編 第5講"}, {"id": "q-org-080", "lecture": "org-05", "unit": "飽和炭化水素", "type": "choice", "q": "構造式 CH3-CH2-CH(CH2-CH2-CH3)-CH2-CH3 で表されるアルカンの、IUPAC命名法に基づく正しい名称はどれか。", "choices": ["3-プロピルペンタン", "2-エチルヘキサン", "4-エチルヘキサン", "3-エチルヘキサン"], "answer": 3, "hint": "最も長い炭素鎖（主鎖）を正しく選び、置換基の番号が小さくなるように番号を振ります。", "book": "有機編 第5講"}, {"id": "q-org-081", "lecture": "org-05", "unit": "飽和炭化水素", "type": "choice", "q": "シクロアルカンに関する記述として正しいものはどれか。", "choices": ["シクロプロパンの炭素間結合角は、正四面体構造の角度に近いため非常に安定である。", "シクロヘキサンは、すべての炭素原子が同一平面上に並んだ平面構造をとる。", "環状構造をもつため、一般式はアルケンと同じ CnH2n で表される。", "シクロプロパンは結合角の歪みが小さいため、シクロヘキサンよりも反応性が低い。"], "answer": 2, "hint": "飽和炭化水素が環状になった場合の水素原子の数の変化と、分子の立体的な歪みに注目しましょう。", "book": "有機編 第5講"}, {"id": "q-org-082", "lecture": "org-06", "unit": "不飽和炭化水素", "type": "choice", "q": "2-ブテンに臭素Br2を付加させたときに得られる生成物の名称として正しいものはどれか。", "choices": ["1,2-ジブロモブタン", "2,2-ジブロモブタン", "2,3-ジブロモブタン", "1,4-ジブロモブタン"], "answer": 2, "hint": "付加反応は二重結合の部分で起こり、そこに臭素原子が1つずつ結合します。", "book": "有機編 第6講"}, {"id": "q-org-083", "lecture": "org-06", "unit": "不飽和炭化水素", "type": "choice", "q": "アセチレンに適切な触媒を用いて物質Xを付加させると、合成樹脂や接着剤の原料となる酢酸ビニルが得られる。この物質Xとして正しいものはどれか。", "choices": ["塩化水素", "メタノール", "酢酸", "シアン化水素"], "answer": 2, "hint": "ビニル基（CH2=CH-）に結合している官能基が「酢酸」に由来することを考えます。", "book": "有機編 第6講"}, {"id": "q-org-084", "lecture": "org-06", "unit": "不飽和炭化水素", "type": "choice", "q": "食品用ラップフィルムの原料などに用いられるポリ塩化ビニリデンの単量体（モノマー）の構造はどれか。", "choices": ["CH2=CHCl", "CH2=CCl2", "CHCl=CHCl", "CCl2=CCl2"], "answer": 1, "hint": "「ビニリデン」は、同じ炭素原子に2つの置換基がついた構造を指します。", "book": "有機編 第6講"}, {"id": "q-org-085", "lecture": "org-06", "unit": "不飽和炭化水素", "type": "choice", "q": "プロペン（プロピレン）を臭素水に通すと、赤褐色の溶液が速やかに無色に変化する。この現象に関する説明として正しいものはどれか。", "choices": ["臭素がプロペンのメチル基部分の水素と置換したため。", "プロペンの二重結合に臭素が付加し、臭素分子が消費されたため。", "プロペンが触媒なしで速やかに重合し、臭素を吸着したため。", "臭素水中の臭素がプロペンを酸化し、自身は臭化物イオンに還元されたため。"], "answer": 1, "hint": "二重結合をもつ化合物と臭素が反応する際の、反応の種類と色の変化の理由を考えます。", "book": "有機編 第6講"}, {"id": "q-org-086", "lecture": "org-07", "unit": "アルコール", "type": "choice", "q": "ヨウ素と水酸化ナトリウム水溶液を加えて温めたとき、特有の臭気をもつ黄色沈殿を生じるアルコールはどれか。", "choices": ["メタノール", "エタノール", "1-プロパノール", "2-メチル-2-プロパノール"], "answer": 1, "hint": "CH3CH(OH)- の構造を持つアルコールを探しましょう。", "book": "有機編 第7講"}, {"id": "q-org-087", "lecture": "org-07", "unit": "アルコール", "type": "choice", "q": "硫酸酸性の二クロム酸カリウム水溶液を作用させても、通常の状態では酸化されにくいアルコールはどれか。", "choices": ["1-ブタノール", "2-ブタノール", "2-メチル-1-プロパノール", "2-メチル-2-プロパノール"], "answer": 3, "hint": "ヒドロキシ基が結合している炭素原子に、水素原子がいくつ結合しているかに注目します。", "book": "有機編 第7講"}, {"id": "q-org-088", "lecture": "org-07", "unit": "エーテル", "type": "choice", "q": "ジエチルエーテルの性質に関する記述として最も適当なものはどれか。", "choices": ["同程度の分子量をもつアルコールよりも沸点が高い。", "分子内に水素結合を形成するため、水に極めて溶けやすい。", "揮発性が高く引火しやすいため、火気への厳重な注意が必要である。", "金属ナトリウムの小片を入れると、激しく水素を発生して溶ける。"], "answer": 2, "hint": "エーテルはアルコールと異なりヒドロキシ基（-OH）を持たないことの影響を考えます。", "book": "有機編 第7講"}, {"id": "q-org-089", "lecture": "org-07", "unit": "アルコール", "type": "choice", "q": "エタノールに濃硫酸を加え、約130～140度で加熱したときに得られる主な有機化合物はどれか。", "choices": ["エチレン", "アセトアルデヒド", "ジエチルエーテル", "酢酸エチル"], "answer": 2, "hint": "温度条件によって、分子内脱水が起こるか分子間脱水が起こるかが決まります。", "book": "有機編 第7講"}, {"id": "q-org-090", "lecture": "org-08", "unit": "アルデヒド", "type": "choice", "q": "アンモニア性硝酸銀溶液を加えて穏やかに加熱したとき、容器の壁面に銀が析出する反応（銀鏡反応）を示す物質はどれか。", "choices": ["アセトン", "ジメチルエーテル", "ホルムアルデヒド", "酢酸エチル"], "answer": 2, "hint": "還元性をもつ「アルデヒド基」をもつ物質を選びます。", "book": "有機編 第8講"}, {"id": "q-org-091", "lecture": "org-08", "unit": "アルデヒド", "type": "choice", "q": "ホルムアルデヒドの性質に関する記述として正しいものはどれか。", "choices": ["常温・常圧において、無色・無臭の液体である。", "約37～40％の水溶液はホルマリンと呼ばれ、防腐剤などに用いられる。", "酸化されるとケトンの一種であるアセトンに変化する。", "フェーリング液を加えて加熱しても、赤色沈殿を生じない。"], "answer": 1, "hint": "ホルムアルデヒドの状態や、その水溶液の慣用名を思い出しましょう。", "book": "有機編 第8講"}, {"id": "q-org-092", "lecture": "org-08", "unit": "ケトン", "type": "choice", "q": "ケトン（例：アセトン）がアルデヒドとは異なり、穏やかな酸化剤では酸化されにくい理由として、最も適切なものはどれか。", "choices": ["分子内に炭素同士の二重結合を含んでいるため。", "分子の極性が非常に小さく、試薬と反応しにくいため。", "アルデヒドよりも沸点が高く、反応温度に達しないため。", "カルボニル基の炭素原子に、結合している水素原子がないため。"], "answer": 3, "hint": "アルデヒド基（-CHO）とカルボニル基（-CO-）の構造的な違いに注目します。", "book": "有機編 第8講"}, {"id": "q-org-093", "lecture": "org-08", "unit": "カルボン酸と還元性", "type": "choice", "q": "次の化合物のうち、カルボン酸でありながら、銀鏡反応やフェーリング反応などの還元性を示す物質はどれか。", "choices": ["酢酸", "ギ酸", "酪酸", "安息香酸"], "answer": 1, "hint": "分子内に「カルボキシ基」と「アルデヒド基」の両方の構造を見いだせる物質を探します。", "book": "有機編 第8講"}, {"id": "q-org-094", "lecture": "org-09", "unit": "カルボン酸", "type": "choice", "q": "ギ酸(HCOOH)が、酢酸などの他のカルボン酸とは異なり、銀鏡反応を示す理由として最も適切なものはどれか。", "choices": ["分子量がカルボン酸の中で最も小さく、水に溶けやすいため。", "炭素原子に直接結合している水素原子が電離しやすいから。", "空気中の酸素によって容易に二酸化炭素まで酸化されるから。", "分子内にカルボキシ基だけでなくホルミル基の構造も持っているから。"], "answer": 3, "hint": "ギ酸の構造式（H-COOH）をよく見て、他の官能基が隠れていないか探しましょう。", "book": "有機編 第9講"}, {"id": "q-org-095", "lecture": "org-09", "unit": "カルボン酸", "type": "choice", "q": "次のカルボン酸のうち、水溶液中での酸の強さが最も強いものはどれか。", "choices": ["酢酸", "モノクロロ酢酸", "プロピオン酸", "ギ酸"], "answer": 1, "hint": "カルボキシ基に結合している原子の、電子を引き付ける強さに注目しましょう。", "book": "有機編 第9講"}, {"id": "q-org-096", "lecture": "org-09", "unit": "エステル", "type": "numeric", "q": "酢酸エチル(分子量88.0) 8.8g を完全にけん化するために必要な水酸化ナトリウム(式量40.0)は何gか。有効数字2桁で答えなさい。", "answer": 4.0, "tolerance": 0.1, "hint": "エステル1molをけん化するのに必要な塩基の物質量を考えましょう。", "book": "有機編 第9講"}, {"id": "q-org-097", "lecture": "org-09", "unit": "エステル", "type": "choice", "q": "プロピオン酸メチル(C2H5COOCH3)を希硫酸とともに加熱して加水分解したときに得られる物質の組み合わせとして正しいものはどれか。", "choices": ["酢酸とエタノール", "プロピオン酸とメタノール", "ギ酸と1-プロパノール", "酢酸とメタノール"], "answer": 1, "hint": "エステル名「〇〇酸△△」の〇〇が酸、△△がアルコールに由来します。", "book": "有機編 第9講"}, {"id": "q-org-098", "lecture": "org-10", "unit": "芳香族炭化水素", "type": "choice", "q": "ベンゼンにニッケル触媒を用いて水素を十分に付加させたときに生成する化合物の名称はどれか。", "choices": ["n-ヘキサン", "シクロヘキサン", "シクロヘキセン", "1,3-シクロヘキサジエン"], "answer": 1, "hint": "ベンゼン環の3つの二重結合すべてに水素が結合するとどうなるか考えましょう。", "book": "有機編 第10講"}, {"id": "q-org-099", "lecture": "org-10", "unit": "芳香族炭化水素", "type": "choice", "q": "トルエンを濃硝酸と濃硫酸の混合物とともに加熱し、3つのニトロ基を導入して得られる爆薬としても知られる物質はどれか。", "choices": ["p-ニトロトルエン", "2,4-ジニトロトルエン", "2,4,6-トリニトロトルエン", "2,4,6-トリニトロフェノール"], "answer": 2, "hint": "トルエンの側鎖（メチル基）が置換反応の場所に与える影響（配向性）を思い出しましょう。", "book": "有機編 第10講"}, {"id": "q-org-100", "lecture": "org-10", "unit": "芳香族炭化水素", "type": "choice", "q": "スチレンを付加重合させて得られる高分子化合物の名称として正しいものはどれか。", "choices": ["ポリエチレン", "ポリ塩化ビニル", "ポリスチレン", "ポリプロピレン"], "answer": 2, "hint": "モノマー（単量体）の名前に「ポリ」をつけたものがポリマー（重合体）の名称になります。", "book": "有機編 第10講"}, {"id": "q-org-101", "lecture": "org-10", "unit": "芳香族炭化水素", "type": "choice", "q": "ニトロベンゼンをさらにニトロ化してジニトロベンゼンを得る際、主な生成物として得られる置換体はどれか。", "choices": ["o-ジニトロベンゼン", "m-ジニトロベンゼン", "p-ジニトロベンゼン", "1,2,4-トリニトロベンゼン"], "answer": 1, "hint": "ニトロ基(-NO2)がベンゼン環に結合している場合、次の置換基はどの位置に入りやすいかを考えます。", "book": "有機編 第10講"}, {"id": "q-org-102", "lecture": "org-10", "unit": "芳香族炭化水素", "type": "choice", "q": "ベンゼンと臭素を、鉄粉(または臭化鉄(III))を触媒として反応させたときに起こる反応の種類と生成物の組み合わせとして正しいものはどれか。", "choices": ["付加反応、ブロモベンゼン", "置換反応、ヘキサブロモシクロヘキサン", "付加反応、ヘキサブロモシクロヘキサン", "置換反応、ブロモベンゼン"], "answer": 3, "hint": "光を当てた場合と、触媒を用いた場合での反応の違いを区別しましょう。", "book": "有機編 第10講"}, {"id": "q-org-103", "lecture": "org-11", "unit": "フェノール類", "type": "choice", "q": "次の化合物のうち、塩化鉄(III)水溶液を加えたときに呈色反応を示さないものはどれか。", "choices": ["フェノール", "サリチル酸", "サリチル酸メチル", "ベンジルアルコール"], "answer": 3, "hint": "フェノール性ヒドロキシ基を持っているかどうかを考えます。", "book": "有機編 第11講"}, {"id": "q-org-104", "lecture": "org-11", "unit": "フェノール類", "type": "choice", "q": "フェノールの水溶液に過剰の臭素水を加えた際の現象と、生成する物質の名称として正しいものはどれか。", "choices": ["溶液の色が消え、橙色沈殿（p-ブロモフェノール）が生じる", "溶液の色が消え、無色の気体（臭化水素）が発生する", "溶液が青紫色に変化し、黒色沈殿（アニリンブラック）が生じる", "溶液の色が消え、白色沈殿（2,4,6-トリブロモフェノール）が生じる"], "answer": 3, "hint": "フェノールの反応性は非常に高く、複数の水素原子が置換されます。", "book": "有機編 第11講"}, {"id": "q-org-105", "lecture": "org-11", "unit": "フェノール類", "type": "choice", "q": "ナトリウムフェノキシドの水溶液に二酸化炭素を通じたときに起こる反応の化学反応式として、正しいものはどれか。", "choices": ["C6H5OH + NaHCO3 -> C6H5ONa + CO2 + H2O", "2C6H5ONa + CO2 + H2O -> 2C6H5OH + Na2CO3", "C6H5ONa + CO2 -> C6H5COONa", "C6H5ONa + CO2 + H2O -> C6H5OH + NaHCO3"], "answer": 3, "hint": "酸の強さを比較し、弱酸の遊離が起こるかどうかを確認しましょう。", "book": "有機編 第11講"}, {"id": "q-org-106", "lecture": "org-11", "unit": "フェノール類", "type": "choice", "q": "フェノールの物理的・化学的性質に関する記述として正しいものはどれか。", "choices": ["常温において無色の液体であり、特有の臭気を持つ", "水に極めて溶けやすく、その水溶液は強い酸性を示す", "金属ナトリウムと反応して、水素を発生しながらナトリウムフェノキシドとなる", "空気中に放置しても酸化されにくく、長期保存しても色は変化しない"], "answer": 2, "hint": "アルコールと同様にナトリウムと反応するか、また融点や保存時の変化を思い出しましょう。", "book": "有機編 第11講"}, {"id": "q-org-107", "lecture": "org-12", "unit": "芳香族アミン", "type": "choice", "q": "アニリンの性質に関する記述として最も適当なものはどれか。", "choices": ["水によく溶け、その水溶液は強い塩基性を示す", "硫酸塩の水溶液に水酸化ナトリウムを加えると、再び硫酸塩が析出する", "アニリンのヒドロキシ基は、フェノールと同様に酸性を示す", "希塩酸を加えると、塩を作って水に溶ける"], "answer": 3, "hint": "アニリンはアミノ基を持つため、酸とどのような反応をするか考えましょう。", "book": "有機編 第12講"}, {"id": "q-org-108", "lecture": "org-12", "unit": "芳香族アミン", "type": "choice", "q": "アニリンの検出反応として、さらし粉水溶液を用いた際に見られる特有の色はどれか。", "choices": ["青紫色", "鮮紅色", "濃紺色", "赤紫色"], "answer": 3, "hint": "さらし粉（次亜塩素酸カルシウム）による酸化反応に注目します。", "book": "有機編 第12講"}, {"id": "q-org-109", "lecture": "org-12", "unit": "芳香族アミン", "type": "choice", "q": "実験室において、ニトロベンゼンからアニリンを合成する際、還元剤として用いられる組み合わせはどれか。", "choices": ["白金と水素", "水素化ホウ素ナトリウムとメタノール", "酸化マンガン(IV)と濃塩酸", "スズと濃塩酸"], "answer": 3, "hint": "ニトロ基をアミノ基に還元するための強酸性条件下の還元剤を選びます。", "book": "有機編 第12講"}, {"id": "q-org-110", "lecture": "org-12", "unit": "芳香族アミン", "type": "choice", "q": "塩化ベンゼンジアゾニウムの水溶液に、ナトリウムフェノキシドの水溶液を冷却しながら加えたときに生成する物質はどれか。", "choices": ["アゾベンゼン", "p-アミノアゾベンゼン", "p-ヒドロキシアゾベンゼン", "ニトロベンゼン"], "answer": 2, "hint": "ジアゾ基とフェノキシドが結合するカップリング反応です。", "book": "有機編 第12講"}, {"id": "q-org-111", "lecture": "org-13", "unit": "糖類（単糖・二糖）", "type": "choice", "q": "スクロース（ショ糖）が、還元性を示さない理由として最も適当なものはどれか。", "choices": ["分子内にヒドロキシ基を全く持たないため。", "グルコースのアルデヒド基がケトン基に変化しているため。", "グルコースとフルクトースの互いのヘミアセタール構造の部分で結合しているため。", "二糖類の中で唯一、分子構造が直鎖状で固定されており、環を開くことができないため。"], "answer": 2, "hint": "還元性を示すには、水溶液中で環状構造が開き、アルデヒド基が生じる必要があります。", "book": "有機編 第13講"}, {"id": "q-org-112", "lecture": "org-13", "unit": "糖類（単糖・二糖）", "type": "choice", "q": "マルトース（麦芽糖）とセロビオースに関する記述として正しいものはどれか。", "choices": ["マルトースは還元性を示すが、セロビオースは還元性を示さない。", "マルトースを水溶性、セロビオースを脂溶性の二糖類と呼んで区別する。", "いずれもデンプンをアミラーゼで加水分解することによって得られる。", "マルトースはα-グルコース2分子が結合し、セロビオースはβ-グルコース2分子が結合したものである。"], "answer": 3, "hint": "どちらもグルコース2分子からなる二糖ですが、結合しているグルコースの向き（α型かβ型か）が異なります。", "book": "有機編 第13講"}, {"id": "q-org-113", "lecture": "org-13", "unit": "糖類（単糖・二糖）", "type": "choice", "q": "グルコースの水溶液中での状態について、正しい説明はどれか。", "choices": ["すべてが直鎖状の構造をとって存在している。", "α型、β型、鎖状構造の3つが平衡状態で存在し、鎖状構造の割合が最も大きい。", "α型とβ型の環状構造が平衡状態で存在し、鎖状構造は全く存在しない。", "α型、鎖状構造、β型の3つが平衡状態にあり、鎖状構造のアルデヒド基により還元性を示す。"], "answer": 3, "hint": "水溶液中では大半が環状構造ですが、ごく一部が鎖状構造になっています。", "book": "有機編 第13講"}, {"id": "q-org-114", "lecture": "org-13", "unit": "糖類（単糖・二糖）", "type": "choice", "q": "乳糖（ラクトース）を希硫酸を用いて完全に加水分解したとき、得られる単糖の組み合わせとして正しいものはどれか。", "choices": ["グルコースのみ", "グルコースとフルクトース", "グルコースとガラクトース", "ガラクトースとフルクトース"], "answer": 2, "hint": "ラクトースは哺乳類の乳に含まれる糖で、2種類の異なる単糖から構成されています。", "book": "有機編 第13講"}, {"id": "q-org-115", "lecture": "org-14", "unit": "多糖類", "type": "choice", "q": "アミロースとアミロペクチンに関する記述として正しいものはどれか。", "choices": ["アミロースは枝分かれが多く、アミロペクチンは直鎖状の構造を持つ。", "アミロースはヨウ素デンプン反応で赤紫色を示し、アミロペクチンは濃青色を示す。", "アミロースは熱水に溶けにくいが、アミロペクチンは熱水に溶けやすい。", "アミロースはα-グルコースが1,4-グリコシド結合でつながった直鎖状の部分が多く、らせん構造を作る。"], "answer": 3, "hint": "デンプンの構成成分のうち、直鎖状でらせんを作りやすい方と、枝分かれが多い方の特徴を整理しましょう。", "book": "有機編 第14講"}, {"id": "q-org-116", "lecture": "org-14", "unit": "多糖類", "type": "choice", "q": "デンプンを酸や酵素で加水分解していく過程において、デンプンより分子量が小さくマルトースより分子量が大きい中間生成物の名称はどれか。", "choices": ["グリコーゲン", "セルロース", "スクロース", "デキストリン"], "answer": 3, "hint": "デンプンが完全にグルコースになる前の、段階的な分解産物の総称です。", "book": "有機編 第14講"}, {"id": "q-org-117", "lecture": "org-14", "unit": "多糖類", "type": "numeric", "q": "デンプン162gを完全に加水分解してすべてグルコースにしたとき、得られるグルコースは何gか。原子量はH=1.0、C=12、O=16とする。", "answer": 180, "tolerance": 0.9, "hint": "デンプンの繰り返し単位に水分子が加わってグルコースになる反応式を立てましょう。", "book": "有機編 第14講"}, {"id": "q-org-118", "lecture": "org-14", "unit": "多糖類", "type": "choice", "q": "セルロースとその誘導体に関する記述として最も適当なものはどれか。", "choices": ["セルロースをシュバイツァー試薬に溶かした後、希硫酸中に押し出したものはアセテートと呼ばれる。", "セルロースのヒドロキシ基の一部を酢酸エステル化したものは、ニトロセルロースと呼ばれる。", "ニトロセルロースにショウノウを加えて練り合わせたものは、セルロイドと呼ばれる。", "セルロースはβ-グルコースが1,6-グリコシド結合でつながった構造を持つ。"], "answer": 2, "hint": "セルロースの加工品（再生繊維や半合成繊維）の名前と製法、材料の組み合わせを確認しましょう。", "book": "有機編 第14講"}, {"id": "q-org-119", "lecture": "org-15", "unit": "アミノ酸", "type": "choice", "q": "分子内にアミノ基を2個、カルボキシ基を1個持つ塩基性アミノ酸はどれか。", "choices": ["グルタミン酸", "アラニン", "セリン", "リシン"], "answer": 3, "hint": "側鎖にアミノ基（-NH2）を持つアミノ酸を探しましょう。", "book": "有機編 第15講"}, {"id": "q-org-120", "lecture": "org-15", "unit": "アミノ酸", "type": "choice", "q": "アミノ酸の検出反応の一つで、試料溶液に水酸化ナトリウム水溶液を加えて加熱し、その後酢酸で酸性にしてから酢酸鉛(II)水溶液を加えると黒色沈殿が生じるアミノ酸はどれか。", "choices": ["グリシン", "フェニルアラニン", "メチオニン", "システイン"], "answer": 3, "hint": "硫黄（S）原子を含み、硫化物イオン（S2-）を遊離しやすいアミノ酸を選びます。", "book": "有機編 第15講"}, {"id": "q-org-121", "lecture": "org-15", "unit": "アミノ酸", "type": "choice", "q": "アミノ酸の検出に用いられるニンヒドリン反応において、多くのアミノ酸が呈する一般的な色はどれか。", "choices": ["黄色", "赤褐色", "赤紫色〜青紫色", "銀白色"], "answer": 2, "hint": "この反応はアミノ基（-NH2）を持つ化合物の検出に非常に感度が良いことで知られています。", "book": "有機編 第15講"}, {"id": "q-org-122", "lecture": "org-15", "unit": "アミノ酸", "type": "choice", "q": "2分子のアミノ酸から1分子の水が取れて結合し、ジペプチドが生成する反応の名称として最も適切なものはどれか。", "choices": ["付加反応", "置換反応", "中和反応", "脱水縮合"], "answer": 3, "hint": "分子間で水（H2O）が取れて結合する形式に注目します。", "book": "有機編 第15講"}, {"id": "q-org-123", "lecture": "org-16", "unit": "タンパク質", "type": "choice", "q": "タンパク質水溶液に水銀(II)イオンや鉛(II)イオンなどの重金属イオンを加えたときに起こる現象の説明として、正しいものはどれか。", "choices": ["タンパク質のアミノ酸配列（一次構造）が切断される。", "タンパク質の溶解度が増し、より透明な溶液になる。", "酵素としての活性が飛躍的に向上する。", "水素結合やイオン結合が切れて高次構造が崩れ、変性する。"], "answer": 3, "hint": "重金属イオンはタンパク質の親水基などと結合し、その立体構造を維持できなくさせます。", "book": "有機編 第16講"}, {"id": "q-org-124", "lecture": "org-16", "unit": "タンパク質", "type": "choice", "q": "タンパク質に濃硝酸を加えて加熱すると黄色になり、冷却後にアンモニア水を加えて塩基性にすると橙黄色に変化する反応（キサントプロテイン反応）を陽性とするアミノ酸はどれか。", "choices": ["アラニン", "バリン", "メチオニン", "チロシン"], "answer": 3, "hint": "ベンゼン環（芳香環）を持つアミノ酸がこの反応を示します。", "book": "有機編 第16講"}, {"id": "q-org-125", "lecture": "org-16", "unit": "タンパク質", "type": "choice", "q": "酵素が特定の立体構造を持つ基質にのみ作用し、それ以外の物質には作用しないという性質を何と呼ぶか。", "choices": ["最適温度", "失活", "触媒作用", "基質特異性"], "answer": 3, "hint": "「特定の相手」だけを選ぶという言葉を考えます。", "book": "有機編 第16講"}, {"id": "q-org-126", "lecture": "org-16", "unit": "タンパク質", "type": "choice", "q": "グリシン(Gly)とアラニン(Ala)の2種類のみで構成されるあるトリペプチド1分子を完全に加水分解した。このとき、得られるアミノ酸の「Gly : Ala」の物質量比として、理論上あり得ないものはどれか。", "choices": ["1 : 2", "2 : 1", "3 : 0", "1 : 1"], "answer": 3, "hint": "トリペプチドは3分子のアミノ酸から構成されていることに着目してください。", "book": "有機編 第16講"}, {"id": "q-org-127", "lecture": "org-17", "unit": "油脂とせっけん", "type": "choice", "q": "液体の油脂に水素を付加させて固体状にした「硬化油」の製法に関する記述として正しいものはどれか。", "choices": ["酸素を吹き込み、不飽和脂肪酸の二重結合を酸化させて架橋構造を作る。", "濃硫酸を加えて加熱し、グリセリンと脂肪酸の鎖の間で脱水反応を促進させる。", "天然の飽和脂肪酸を多量に含む固体脂肪を高温で融解し、急冷して作る。", "ニッケル触媒を用いて、脂肪酸鎖の炭素-炭素二重結合に水素を付加させる。"], "answer": 3, "hint": "不飽和結合を飽和結合に変える反応を考えましょう。", "book": "有機編 第17講"}, {"id": "q-org-128", "lecture": "org-17", "unit": "油脂とせっけん", "type": "choice", "q": "せっけんの製造工程において、けん化後の混合液に多量の食塩を加える「塩析」を行う目的として最も適切なものはどれか。", "choices": ["反応液中に残った未反応の水酸化ナトリウムを中和して除去するため。", "副生成物であるグリセリンを塩素化物に変えて沈殿させるため。", "せっけん分子の親水基を疎水基に変化させて、洗浄力を高めるため。", "せっけんの溶解度を下げて、コロイド溶液から固体として分離するため。"], "answer": 3, "hint": "親水基を持つコロイド粒子に多量の電解質を加えるとどうなるかを思い出しましょう。", "book": "有機編 第17講"}, {"id": "q-org-129", "lecture": "org-17", "unit": "油脂とせっけん", "type": "choice", "q": "せっけんを硬水（Ca2+やMg2+を多く含む水）で使用すると、洗浄力が著しく低下するのはなぜか。", "choices": ["硬水中の金属イオンが触媒となり、せっけんのエステル結合が加水分解されるため。", "カルシウムイオンの影響で溶液のpHが酸性に偏り、せっけんが脂肪酸に戻るため。", "金属イオンがせっけんのミセル内部に入り込み、油汚れを取り込む隙間をなくすため。", "せっけんが2価の金属イオンと反応し、水に不溶の塩を形成して沈殿するため。"], "answer": 3, "hint": "せっけんの陰イオンと2価の陽イオンが反応した後の状態を考えましょう。", "book": "有機編 第17講"}, {"id": "q-org-130", "lecture": "org-17", "unit": "油脂とせっけん", "type": "numeric", "q": "ある油脂の分子量は762であり、その1分子中には炭素-炭素二重結合が3個存在する。この油脂のヨウ素価を求めよ。原子量：I=127", "answer": 100, "tolerance": 0.5, "hint": "ヨウ素価の定義は「油脂100gに付加するヨウ素の質量(g)」です。", "book": "有機編 第17講"}, {"id": "q-org-131", "lecture": "org-18", "unit": "合成高分子", "type": "choice", "q": "次の高分子化合物のうち、単量体が「縮合重合」することによって生成するものはどれか。", "choices": ["ポリスチレン", "ポリプロピレン", "ポリ塩化ビニル", "ナイロン66"], "answer": 3, "hint": "分子間で水などの簡単な分子が取れながら結合していく反応を選びます。", "book": "有機編 第18講"}, {"id": "q-org-132", "lecture": "org-18", "unit": "合成高分子", "type": "choice", "q": "合成繊維ビニロンの製造工程に関する記述として正しいものはどれか。", "choices": ["ビニルアルコールを単量体として付加重合させ、得られた高分子をアセトンで処理する。", "酢酸ビニルとホルムアルデヒドを共重合させた後、強酸を加えてアセタール化する。", "ポリビニルアルコールを濃厚な水酸化ナトリウム水溶液中で加熱し、繊維状に押し出す。", "ポリ酢酸ビニルをけん化して得られるポリビニルアルコールを、ホルムアルデヒドで処理する。"], "answer": 3, "hint": "単体では不安定なビニルアルコールの代わりに何を用いるかと、最後のアセタール化の工程を考えます。", "book": "有機編 第18講"}, {"id": "q-org-133", "lecture": "org-18", "unit": "合成高分子", "type": "choice", "q": "加熱した際の性質に基づいて分類したとき、他の3つとは異なる性質（熱硬化性）を持つ樹脂はどれか。", "choices": ["ポリエチレン", "ポリエチレンテレフタラート", "ポリスチレン", "フェノール樹脂"], "answer": 3, "hint": "加熱すると一度硬化した後は軟化せず、三次元網目構造を持つ樹脂を選びます。", "book": "有機編 第18講"}, {"id": "q-org-134", "lecture": "org-18", "unit": "合成高分子", "type": "choice", "q": "ポリエチレンテレフタラート（PET）の単量体として用いられる2つの化合物の組み合わせはどれか。", "choices": ["アジピン酸とエチレングリコール", "テレフタル酸とヘキサメチレンジアミン", "フタル酸とエチレン", "テレフタル酸とエチレングリコール"], "answer": 3, "hint": "PETはエステル結合によってつながったポリエステルの一種です。", "book": "有機編 第18講"}, {"id": "q-org-135", "lecture": "org-19", "unit": "イオン交換樹脂", "type": "choice", "q": "強酸性陽イオン交換樹脂（R-SO3H）の能力が低下した際、再びH+型に戻して再生するために用いる最も適切な試薬はどれか。", "choices": ["希塩酸", "水酸化ナトリウム水溶液", "塩化ナトリウム水溶液", "蒸留水"], "answer": 0, "hint": "樹脂に結合している他の陽イオンを、多量のH+で追い出す必要があります。", "book": "有機編 第19講"}, {"id": "q-org-136", "lecture": "org-19", "unit": "イオン交換樹脂", "type": "choice", "q": "イオン交換樹脂を用いて純水（脱イオン水）を製造する際、一般的に陽イオン交換樹脂を先に通し、次に陰イオン交換樹脂を通す。この理由として適切なものはどれか。", "choices": ["先に陰イオン交換樹脂を通すと、水中の金属イオンが水酸化物として沈殿し、樹脂が詰まる恐れがあるため。", "先に陽イオン交換樹脂を通さないと、水中の塩化物イオンが樹脂と反応して塩素ガスが発生するため。", "陽イオン交換樹脂は酸に強く、陰イオン交換樹脂は塩基に強いため、この順番でしか反応が進行しないため。", "逆の順番にすると、樹脂の母体であるポリスチレンが加水分解を受けて溶け出してしまうため。"], "answer": 0, "hint": "アルカリ性条件下で金属イオンがどう変化するかを考えましょう。", "book": "有機編 第19講"}, {"id": "q-org-137", "lecture": "org-19", "unit": "イオン交換樹脂", "type": "numeric", "q": "H+型の陽イオン交換樹脂を充填したカラムに、0.050 mol/LのKCl水溶液200 mLをすべて通した。流出液に含まれるH+の物質量は何molか。有効数字2桁で答えよ。", "answer": 0.01, "tolerance": 0.0001, "hint": "交換されるイオンの価数と、溶液中のK+の物質量に注目しましょう。", "book": "有機編 第19講"}, {"id": "q-org-138", "lecture": "org-19", "unit": "イオン交換樹脂", "type": "choice", "q": "強塩基性陰イオン交換樹脂の交換基として適した構造はどれか。", "choices": ["-NH2", "-N+(CH3)3 OH-", "-SO3H", "-COOH"], "answer": 1, "hint": "強塩基性を示すのは、水酸化物イオンを電離しやすい第四級アンモニウム基です。", "book": "有機編 第19講"}, {"id": "q-org-139", "lecture": "org-20", "unit": "ナイロンとゴム", "type": "choice", "q": "ナイロン6の合成に関する説明として正しいものはどれか。", "choices": ["アジピン酸とヘキサメチレンジアミンを、縮合重合させることで得られる。", "テレフタル酸とエチレングリコールを、縮合重合させることで得られる。", "イプシロン-カプロラクタムを、開環重合させることで得られる。", "アクリロニトリルを、付加重合させることで得られる。"], "answer": 2, "hint": "ナイロン6は、単一の環状モノマーからつくられます。", "book": "有機編 第20講"}, {"id": "q-org-140", "lecture": "org-20", "unit": "ナイロンとゴム", "type": "choice", "q": "生ゴム（天然ゴム）に数%の硫黄を加えて加熱する「加硫」を行う目的として、最も適切なものはどれか。", "choices": ["分子内の二重結合をすべて飽和させ、熱に対する流動性を高めるため。", "重合度を小さくし、有機溶媒に溶けやすくするため。", "シス型の構造をトランス型に変化させ、プラスチックのような硬さを与えるため。", "高分子鎖の間に橋かけ構造を作り、弾性や強度を高めるため。"], "answer": 3, "hint": "硫黄原子が分子鎖の間でどのような役割を果たすか考えましょう。", "book": "有機編 第20講"}, {"id": "q-org-141", "lecture": "org-20", "unit": "ナイロンとゴム", "type": "choice", "q": "天然ゴムの主成分であるポリイソプレンの構造について、正しい説明はどれか。", "choices": ["イソプレンがトランス型で1,4-付加重合した構造をもつ。", "イソプレンがシス型で1,4-付加重合した構造をもつ。", "2-クロロ-1,3-ブタジエンがシス型で付加重合した構造をもつ。", "ブタジエンとスチレンが交互に共重合した構造をもつ。"], "answer": 1, "hint": "天然ゴムは弾性に富むシス型、グッタペルカは硬いトランス型です。", "book": "有機編 第20講"}, {"id": "q-org-142", "lecture": "org-20", "unit": "ナイロンとゴム", "type": "choice", "q": "合成ゴムの一種である「クロロプレンゴム（ネオプレン）」の単量体として正しいものはどれか。", "choices": ["CH2=CH-CN", "CH2=C(CH3)-CH=CH2", "CH2=C(Cl)-CH=CH2", "CH2=CH-CH=CH2"], "answer": 2, "hint": "イソプレンのメチル基が塩素原子に置き換わった構造を探しましょう。", "book": "有機編 第20講"}]}]};
